UPDATE "library_manuals" SET "title" = 'Сердечно-сосудистая система', "annotation" = 'Сердечно-сосудистая система: АФО у детей, пульс и АД, симптомы и уход, врождённые пороки сердца, ревматизм, кардиты, недостаточность кровообращения, СЛР, режим и диеты. С методическими указаниями, алгоритмами манипуляций и самоконтролем.',
  "published" = v.j, "draft" = CASE WHEN "draft_changed" THEN "draft" ELSE v.j END, "updated_at" = now()
FROM (SELECT $json${"sections":[{"id":"ccc-s00","title":"Методические указания","blocks":[{"id":"ccc-m-001","text":{"text":"Методичка собрана для самостоятельной подготовки студентов по теме «Сестринский уход при заболеваниях сердечно-сосудистой системы». Материал сведён по темам; у каждого факта стоит метка источника (буква в квадратных скобках — расшифровка в разделе «Источники» в конце), расхождения между источниками отмечены прямо в тексте."}},{"id":"ccc-m-002","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Главное — методика","text":"Медсестру оценивают не по пересказу теории, а по тому, **как она выполняет манипуляцию и оказывает доврачебную помощь**. Поэтому алгоритмы (пульс, АД, водный баланс, помощь при сердечной астме и т.д.) вынесены в отдельные карточки с порядком шагов — их нужно знать дословно и отработать на фантоме и друг на друге. Подробный разбор методики с оснащением, типичными ошибками и задачами — в методичке «Методика сестринского наблюдения и ухода при заболеваниях органов кровообращения» этой же кафедры."}},{"id":"ccc-m-003","heading":{"text":"Цели изучения темы","level":2}},{"id":"ccc-m-004","text":{"text":"**Знать:**\n- анатомо-физиологические особенности ССС у детей и возрастные нормы пульса и АД;\n- основные симптомы заболеваний ССС и проблемы пациента;\n- клинику врождённых пороков сердца, ревматизма, кардитов, недостаточности кровообращения;\n- принципы лечения, режимы и лечебные диеты (№ 10, 10а, 10с, 10и).\n\n**Уметь:**\n- исследовать пульс и измерять АД по методике, оценивать результат по возрастной норме;\n- вести учёт водного баланса и выявлять скрытые отёки;\n- оказывать доврачебную помощь при стенокардии, гипертоническом кризе, сердечной астме и отёке лёгких, обмороке, коллапсе, одышечно-цианотическом приступе;\n- проводить базовую сердечно-лёгочную реанимацию;\n- готовить пациента к инструментальным исследованиям и транспортировать его."}},{"id":"ccc-m-005","heading":{"text":"Как работать с методичкой","level":2}},{"id":"ccc-m-006","checklist":{"title":"Порядок подготовки к занятию","ordered":true,"steps":["Прочитать тему целиком и выписать незнакомые термины.","Разобрать таблицы возрастных норм: пульс, АД, формулы систолического и диастолического АД.","Выучить алгоритмы манипуляций (карточки с шагами) — порядок шагов и обоснование каждого.","Отработать манипуляции в паре: пульс на лучевой и сонной артерии, АД на руке и на ноге.","Пройти самоконтроль в конце методички; ошибки — повод вернуться к теме.","Решить ситуационные задачи в методичке по методике ухода."]}}]},{"id":"ccc-s02","title":"1. Анатомо-физиологические особенности (АФО) ССС у детей","blocks":[{"id":"ccc-004","text":{"text":"У ребёнка относительно большое сердце, широкие сосуды, частый пульс и низкое АД; кровообращение находится в более благоприятных условиях, чем у взрослых [Е, З]."}},{"id":"ccc-005","heading":{"text":"Перестройка кровообращения после рождения","level":2}},{"id":"ccc-006","text":{"text":"- С первого вдоха прекращается плацентарное кровообращение, в полном объёме включается малый круг кровообращения [Е, З].\n- Закрываются фетальные коммуникации: боталлов (артериальный) проток, овальное отверстие, аранциев (венозный) проток — соединяет пупочную и воротную вены; запустевают пупочные сосуды [Е, З].\n- Параллельно работавшие правый и левый желудочки переключаются на последовательную работу; растут сердечный выброс и системное сосудистое сопротивление [З].\n- В первые 2 дня жизни возможен сброс (шунтирование) крови — зависит от состояния лёгких и гемодинамики [Е].\n- Функционально закрытый артериальный проток может вновь открыться при нарушении дыхания [З]."}},{"id":"ccc-007","table":{"caption":"","header":true,"rows":[{"cells":["Структура","Функциональное закрытие","Анатомическое закрытие"]},{"cells":["Артериальный (боталлов) проток","через 10–15 ч после родов [Е]; после первых дыхательных движений [З]","в течение нескольких недель [Е]; к 6-й неделе [З]. У недоношенных может функционировать от нескольких недель до месяца [Е]"]},{"cells":["Венозный (аранциев) проток","—","к 2–3 мес [З]"]},{"cells":["Овальное окно","—","к 5–6 мес [З]"]}]}},{"id":"ccc-008","heading":{"text":"Сердце","level":2}},{"id":"ccc-009","text":{"text":"- **Масса.** У новорождённого сердце относительно велико: 0,8% массы тела (у взрослого 0,4% [З]), абсолютная масса 20–25 г [З]. К 3 годам — 0,5%, т.е. как у взрослого [Е]. Границы сердца у новорождённого значительно шире, чем у взрослых [З].\n- **Рост.** Неравномерный: наиболее энергично в первые 2 года и в период полового созревания [Е, З]. До 2 лет интенсивнее растут предсердия, с 10 лет — желудочки; во все периоды увеличение объёма сердца отстаёт от роста тела [Е]. К 15 годам объём сердца увеличивается в 7 раз, а окружность аорты — только в 3 раза [З].\n- **Форма.** У новорождённого округлая (желудочки развиты недостаточно, предсердия сравнительно велики); к 6 годам — овальная, как у взрослого [Е].\n- **Положение.** Из-за высокого стояния диафрагмы у новорождённых и детей первых 2 лет сердце лежит горизонтально (поперечно) и выше; к 2–3 годам — косое [Е]; примерно к 5 годам по мере роста лёгких и опускания диафрагмы — более вертикальное [З].\n- **Сердечный толчок.** До 2 лет — в IV межреберье, старше 2 лет — в V межреберье [З].\n- **Стенки желудочков.** У новорождённого правый и левый почти одинаковой толщины (около 5 мм [З]); потом левый утолщается сильнее из-за большей нагрузки [Е, З].\n- **Миокард** новорождённого: очень тонкие, слабо отграниченные мышечные волокна; с возрастом — тканевая дифференцировка, развитие соединительной ткани [З].\n- **Сообщения между отделами.** В первые недели и месяцы сохраняются овальное отверстие, артериальный проток, артериоло-венулярные анастомозы в малом круге. Кровь идёт из камеры с высоким давлением в камеру с низким. При лёгочной гипертензии или дыхательной недостаточности давление справа превышает давление в большом круге → шунт справа налево, смешивание артериальной и венозной крови [Е].\n- **Работоспособность** детского сердца выше, чем у взрослого: относительно большое количество крови и интенсивный обмен предъявляют к нему значительные требования [Е]."}},{"id":"ccc-010","heading":{"text":"Сосуды","level":2}},{"id":"ccc-011","text":{"text":"- Артерии у детей относительно широкие. Просвет вен при рождении примерно равен просвету артерий; вены растут быстрее и к 15–16 годам вдвое шире артерий [Е, З]. Переход к прямостоянию и ходьбе усиливает развитие венозной сети, особенно нижней половины тела [З].\n- С возрастом развиваются коллатерали, клапанный аппарат вен, растёт число и длина капилляров [З].\n- **Аорта и лёгочная артерия.** [Е]: аорта до 10 лет уже лёгочной артерии, затем диаметры сравниваются, в пубертате аорта шире. [З]: до 12 лет ствол лёгочной артерии шире аорты, с 12 лет одинаковы.\n- **Мышечная оболочка** при рождении развита только в артериях малого круга; в артериях большого круга формируется с 5 лет. Поэтому до 5–7 лет редко бывает гипертензия, а у детей первых месяцев легко развивается гипертензия в малом круге [З].\n- **Капилляры** хорошо развиты, проницаемость выше, чем у взрослых. Ширина и обилие капилляров предрасполагают к застою крови — одна из причин частых пневмоний и остеомиелитов на 1-м году [Е].\n- **Скорость кровотока** высокая (у новорождённых почти вдвое выше, чем у взрослых), с возрастом замедляется из-за удлинения сосудистого русла и урежения ЧСС [Е, З]. Один кругооборот крови: новорождённый — 12 с, 3 года — 15 с, взрослый — 22 с [З].\n- Неравномерный рост длины сосудов объясняет частые (функциональные) шумы над сердцем [З]."}},{"id":"ccc-012","heading":{"text":"Возрастная структура патологии [З]","level":2}},{"id":"ccc-013","text":{"text":"- На 1-м году среди впервые выявленных болезней сердца преобладают ВПС, старше 1 года — приобретённые болезни; приобретённые доминируют у школьников.\n- У новорождённых в основе патологии — дисметаболические расстройства на фоне гипоксии, токсикоза, эндокринных заболеваний матери. До 3 лет незрелый иммунитет и частые ОРЗ ведут к инфекционным (чаще вирусным) кардитам; старше — неревматические и ревматические поражения.\n- В пубертате часты функциональные расстройства (аритмии, колебания АД; ВСД, «юношеское сердце», юношеская гипертония) — обратимы, связаны с нейроэндокринной регуляцией и дисгармонией роста, но требуют дообследования."}}]},{"id":"ccc-s03","title":"2. Пульс и артериальное давление","blocks":[{"id":"ccc-x-001","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Методика","text":"Пульс и АД — первые манипуляции, которые проверяют на занятии. Алгоритмы ниже выучить по шагам и отработать в паре; оснащение, обоснование каждого шага и типичные ошибки разобраны в методичке «Методика сестринского наблюдения и ухода при заболеваниях органов кровообращения»."}},{"id":"ccc-014","text":{"text":"Норма у взрослого — пульс 60–90 в минуту и АД 100–139 / 60–89 мм рт. ст. [О]; у детей пульс чаще, а АД ниже, и тем сильнее, чем младше ребёнок [Е, З]."}},{"id":"ccc-015","heading":{"text":"Артериальный пульс [О]","level":2}},{"id":"ccc-016","text":{"text":"Артериальный пульс (лат. *pulsus* — удар, толчок) — периодические колебания стенок артерий из-за изменения их кровенаполнения при работе сердца."}},{"id":"ccc-017","text":{"text":"**На лучевой артерии** (периферический пульс; артерия пальпируется между шиловидным отростком лучевой кости и сухожилием внутренней лучевой мышцы):"}},{"id":"ccc-018","checklist":{"title":"Алгоритм: пульс на лучевой артерии [О]","ordered":true,"steps":["Одновременно охватить оба запястья так, чтобы подушечки указательного и среднего пальцев лежали на проекции лучевой артерии.","Прижимать артерию к кости с разной силой — волна ощущается как расширение и спадение артерии.","Сравнить пульс на обеих руках; при симметрии дальше исследуют на одной.","При ритмичном пульсе считать 15 с и умножить на 4; при аритмии — считать 1 мин.","Записать в температурный лист красными точками по шкале пульса."]}},{"id":"ccc-019","text":{"text":"При подозрении на облитерирующее заболевание сосудов ног (чаще — атеросклероз аорты и её ветвей) пульс ищут на бедренных, подколенных артериях и сосудах стопы."}},{"id":"ccc-020","text":{"text":"**На сонной артерии** (при тяжёлом состоянии): найти кадык, сместить указательный и средний пальцы кнаружи — между хрящом и мышцей, нащупать пульсацию. Только с одной стороны и без пережатия: рефлексогенная зона, опасно резкое урежение ЧСС вплоть до потери сознания."}},{"id":"ccc-021","text":{"text":"**Свойства пульса:**"}},{"id":"ccc-022","table":{"caption":"","header":true,"rows":[{"cells":["Свойство","Чем определяется","Варианты"]},{"cells":["Ритмичность","Равенство интервалов между волнами","Ритмичный (p. regularis), аритмичный (p. irregularis). При мерцательной аритмии — дефицит пульса: ЧСС 98 при аускультации, пульс 78 → дефицит 20"]},{"cells":["Частота","Число волн в минуту","Норма 60–90; менее 60 — редкий, более 90 — частый"]},{"cells":["Наполнение","Объём крови в артерии, систолический объём","Полный (p. plenus), пустой (p. vacuus), нитевидный (p. filiformis) — сразу сообщить врачу"]},{"cells":["Напряжение","Сила для полного пережатия артерии; ориентир АД","Удовлетворительного напряжения; напряжённый, твёрдый (p. durus) — при высоком АД; мягкий (p. mollis) — при низком"]},{"cells":["Величина","Наполнение + напряжение, амплитуда колебания стенки","Большой (p. magnus), малый (p. parvus)"]},{"cells":["Форма","Скорость изменения объёма артерии","Скорый (p. celer) — недостаточность аортального клапана, нервное возбуждение; медленный (p. tardus) — аортальный стеноз"]}]}},{"id":"ccc-023","text":{"text":"Частота зависит от пола, возраста, температуры, нагрузки: самый частый — у новорождённых; у женщин чаще, чем у мужчин; реже у спортсменов и пожилых; учащается стоя, при нагрузке, лихорадке, сердечной недостаточности, аритмиях. Неодинаковый пульс на руках — при аномалиях, сужении, сдавлении лучевой, плечевой или подключичной артерии; тогда работу сердца оценивают по той руке, где пульс лучше."}},{"id":"ccc-024","heading":{"text":"Пульс у детей","level":2}},{"id":"ccc-025","text":{"text":"- Чаще, чем у взрослых: сердечная мышца сокращается быстрее, влияние блуждающего нерва меньше, обмен выше. Потребность тканей в крови покрывается частотой сокращений, а не ударным объёмом [Е].\n- Лабилен: крик, плач, напряжение, лихорадка заметно учащают его. Характерна дыхательная аритмия: на вдохе чаще, на выдохе реже [Е].\n- У маленьких детей пульс считают во сне — на сонной или височной артерии, на большом родничке или при аускультации сердца; у старших — на лучевой артерии [З]. Пульс и АД измеряют в покое, лучше во сне, и записывают в температурный лист [З]."}},{"id":"ccc-026","heading":{"text":"Возрастные нормы пульса и АД","level":2}},{"id":"ccc-027","table":{"caption":"","header":true,"rows":[{"cells":["Возраст","Пульс, уд/мин [З]","ЧСС, уд/мин [Е]","АД сист. / диаст., мм рт. ст. [З]"]},{"cells":["Новорождённый","120–140","120–140","76 / — (по [Е] систолическое 65–85)"]},{"cells":["1 год","120","110–120","80–90 / 40–45"]},{"cells":["3 года","105","—","95 / 45"]},{"cells":["5 лет","100","100","100 / 50"]},{"cells":["8 лет","90","—","105 / 55"]},{"cells":["10 лет","85","90","110 / 60"]},{"cells":["12 лет","80","80–70 (12–13 лет)","115 / 70"]},{"cells":["15 лет","70","—","120 / 80"]}]}},{"id":"ccc-028","heading":{"text":"АД у детей","level":2}},{"id":"ccc-029","text":{"text":"- Низкое АД объясняется малым объёмом левого желудочка, широким просветом сосудов (аорты) и эластичностью артериальных стенок [Е, З]. Рост АД с возрастом идёт параллельно росту скорости пульсовой волны и тонуса сосудов мышечного типа [З].\n- АД лабильно, зависит от пола и физического развития: лёжа и во сне снижается, при психической и физической нагрузке повышается [З].\n- **Формулы систолического (максимального) АД** [Е, З]: до 1 года — 76 + 2n (n — месяцы; 76 — среднее систолическое АД новорождённого); старше года — 100 + n (n — годы), допускаются колебания ±15.\n- **Диастолическое АД** — расходится: [Е] 2/3–1/2 систолического; [З] ½ систолического + 10. Верхняя граница диастолического у подростков — 80 [З].\n- **Оценка по центильным таблицам** [Е]: норма — 10–90-я центиль; 90–95-я — пограничная гипертензия; 10–5-я — пограничная гипотензия; выше 95-й — артериальная гипертензия; ниже 5-й — артериальная гипотензия.\n- **Манжетка.** Набор шириной 3, 5, 7, 12 и 18 см; манжетка захватывает ~2/3 предплечья или бедра. Узкая завышает показатели, широкая — занижает [Е]. При взрослой манжете 13 см у ребёнка систолическое корректируют в сторону увеличения, диастолическое — уменьшения [З].\n- **АД на ногах** измеряют обязательно (особенно при подозрении на порок) [Е, З]: стетоскоп — над подколенной артерией; на ногах АД выше, чем на руках, примерно на 10 [Е] (на 10–20 — в разделе о коарктации [Е]). У взрослых АД в бедренной артерии в норме существенно не отличается от плечевой; измеряют лёжа на животе, манжета на бедре, выслушивают подколенную ямку [О]."}},{"id":"ccc-030","heading":{"text":"Артериальное давление: понятия и измерение [О]","level":2}},{"id":"ccc-031","text":{"text":"- **Систолическое (максимальное)** — возникает вслед за систолой левого желудочка, максимум пульсовой волны. **Диастолическое** — поддерживается тонусом артерий в диастолу. **Пульсовое** — разница между ними.\n- АД зависит от сердечного выброса, общего периферического сопротивления, ОЦК, ЧСС.\n- **Методы:** прямой (датчик в сосуд при катетеризации); непрямой аускультативный метод Н.С. Короткова (1905) сфигмоманометром (аппарат Рива-Роччи, тонометр); осциллографический (ещё оценивает сосудистую стенку, тонус, скорость кровотока, а при компьютерной обработке — ударный и минутный объёмы, периферическое сопротивление). В эпидемиологических исследованиях — ртутные сфигмоманометры с «плавающим нулём».\n- **Правила измерения** (ДАГ-1, 2000; ВНОК): лёжа или сидя на стуле с прямой спинкой, ноги не скрещены, рука на столе (иначе АД растёт из-за изометрического сокращения); через 1–2 ч после еды и не ранее 1 ч после кофе и курения; манжета охватывает не менее 80% окружности и 2/3 длины плеча; не менее 3 измерений с интервалом ≥ 5 мин, берут среднее двух последних. (По классической методике ВОЗ в историю болезни заносят самое низкое из трёх.)"}},{"id":"ccc-033","checklist":{"title":"Алгоритм измерения АД [О]","ordered":true,"steps":["Пациент лёжа или сидя, рука свободно, ладонью вверх.","Манжету накладывают на уровне сердца (середина ≈ IV межреберье), нижний край на 2–2,5 см выше локтевого сгиба, под неё проходит один палец; середина баллона — над артерией. Смещение манжеты от уровня сердца на 1 см меняет АД на 0,8 мм рт. ст. (ниже сердца — завышение, выше — занижение).","Соединить трубку манжеты с манометром.","Пальцы левой руки — на плечевой артерии в локтевой ямке; быстро накачать воздух и заметить уровень исчезновения пульсации.","Выпустить воздух, поставить фонендоскоп в локтевую ямку.","Быстро накачать на 20–30 мм рт. ст. выше уровня исчезновения пульса (медленное нагнетание нарушает венозный отток, вызывает боль и «смазывает» тоны).","Спускать воздух со скоростью 2 мм рт. ст. в секунду (медленнее — занижение АД), выслушивая артерию.","Появление первых тонов Короткова — систолическое АД; исчезновение — диастолическое.","Выпустить весь воздух, разъединить трубки, снять манжету.","Записать в температурный лист красными столбиками; значение округляют до ближайших 2 мм рт. ст."]}},{"id":"ccc-034","heading":{"text":"Нормы и классификации АД у взрослых [О]","level":2}},{"id":"ccc-035","text":{"text":"Повышенным считают АД от 140/90 (артериальная гипертензия), пониженным — ниже 100/60 (гипотензия). Резкое повышение АД с сильной головной болью, головокружением, тошнотой и рвотой — гипертонический криз."}},{"id":"ccc-036","text":{"text":"Табл. 13-1. Классификация уровней АД у взрослых старше 18 лет (ВОЗ, МОАГ, JNC-VI, ДАГ-1; 2001). При попадании систолического и диастолического в разные категории ставят более высокую."}},{"id":"ccc-037","table":{"caption":"","header":true,"rows":[{"cells":["Категория","Систолическое, мм рт. ст.","Диастолическое, мм рт. ст."]},{"cells":["Оптимальное","< 120","< 80"]},{"cells":["Нормальное","< 130","< 85"]},{"cells":["Повышенное нормальное","130–139","85–89"]},{"cells":["АГ 1-й степени","140–159","90–99"]},{"cells":["АГ 2-й степени","160–179","100–109"]},{"cells":["АГ 3-й степени","≥ 180","≥ 110"]},{"cells":["Изолированная систолическая АГ","≥ 140","< 90"]}]}},{"id":"ccc-038","text":{"text":"Табл. 13-2. Классификация JNC-VII (2003): нормальное АД — < 120 / < 80; предгипертензия — 120–139 / 80–89; АГ 1-й степени — 140–159 / 90–99; АГ 2-й степени — ≥ 160 / ≥ 100. Предгипертензия — не болезнь, а показание к оздоровлению образа жизни; все лица с АД выше 159/99 должны получать антигипертензивную терапию. Границы нормы условны и смещаются к всё меньшим величинам по данным исследований инсультов и инфарктов."}},{"id":"ccc-039","text":{"text":"**Суточное мониторирование АД** (СМАД): автоматическая манжета, прибор на плече; по Короткову работают 38% аппаратов, осциллометрически — 30%, остальные — комбинированно. Интервалы: 15 мин днём, 30 мин ночью. Норма: днём 135/85, ночью 120/70 (ночное снижение на 10–20%). АГ диагностируют при среднесуточном ≥ 135/85, дневном ≥ 140/90, ночном ≥ 125/75."}}]},{"id":"ccc-s04","title":"3. Общие симптомы заболеваний ССС, наблюдение и уход","blocks":[{"id":"ccc-x-002","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Методика","text":"В этой теме главное для медсестры — доврачебная помощь и положение пациента: при сердечной астме — сидя с опущенными ногами, при обмороке, коллапсе и гипотензии — лёжа с приподнятыми ногами. Алгоритм помощи при отёке лёгких и учёт водного баланса — дословно."}},{"id":"ccc-040","text":{"text":"Чаще всего больные жалуются на боли в грудной клетке, сердцебиение, одышку, удушье, отёки и перебои в работе сердца [О]. Кардиология (греч. *kardia* — сердце, *logos* — учение) — раздел внутренних болезней об этиологии, патогенезе, клинике, диагностике, профилактике и лечении болезней ССС [О]."}},{"id":"ccc-041","text":{"text":"Наблюдение и уход идут в двух направлениях [О]:"}},{"id":"ccc-042","text":{"text":"- **Общие мероприятия** — нужны любым больным: наблюдение за состоянием, термометрия, контроль пульса и АД, температурный лист, личная гигиена, подача судна.\n- **Специальные мероприятия** — помощь при боли в области сердца, острой и хронической сердечной недостаточности, отёках, нарушениях ритма."}},{"id":"ccc-043","heading":{"text":"Симптомы у детей [З]","level":2}},{"id":"ccc-044","text":{"text":"- Слабость, утомляемость при нагрузке (ходьба, игры, лестница): ребёнок просится на руки, бросает игру; грудной перестаёт активно сосать, ест с перерывами.\n- Одышка, цианоз или бледность, снижение аппетита, похудание, замедление роста — типичные признаки недостаточности кровообращения. Повторные простуды и пневмонии связаны с переполнением малого круга.\n- При некоторых ВПС — гипоксические (одышечно-цианотичные) приступы: внезапная бледность, резкая одышка, беспокойство, синюшность, возможны потеря сознания и остановка дыхания; приступы повторяются.\n- При нарушениях ритма и проводимости в приступ — беспокойство, одышка, холодный пот, иногда рвота; старшие дети жалуются на сердцебиение.\n- Боли в сердце у детей чаще связаны с сосудистым тонусом, а не с патологией сердца (исключение — острый неревматический кардит). При изменениях АД — головная боль, головокружение.\n- Заподозрить болезнь сердца позволяют: учащение или урежение сокращений, расширение границ сердца, шумы, изменение тонов, деформация грудной клетки, изменения АД и пульса. Сейчас болезни выявляют рано благодаря профосмотрам, ЭКГ и ЭхоКГ."}},{"id":"ccc-045","heading":{"text":"Артериальная гипертензия [О]","level":2}},{"id":"ccc-046","text":{"text":"- Строго соблюдать лечебно-охранительный режим: отрицательные эмоции, нервно-психические нагрузки и плохой сон утяжеляют болезнь.\n- **Гипертонический криз** опасен нарушением мозгового и коронарного кровообращения, нужны врач и антигипертензивные препараты. До прихода врача: полный покой, свежий воздух, горячие ножные ванны и тёплые ванны для рук (37–40 °C)."}},{"id":"ccc-047","heading":{"text":"Артериальная гипотензия [О]","level":2}},{"id":"ccc-048","text":{"text":"Бывает у здоровых (особенно астеников) или как симптом снижения сердечного выброса, сосудистого тонуса, ОЦК (инфаркт миокарда, кровотечения, шок, коллапс). При острой гипотензии: уложить, приподнять ножной конец кровати (приток крови к мозгу), лекарства по назначению врача."}},{"id":"ccc-049","heading":{"text":"Боли в области сердца и стенокардия [О]","level":2}},{"id":"ccc-050","text":{"text":"- **Кардиалгия** — боли не сердечного происхождения: сухой плеврит, остеохондроз, межрёберная невралгия, миозит, грыжа пищеводного отверстия диафрагмы. Боли со стороны системы кровообращения дают также перикард, аорта, невротические состояния.\n- **Стенокардия («грудная жаба», *angina pectoris*)** — сужение коронарных артерий атеросклерозом (иногда + спазм). Потребность миокарда в кислороде превышает коронарный кровоток → ишемия, гипоксия; недоокисленные продукты обмена раздражают нервные окончания → боль.\n- Типичный приступ: провоцируется физической или эмоциональной нагрузкой; боль за грудиной, давящая, жгучая, сжимающая, со страхом смерти; отдаёт в левое плечо, руку, левую половину шеи, нижнюю челюсть; длится 1–10 мин, проходит в покое или через 1–3 мин после нитроглицерина под язык.\n- Помощь: полный покой, нитроглицерин под язык (в возвышенном положении), реже — горчичники на область сердца.\n- У детей боли в сердце обычно связаны с нервным перенапряжением и расстройством нервной регуляции: препараты валерианы, пустырника, валокордин, иногда нитроглицерин под язык; согреть ребёнка, позвать врача [З]."}},{"id":"ccc-051","heading":{"text":"Инфаркт миокарда [О]","level":2}},{"id":"ccc-052","text":{"text":"Некроз участка сердечной мышцы. Типичный (болевой, ангинозный) вариант: чрезвычайно сильная загрудинная боль, не снимается покоем и нитроглицерином, длится более 30 мин (до нескольких часов); страх смерти, удушье, резкая слабость, падение АД. В первые часы — срочная госпитализация в палату интенсивной терапии с мониторированием и готовностью к реанимации. Первые дни — строгий постельный режим: контроль постели и белья, все гигиенические процедуры, кормление, подача судна и мочеприёмника. Питание — диета №10и (см. раздел 9)."}},{"id":"ccc-053","heading":{"text":"Одышка, сердечная астма, отёк лёгких [О]","level":2}},{"id":"ccc-054","text":{"text":"- **Одышка** — признак сердечной недостаточности (прогрессирующее снижение сократимости миокарда, застой в малом круге, задержка жидкости). Сначала при нагрузке и волнении, потом и в покое.\n- **Удушье (сердечная астма)** — внезапный тяжёлый приступ одышки с шумным дыханием, чаще ночью (тонус блуждающего нерва сужает коронарные сосуды); больной садится — **ортопноэ** (греч. *orthos* — прямой, *pnoe* — дыхание): сидя с опущенными ногами кровь депонируется в сосудах живота и ног, малый круг разгружается. Причины: резкое снижение сократимости при инфаркте, тяжёлом миокардите, перегрузке (криз, неадекватная нагрузка). Отличие: астма Траубе — удушье центрального генеза при атеросклерозе сосудов дыхательного центра, смена позы не помогает.\n- **Отёк лёгких** — самое тяжёлое проявление СН: жидкая часть крови пропотевает в альвеолы; к сердечной астме добавляются клокочущее дыхание и розовая пенистая мокрота.\n- **Помощь при одышке:** покой, положение сидя/полусидя, снять стесняющую одежду, свежий воздух, нитроглицерин (при отсутствии противопоказаний) или антигипертензивные при высоком АД по назначению врача."}},{"id":"ccc-056","checklist":{"title":"Алгоритм помощи при сердечной астме и отёке лёгких [О]","ordered":true,"steps":["Немедленно вызвать врача.","Положение сидя (ортопноэ).","Нитроглицерин, если систолическое АД не менее 100 мм рт. ст.","Оксигенотерапия с пеногасителем через маску или носовой катетер.","Аспирация пенистой мокроты электроотсосом.","Венозные жгуты на обе ноги на 15 см ниже паховой складки (можно и на руки): артериальный пульс ниже жгута сохраняется, конечность цианотичная, но не белая; через 15–20 мин ослабить.","Снимать жгуты последовательно и медленно, с одной конечности за другой.","Возможны кровопускание и горячие ножные ванны для разгрузки малого круга.","По назначению врача в/в: наркотические анальгетики, мочегонные, ингибиторы АПФ, сердечные гликозиды и др."]}},{"id":"ccc-057","heading":{"text":"Отёки при сердечной недостаточности [О]","level":2}},{"id":"ccc-058","text":{"text":"- Результат застоя в большом круге и задержки жидкости. У ходячих — на ногах, у лежачих — на крестце, пояснице, лопатках. Кожа гладкая, блестящая, натянутая; от надавливания остаётся долго не расправляющаяся ямка.\n- В запущенных случаях транссудат в полостях: **асцит** (брюшная полость), **гидроторакс** (плевральная), **гидроперикард** (перикард), **анасарка** — распространённый отёк подкожной клетчатки (от *hydor ana sarcus* — «жидкость по всему телу»).\n- На ранних стадиях отёки скрытые: быстрая прибавка массы и снижение диуреза → ежедневно контролируют водный баланс и взвешивают. Суточный диурез в норме 1,5–2 л — 70–80% всей потреблённой жидкости. Меньше 70–80% — отрицательный диурез (жидкость задерживается); больше выпитого — положительный (схождение отёков, диуретики).\n- Больные на постельном режиме, получающие мочегонные, должны иметь мочеприёмники и судна.\n- При большом асците — абдоминальная пункция (парацентез); быстрое удаление большого объёма жидкости может вызвать коллапс.\n- При ХСН на постельном режиме в местах отёков (крестец, поясница, лопатки) возникают трофические нарушения — особенно важна профилактика пролежней."}},{"id":"ccc-059","text":{"text":"**Наблюдение за водным балансом** [О]. Цели: выявить скрытые отёки, измерить суточный диурез, оценить терапию (прежде всего мочегонную). Оснащение: медицинские весы, чистая сухая банка 2–3 л, два градуированных сосуда, лист учёта водного баланса, температурный лист."}},{"id":"ccc-060","checklist":{"title":"Алгоритм учёта водного баланса [О]","ordered":true,"steps":["Накануне предупредить больного и объяснить правила сбора мочи и записей.","В 6 ч утра разбудить — пациент мочится в унитаз (или катетером); эту порцию не учитывают.","Все последующие порции до 6 ч следующего утра включительно — в банку.","В течение дня учитывать введённую жидкость в мл: выпитую (первые блюда — 75% жидкости) и парентеральную.","Измерить суточную мочу градуированным сосудом.","Записать в температурный лист."]}},{"id":"ccc-061","text":{"text":"**Оценка:** ожидаемый диурез = вся поступившая жидкость (включая воду пищи и растворы) × 0,8. Выделено меньше расчётного — баланс отрицательный (отёки нарастают, диуретики неэффективны); больше — положительный (отёки сходят, лечение эффективно)."}}]},{"id":"ccc-s05","title":"4. Врождённые пороки сердца (ВПС)","blocks":[{"id":"ccc-062","text":{"text":"ВПС — аномалии сердца и магистральных сосудов, возникающие на 2–8-й неделе эмбрионального развития; единственный радикальный способ лечения большинства — операция [З, Е]."}},{"id":"ccc-063","heading":{"text":"Эпидемиология и причины","level":2}},{"id":"ccc-064","text":{"text":"- Среди пороков развития внутренних органов — 2-е место (после аномалий ЦНС), 0,3–0,8% новорождённых. Ежегодно умирают 5–6 детей на 10 тыс. населения: 55% — на 1-м году, 85% — к 5 годам [З].\n- В структуре врождённых пороков развития чаще всего — пороки ССС; среди них преобладают дефекты перегородок, ОАП, коарктация аорты, стеноз лёгочной артерии, тетрада Фалло [Е].\n- Причины: в большинстве случаев — генетические факторы, хромосомные аномалии, их сочетание с внешними факторами; алкоголизм, сахарный диабет, тиреотоксикоз у родителей; тератогенные вирусы (краснуха, грипп) и лекарства в первые 3 мес беременности [З]. Экзогенные тератогены: внутриутробные инфекции, алкоголь, лекарства, профвредности, экология, радиация и рентгеновское облучение [Е].\n- Порок может проявиться сразу после рождения или через некоторое время [З]."}},{"id":"ccc-065","heading":{"text":"Фазы течения","level":2}},{"id":"ccc-066","text":{"text":"1. Фаза первичной адаптации — первые 2–3 года: приспособление к нарушениям гемодинамики, компенсаторная гиперфункция сердца, часто с признаками острой сердечной недостаточности; при небольших нарушениях клиника слабая [Е]. По [З] — с первых дней жизни, состояние затем улучшается.\n2. Фаза относительной компенсации — с 3–4 лет: улучшаются общее состояние, физическое развитие, двигательная активность за счёт устойчивой гиперфункции и гипертрофии миокарда [Е].\n3. Терминальная фаза — чаще к 3–12 годам, когда исчерпаны компенсационные возможности: хроническая СН, склеротические изменения в сердце и органах, заканчивается смертью [Е]; расстройство кровообращения, не поддающееся лечению, дыхательная и сердечно-сосудистая недостаточность, нарушение мозгового кровообращения [З]. Благодаря хирургии сейчас встречается редко [Е]."}},{"id":"ccc-067","heading":{"text":"Классификация","level":2}},{"id":"ccc-068","table":{"caption":"","header":true,"rows":[{"cells":["Группа","Суть","Пороки"]},{"cells":["С обогащением (переполнением) малого круга","Патологическое сообщение между кругами, сброс артериальной крови в венозное русло (лево-правый шунт)","ДМПП, ДМЖП, ОАП, АВ-канал; ТМС — по [Е]. Дефекты перегородок + ОАП = 65–70% всех ВПС [З]"]},{"cells":["С обеднением малого круга","Сужение лёгочной артерии, часто + сброс из правого желудочка в большой круг (право-левый шунт); смешение крови → цианоз, одышка","Стеноз лёгочной артерии, тетрада Фалло; ТМС — по [З]"]},{"cells":["С обеднением большого круга [Е] / с нормальным лёгочным кровообращением [З]","Нет цианоза и нарушений газообмена, резкое обеднение большого круга","Коарктация аорты, стеноз аорты; также недостаточность клапанов, аномалии расположения сердца и сосудов [З]"]}]}},{"id":"ccc-069","heading":{"text":"Сводка по порокам","level":2}},{"id":"ccc-070","table":{"caption":"","header":true,"rows":[{"cells":["Порок","Гемодинамика","Шум и тоны","Операция [З]"]},{"cells":["ДМПП","Сброс левое → правое предсердие, перегрузка правого желудочка","Негрубый систолический во II–III межреберье слева; расщепление/акцент II тона на лёгочной артерии","Ушивание/пластика в 3–5 лет"]},{"cells":["ДМЖП","Сброс левый → правый желудочек; при высоком лёгочном сопротивлении — комплекс Эйзенменгера","Грубый систолический (лучше в 5-й точке [Е]; у IV ребра слева и справа от грудины [З]), систолическое дрожание","Ушивание/пластика в 3–5 лет (по показаниям раньше)"]},{"cells":["ОАП","Сброс аорта → лёгочная артерия в систолу и диастолу, перегрузка левых камер","Систоло-диастолический «машинный» шум во II межреберье слева","Перевязка или рассечение протока в 1–3 года"]},{"cells":["Стеноз лёгочной артерии","Препятствие оттоку из правого желудочка, его гипертрофия","Грубый систолический во II межреберье; II тон на лёгочной артерии ослаблен, I на верхушке усилен","Только в тяжёлых случаях — рассечение створок по комиссурам"]},{"cells":["Тетрада Фалло","Часть венозной крови из правого желудочка через ДМЖП идёт в аорту → цианоз","Грубый (или умеренный) систолический вдоль левого края грудины; II тон на лёгочной артерии ослаблен","Соустье между сосудами кругов, ликвидация стеноза, пластика ДМЖП"]},{"cells":["Транспозиция магистральных сосудов","Аорта от правого желудочка, лёгочная артерия от левого — два разобщённых круга","Нехарактерна; систолический шум и акцент II тона лишь у ⅓","Двухэтапная: в грудном возрасте анастомоз, в 5–7 лет перемещение сосудов"]},{"cells":["Коарктация аорты","Сужение аорты ниже левой подключичной артерии; АД выше сужения высокое, ниже — низкое","Систолический в III–IV межреберье слева, на сосуды шеи и спину; акцент II тона на аорте","Иссечение участка или протезирование в 4–6 лет"]},{"cells":["Стеноз аорты","Препятствие выбросу из левого желудочка, его гипертрофия","Грубый систолический во II межреберье справа, на сосуды шеи; дрожание там же","Рассечение створок по комиссурам в 6–10 лет"]}]}},{"id":"ccc-071","heading":{"text":"ВПС с обогащением малого круга","level":2}},{"id":"ccc-072","text":{"text":"**Дефект межпредсердной перегородки (ДМПП)** — один из самых частых ВПС [Е]; по [З] — самая частая аномалия сердца."}},{"id":"ccc-073","text":{"text":"- 15% дефектов — у устья верхней полой вены и синусового узла; реже множественные дефекты и полное отсутствие перегородки; в 10–20% — в сочетании с пролапсом митрального клапана [Е].\n- Гемодинамика: сброс из левого предсердия в правое → увеличение объёма крови малого круга (гиперволемия), диастолическая перегрузка и дилатация правого желудочка [Е, З]. Сброс обусловлен разницей давлений предсердий, более высоким положением левого предсердия, большой растяжимостью правого желудочка [Е]. Разница давлений предсердий у здоровых детей — 5 мм рт. ст.; она влияет на сброс лишь при малых дефектах, при больших — решает растяжимость желудочков в диастолу [З]. Лёгочная гипертензия → обратный сброс и цианоз [Е].\n- Клиника: часто бессимптомно; на 1-м году распознаётся у 40%, остальные — в 2–7 лет [Е] (2–5 лет [З]). Открытое овальное окно и малый срединный дефект часто не проявляются [З]. При большом сбросе — отставание в массе, повторные респираторные заболевания и пневмонии, одышка, утомляемость, боли в сердце. Иногда «сердечный горб» [З]. Границы сердца расширены в поперечнике и вправо. Негрубый короткий систолический шум во II–III межреберье слева. II тон на лёгочной артерии расщеплён [Е]; при развитии лёгочной гипертензии расщепление исчезает, появляется акцент II тона и диастолический шум Грехема — Стилла (недостаточность клапанов лёгочной артерии) [Е].\n- Рентген: расширение сердца в поперечнике за счёт правого желудочка, увеличение правого предсердия, выбухание дуги лёгочной артерии, сглаженная «талия», расширение корней, усиление сосудистого рисунка. ЭКГ: гипертрофия правых отделов, неполная блокада правой ножки пучка Гиса [З].\n- **Низко расположенный ДМПП** протекает тяжелее, часто вместе с ДМЖП образует **общий открытый атриовентрикулярный канал** (все 4 камеры сообщаются). Дети резко отстают в развитии, ⅓ из них — с болезнью Дауна. Одышка, кашель, слабость; бледность и цианоз губ, выраженный «сердечный горб», пульсация в эпигастрии, акцент II тона, ритм галопа, грубый скребущий шум в III–IV межреберье слева, проводится на все точки и спину; застойные хрипы. Рентген — шаровидное сердце; ЭКГ — перегрузка всех камер, больше правых. Операция сопряжена с большим риском [З]."}},{"id":"ccc-074","text":{"text":"**Дефект межжелудочковой перегородки (ДМЖП)** — 17–30% сердечных аномалий [Е]."}},{"id":"ccc-075","text":{"text":"- Локализация: мембранозная часть — 75%, мышечная — 10% (**болезнь Толочинова — Роже**); мышечные дефекты бывают множественными и часто закрываются сами [Е]. Болезнь Роже практически не нарушает гемодинамику: только длительный интенсивный (иногда грубый) систолический шум на уровне IV ребра; рентген — округлое сердце, ЭКГ — умеренно повышена активность обоих желудочков [З].\n- Высокий (мембранозный) ДМЖП: шум сразу после рождения, гемодинамические расстройства на 2–4-м месяце: гипертрофия правых отделов, лёгочная гипертензия, затем гипертрофия левых, смена направления сброса, цианоз и СН [З].\n- Типы по величине лево-правого шунта [Е]:\n  - **I тип** — дефект < 0,5 см², сброс < 25% ударного объёма; давление в правом желудочке и малом круге не меняется, гипертензии нет, клиники нет; лечение и операция не нужны.\n  - **II тип** — 0,5–1,0 см², сброс до 50%, среднее повышение давления в малом круге; возможны отставание в развитии, застойная СН, рецидивирующие нижнедолевые пневмонии.\n  - **III тип** — > 1,0 см², сброс > 50%: частые бронхолёгочные заболевания, нарушения роста, СН; при высоком лёгочном сопротивлении — одышка в покое, боли в груди, цианоз, кровохарканье. Без операции большинство умирает в детстве и подростковом возрасте."}},{"id":"ccc-076","text":{"text":"**Открытый артериальный (боталлов) проток (ОАП)** — внутриутробно соединяет лёгочную артерию и аорту."}},{"id":"ccc-077","text":{"text":"- Гемодинамика: сброс из аорты в лёгочную артерию и в систолу, и в диастолу → переполнение малого круга и перегрузка левых камер; при лёгочной гипертензии — и правого желудочка. Объём шунта растёт с диаметром протока; когда лёгочное сопротивление превышает системное, шунт меняет направление (при больших протоках) [Е]. Узкий проток обычно без расстройств — случайная находка; широкий быстро даёт лёгочную гипертензию [З].\n- Клиника: обычно в конце 1-го или на 2–3-м году; до этого развитие нормальное, 1-я фаза лёгкая [Е]. Одышка, утомляемость, боли в сердце [З]. Пульс ускоренный и высокий; максимальное АД нормальное или повышено, минимальное низкое, особенно стоя [Е] (до 0 стоя [З]). Границы сердца расширены влево и вверх. «Машинный» систоло-диастолический шум во II межреберье слева, проводится на верхушку, шейные сосуды, аорту, межлопаточное пространство [Е]. Ослабление или исчезновение шума — признак лёгочной гипертензии (II тон на лёгочной артерии усилен) [Е]: сначала исчезает диастолический компонент, в терминальной фазе — и систолический [З].\n- Рентген: умеренное увеличение левых отделов и аорты, расширение корней, усиление лёгочного рисунка; ЭКГ — изолированная гипертрофия левого желудочка, иногда предсердия [З].\n- У новорождённых для закрытия протока применяют ингибитор простагландинов индометацин [Е]. Послеоперационная летальность при перевязке протока — 1–3% [З]."}},{"id":"ccc-078","text":{"text":"**Полная транспозиция магистральных сосудов (ТМС)** — самый тяжёлый ВПС [Е]."}},{"id":"ccc-079","text":{"text":"- Жизнь возможна только при компенсирующих коммуникациях (ОАП, ДМПП, ДМЖП); чаще у мальчиков. Постоянный цианоз с рождения, границы сердца расширены в поперечнике и вверх; аускультация зависит от коммуникаций. При присоединении СН без операции 85% умирают на 1-м году [Е].\n- По [З] клиника идентична тетраде Фалло: рано нарастающий цианоз, одышка, кардиомегалия, «сердечный горб», «барабанные палочки», НК. Рентген: сердце овальное, с приподнятой верхушкой и подчёркнутой «талией», лёгочный рисунок усилен. ЭКГ — гипертрофия правых отделов."}},{"id":"ccc-080","heading":{"text":"ВПС с обеднением малого круга","level":2}},{"id":"ccc-081","text":{"text":"**Стеноз лёгочной артерии (СЛА)**"}},{"id":"ccc-082","text":{"text":"- Варианты: чаще клапанный, реже под- и надклапанный, стеноз ветвей; подклапанный часто входит в сложный ВПС [Е].\n- Повышение систолического давления и гипертрофия правого желудочка. Градиент давления желудочек/лёгочная артерия: лёгкая степень < 30, средняя 30–80, тяжёлая > 80 мм рт. ст. [Е].\n- Клиника: слабый стеноз может не проявляться (иногда утомляемость); при выраженном — одышка, бледность, боли в сердце [Е], перебои и сердцебиение [З]; цианоз — в терминальной фазе (при хронической СН). Границы сердца расширены в поперечнике [Е] / вправо [З]. Систолическое дрожание у верхней части левого края грудины и надгрудинной вырезки. Грубый систолический шум во II межреберье слева [Е] (в [З] — «справа», проводится в подключичную область, на сонные артерии и спину); II тон на лёгочной артерии ослаблен или отсутствует, I на верхушке усилен.\n- Рентген и ЭхоКГ: увеличение правого желудочка, постстенотическое расширение лёгочной артерии; ЭКГ — гипертрофия правых отделов [З].\n- Основные причины смерти — СН и инфекционный эндокардит [Е]."}},{"id":"ccc-083","text":{"text":"**Тетрада Фалло (ТФ)** — самый частый «синий» порок."}},{"id":"ccc-084","text":{"text":"- 4 аномалии: ДМЖП (высокий), аорта над дефектом (декстрапозиция), гипертрофия правого желудочка, стеноз лёгочной артерии [Е, З].\n- Формы [Е]: крайний вариант по типу общего ложного артериального ствола (лёгочный ствол не работает): тяжёлое состояние, ранний цианоз, без операции 80% погибают в 1-й месяц; классический вариант — цианоз чаще в 2–3 мес, ранняя одышка, заметная при кормлении и движении.\n- Клиника: цианоз и одышка при кормлении или крике, затем в покое; акроцианоз [З]. С рождения — грубый систолический шум вдоль левого края грудины (от ДМЖП); границы сердца нормальные или слегка расширены влево [Е] (вправо — [З]); II тон над лёгочной артерией ослаблен [З]. Отставание в физическом развитии.\n- **Поза:** ребёнок присаживается на корточки, обхватив колени, или ложится ничком — так меньше одышка [Е].\n- Из-за застоя в капиллярах — пальцы «барабанные палочки», ногти «часовые стёкла» [Е, З]; «сердечный горб», выраженное плоскостопие [З].\n- **Одышечно-цианотические (гипоксемические) приступы** у младших детей: на фоне обычного цианоза — одышка, тахикардия, усиление цианоза [Е]. Механизм: спазм выходного отдела правого желудочка → вся венозная кровь в аорту → резкая гипоксия ЦНС [З].\n- Кровь: тяжёлая полицитемия или относительная (часто железодефицитная) анемия [Е].\n- Рентген: сердце в форме «башмачка» (подчёркнутая «талия», приподнятая округлая верхушка), увеличение правых отделов, расширение аорты, лёгочные поля повышенно прозрачны, рисунок обеднён. ЭКГ — гипертрофия и перегрузка правых отделов, выраженная гипоксия миокарда [З]."}},{"id":"ccc-085","heading":{"text":"ВПС с обеднением большого круга","level":2}},{"id":"ccc-086","text":{"text":"**Коарктация аорты (КА)** — сужение или полное закрытие просвета аорты на ограниченном участке, обычно ниже левой подключичной артерии."}},{"id":"ccc-087","text":{"text":"- В 98% — в области отхождения артериального протока. Предуктивная (инфантильная) форма — сужение до ОАП, сочетается с ДМЖП, двустворчатым аортальным клапаном, ТМС; постдуктивная (взрослая) — проток закрыт, прогноз лучше [Е].\n- Сопротивление току крови → систолическая перегрузка и гипертрофия левого желудочка со склерозом [З]. АД выше уровня коарктации повышено, большой градиент между руками и ногами, развиваются коллатерали к нижней части туловища [Е].\n- Клиника: у грудных — СН, низкая прибавка массы; у старших обычно бессимптомно, возможны утомляемость, слабость ног при беге, ишемические боли в животе; редко — перемежающаяся хромота, головные боли, боль в груди [Е]. По [З] жалобы поздние (синдром гипертонии и декомпенсации): головная боль, головокружение, шум в ушах, утомляемость, боли в животе и ногах; верхняя половина туловища развита лучше нижней.\n- **Классический признак** — разные пульс и АД на руках и ногах: гипертензия и напряжённый пульс на руках, ослабленный или отсутствующий пульс и низкое АД на ногах (в норме на ногах на 10–20 выше) [Е]. АД на руках до 250–300, на ногах иногда до 0; пульс напряжённый, редкий [З].\n- Выраженная пульсация сосудов верхней половины тела, усиленный верхушечный толчок, границы сердца расширены влево; систолический шум по левому краю грудины в III–IV межреберье на сосуды шеи и спину, акцент II тона на аорте [Е]; шум также над основанием сердца, у мечевидного отростка и в межлопаточном пространстве [З].\n- Рентген: расширение левых отделов, восходящей и нисходящей аорты, **узурация нижних краёв рёбер**. ЭКГ: брадикардия, перегрузка и гипертрофия левых отделов. ФКГ: веретенообразный (ромбовидный) шум стеноза на основании сердца [З]."}},{"id":"ccc-088","text":{"text":"**Аортальный стеноз (АС), стеноз устья аорты**"}},{"id":"ccc-089","text":{"text":"- Около 5% ВПС у детей; клапанный — ~80%, остальные — под- и надклапанный [Е].\n- Степени по градиенту давления желудочек/аорта: лёгкая < 50, средняя 50–80, тяжёлая > 80 мм рт. ст.; критический стеноз — с острой СН в грудном возрасте [Е].\n- При выраженном стенозе уже у грудных — тяжёлая левожелудочковая недостаточность; но чаще порок выявляется в школьном возрасте [Е] (5–15 лет, т.к. развитие и окраска кожи нормальные, жалобы в 5–10 лет [З]).\n- Жалобы: утомляемость, одышка, боли в сердце, головокружения, обмороки, удушье. Цианоза нет. Приподнимающийся (усиленный) верхушечный толчок, систолическое дрожание и грубый систолический шум во II межреберье справа, проводится на сосуды шеи (и на все точки, спину [З]). Брадикардия, низкое максимальное и пульсовое давление, левые отделы увеличены [Е]. Рентген в 3 проекциях и ЭКГ — гипертрофия и дилатация левого желудочка [З]."}},{"id":"ccc-090","text":{"text":"**Аномалии расположения сердца** [З]. Эктопия — сердце вне средостения: грудная (на передней поверхности грудной клетки, обнажено или частично покрыто кожей или перикардом) и абдоминальная (в брюшной полости через дефект диафрагмы)."}},{"id":"ccc-091","heading":{"text":"Осложнения и диагностика ВПС","level":2}},{"id":"ccc-092","text":{"text":"- Частые осложнения: инфекционный эндокардит, нарушения ритма, хронические бронхолёгочные заболевания, тромбозы, эмболии, кровоизлияния в мозг [Е].\n- Заподозрить ВПС: ранняя одышка (первые месяцы и годы), цианоз, отставание в физическом и психомоторном развитии, шумы в сердце [Е].\n- Окончательный диагноз: ЭКГ (гипертрофия предсердий и желудочков, нарушения ритма), рентгенография, УЗИ и ЭхоКГ (наличие, локализация и размер дефекта, величина и направление сброса, гипертрофия стенок, увеличение полостей), ангиография (локализация, протяжённость, степень сужения сосудов, заполнение полостей), по необходимости — катетеризация (зондирование) сердца [Е]."}},{"id":"ccc-093","heading":{"text":"Лечение ВПС","level":2}},{"id":"ccc-094","text":{"text":"- **Оперативное** — единственный способ для большинства ВПС; при малых дефектах без перегрузки сердца не показано. Наблюдение в кардиохирургическом центре. Радикальные операции нормализуют гемодинамику; паллиативные облегчают состояние и отдаляют летальный исход [Е].\n- Сроки: наиболее благоприятно — фаза относительной компенсации (3–12 лет); при больших пороках с перегрузкой — в 1–4 года; при СН и лёгочной гипертензии — немедленно [Е]. По [З] — в раннем возрасте (сроки по порокам — в сводной таблице). Возможно спонтанное закрытие ОАП, ДМПП, мышечного ДМЖП [Е].\n- Послеоперационная летальность: 1–3% при перевязке протока; при паллиативных и радикальных операциях на сложных и декомпенсированных пороках — до 25% [З].\n- **Консервативное** — две задачи [Е]: 1) неотложная помощь при острой СН и гипоксемических приступах; 2) профилактика и лечение осложнений (гипоксические поражения ЦНС, коагулопатии, аритмии, инфекционный эндокардит). При признаках СН — обязательная госпитализация. По [З]: сердечные гликозиды, диуретики, препараты калия, кислородо- и аэротерапия, при необходимости — управляемое дыхание.\n- **Гипоксемический приступ** [Е]: лёгкий, без потери сознания — кислород и седативные (седуксен, тазепам). Длительный тяжёлый с потерей сознания — промедол 0,2 мг/кг, коррекция ацидоза (кислород, 4% натрия гидрокарбонат 5 мл/кг), β-блокатор пропранолол 2–5 мг/кг (так в тексте [Е]; в [З] — 0,1–0,2 мг/кг в/в), оксигенотерапия с положительным давлением на выдохе 6–8 см вод. ст.; в крайне тяжёлом состоянии — ИВЛ; при судорогах — 4% натрия оксибутират 50–150 мг/кг (ещё и антигипоксант). **Сердечные гликозиды и мочегонные при приступе противопоказаны.** Схема [З] — в разделе 7.\n- **Аритмии** (нарушение АВ-проводимости, пароксизмальная предсердная тахикардия, желудочковая экстрасистолия) — базисная терапия [Е]: нейрометаболические (пирацетам, ноотропил, энцефабол, пикамилон), психостимуляторы (сиднокарб, дуплекс), центральные (амизил) и периферические (беллатаминал) холинолитики, сосудистые с ноотропным действием (трентал), ангиопротекторы (пармидин, кавинтон), адаптогены (элеутерококк, женьшень, лимонник); индивидуально — антиаритмики (хинидин, новокаинамид, ритмодан, лидокаин, морацизин, ритмонорм, анаприлин, обзидан, кордарон, нифедипин).\n- При цианотичных пороках гемоглобин и эритроциты должны быть выше нормы; «нормальные» цифры = относительная анемия → препараты железа и меди [Е]."}},{"id":"ccc-095","heading":{"text":"Режим, наблюдение, уход, профилактика ВПС [Е]","level":2}},{"id":"ccc-096","text":{"text":"- Противопоказаны тяжёлая физическая работа, спортивные секции, соревнования. Нагрузку подбирают функциональными пробами. Ограничивают при: сбросе > 50% ударного объёма; высокой лёгочной гипертензии; предсердных нарушениях ритма; частых бронхолёгочных заболеваниях; снижении функциональных возможностей сердца; усилении симптомов при нагрузке (диспноэ вплоть до правожелудочковой недостаточности). При право-левом шунте (все «синие» пороки) физические нагрузки противопоказаны. По результатам проб — ЛФК или физкультура в подготовительной группе под наблюдением.\n- Задачи поликлиники: раннее выявление, систематическое наблюдение, выбор с кардиохирургом срока операции, консервативная терапия, режим, оздоровление, реабилитация после операции.\n- Уход: правильный режим дня с максимумом свежего воздуха, рациональное питание, по показаниям ограничение соли и жидкости, защита от инфекций, щадящее закаливание.\n- Профилактика: ограждение беременной от неблагоприятных факторов (болезни, неполноценное питание, гипоксия, химические, радиационные и другие воздействия)."}}]},{"id":"ccc-s06","title":"5. Ревматизм (острая ревматическая лихорадка, ОРЛ)","blocks":[{"id":"ccc-097","text":{"text":"Ревматизм — системное воспалительное заболевание соединительной ткани с преимущественным поражением ССС (кардит, артрит, хорея, эритема кожи), склонное к рецидивам, прогрессированию и формированию пороков сердца [Е]. Синонимы: ревматическая лихорадка, болезнь Сокольского — Буйо; аутоиммунное воспаление соединительной ткани с преимущественным поражением сердца и суставов у генетически предрасположенных детей [З]."}},{"id":"ccc-098","heading":{"text":"Эпидемиология и этиология","level":2}},{"id":"ccc-099","text":{"text":"- Частота у детей 0,08%; болеют дети 7–15 лет, в 30% — семейный характер, у дошкольников практически не встречается [З].\n- Возбудитель — **β-гемолитический стрептококк группы А**. Связь с перенесённой ангиной, скарлатиной, обострением хронического тонзиллита, фарингитом, синуситом, отитом; возможна ассоциация стрептококка и вируса [Е]. Связь с острой или хронической носоглоточной инфекцией [З].\n- Одного стрептококка недостаточно: нужен гипериммунный ответ, свидетельствующий о генетической предрасположенности. Маркеры: антигены HLA — A11, B35, DR4, DR5, DR7 и аллоантиген В-лимфоцитов D8/17 [Е]; у 98% больных — гаплотипы D8/17 [З]."}},{"id":"ccc-100","heading":{"text":"Патогенез","level":2}},{"id":"ccc-101","text":{"text":"- В основе — иммунные реакции и иммунное (асептическое) воспаление. Повреждение сердца обусловлено двумя факторами: **антигенной мимикрией** (сходство антигенов возбудителя и тканей сердца) и **кардиотропностью токсинов** стрептококка [Е].\n- Три ведущих механизма [З]: 1) прямое повреждающее действие токсинов на сердце и другие органы; 2) нарушение иммуногенеза с аллергическими и аутоиммунными реакциями; 3) генетическая предрасположенность.\n- Токсины стрептококка (стрептолизин-О, ДНКаза, протеиназа, гиалуронидаза, стрептокиназа) → антитела (антистрептолизин-О, антистрептогиалуронидаза, антистрептокиназа). Из-за мимикрии антитела бьют и по сердцу — главные мишени миокард и эндокард. Повреждённая ткань становится антигеном → аутоантитела → аутоиммунный процесс [Е, З].\n- Иммунные комплексы (антиген + антитело + комплемент) фиксируются на стенках сосудов и повреждают их; выделяются медиаторы (гистамин, серотонин, брадикинин). Антикардиальные антитела связываются с клетками эндокарда → непрерывно-рецидивирующее и хроническое течение [З].\n- Латентное и рецидивирующее течение объясняют переходом стрептококка в безоболочечные L-формы, устойчивые к фагоцитозу и антибиотикам [З]."}},{"id":"ccc-102","heading":{"text":"Клиническая картина","level":2}},{"id":"ccc-103","text":{"text":"- У детей протекает острее и тяжелее, чем у взрослых; развивается через 1–2 недели после стрептококковой инфекции [Е].\n- Периоды [З]: латентный (2–4 нед после инфекции, бессимптомно или с явлениями перенесённой болезни); период основного симптомокомплекса (активная фаза; при верном лечении — переход в неактивную и выздоровление); возвратный ревматизм. Начало активной фазы в половине случаев острое (фебрильная температура, слабость, утомляемость, бледность, поражение сердца), в остальных — подострое и латентное.\n- **Ревмокардит** — ведущий синдром, определяет исход; изменения в сердце есть всегда, даже если впереди хорея или эритема [З]. Первичный — при первой атаке, возвратный — при повторных [Е]."}},{"id":"ccc-104","text":{"text":"**Миокардит** — практически у 100% [Е]:"}},{"id":"ccc-105","text":{"text":"- Редкий тяжёлый вариант: состояние тяжёлое, бледность, границы сердца расширены, верхушечный толчок ослаблен, тоны глухие, возможна НК.\n- У большинства — умеренный: состояние нарушено незначительно, упорная тахикардия (реже брадикардия), I тон приглушен, «мягкий» систолический шум на верхушке и в 5-й точке, небольшое расширение левой границы, НК нет.\n- ЭКГ: замедление предсердно-желудочковой проводимости, снижение амплитуды зубца T, смещение ST вниз, удлинение электрической систолы."}},{"id":"ccc-106","text":{"text":"**Эндокардит** — почти всегда с миокардитом; у 70% при первой атаке и 100% при повторной [Е]:"}},{"id":"ccc-107","text":{"text":"- Пристеночный, клапанный, тотальный (с выраженной интоксикацией, высокой СОЭ, яркими сдвигами в анализах).\n- При поражении клапанов — дующий шум. Чаще всего митральный клапан: грубый систолический шум на верхушке и в 5-й точке, проводится в подмышечную область. Аортальный (~10%): диастолический шум во II межреберье справа у края грудины. Не всегда слышно — иногда выявляется только при УЗИ сердца.\n- Исход: выздоровление или ревматический порок (недостаточность митрального клапана, стеноз митрального отверстия, недостаточность аортальных клапанов): при первой атаке — у 15–20%, при повторной — у 50%."}},{"id":"ccc-108","text":{"text":"**Перикардит** — изолированно редко, обычно присоединяется к эндомиокардиту [Е]:"}},{"id":"ccc-109","text":{"text":"- Сухой: отложение фибрина → шум трения перикарда (изменчивый, не связан с тонами, лучше в III–IV межреберье слева или над грудиной, усиливается при наклоне вперёд). Боль в сердце, усиливающаяся при вдохе и движениях; у грудных — приступы беспокойства, бледность, тахикардия, апноэ.\n- Экссудативный (сейчас обычно серозно-фиброзный с небольшим выпотом): одышка, тахикардия, тупые боли, глухие тоны, верхушечный толчок не определяется, границы тупости увеличены. ЭКГ: низкий вольтаж, ST ниже изолинии, отрицательный T."}},{"id":"ccc-110","text":{"text":"**Внесердечные проявления:**"}},{"id":"ccc-111","text":{"text":"- **Ревматический полиартрит/артралгии** — у 80% [З], в начале болезни. Крупные и средние суставы (коленные, голеностопные, локтевые, плечевые, лучезапястные): отёк, резкая болезненность, жар, гиперемия. Летучесть, симметричность, множественность; на фоне лечения за несколько дней проходит **без деформаций** (отличительная черта), рентген без изменений [Е, З]. Артралгия — боль без видимых изменений; при повторных атаках чаще именно она [З].\n- **Малая хорея** — у 12–17%, через 2–3 нед от начала [Е]. Триада: 1) гиперкинезы (непроизвольные порывистые движения, усиливаются при эмоциях, исчезают во сне); 2) нарушение координации; 3) мышечная гипотония. Ребёнок гримасничает, роняет предметы, меняются походка и почерк; часто гемихорея; эмоциональная неустойчивость, раздражительность, плаксивость. Длится 2–3 мес, часты рецидивы; сейчас чаще стёртые формы.\n- **Кольцевидная (анулярная) эритема** — у 5–10%: розовые кольца, не возвышаются, кружевной рисунок, летучие; на спине, груди, над суставами [Е].\n- **Ревматические узелки** — плотные, безболезненные, неподвижные, с просяное зерно и больше; в подкожной клетчатке у крупных суставов, по ходу сухожилий, в фасциях; исчезают медленно без следа; сейчас очень редки [Е].\n- Опасны стёртые и малосимптомные формы [З]."}},{"id":"ccc-112","heading":{"text":"Течение и активность [Е]","level":2}},{"id":"ccc-113","text":{"text":"- Фазы: активная (1 год от начала атаки) и неактивная. С каждой новой атакой на первый план выходит поражение сердца (пороки), внесердечные проявления бледнеют.\n- **I (минимальная)** — изолированный миокардит или только малая хорея; лабораторные и инструментальные признаки слабые.\n- **II (умеренная)** — поражение миокарда и эндокарда, СН I и IIA; признаки умеренные.\n- **III (высокая)** — поражены 2–3 оболочки, СН IIA–IIБ, выраженная хорея; резко изменены анализы.\n- Течение: острое (до 2–3 мес), подострое (3–6 мес), затяжное (> 6 мес), рецидивирующее (обострения и неполные ремиссии с минимальной активностью), латентное (бессимптомное)."}},{"id":"ccc-114","heading":{"text":"Диагностика","level":2}},{"id":"ccc-116","table":{"caption":"Критерии Киселя — Джонса — Нестерова (табл. 9 [Е])","header":true,"rows":[{"cells":["Большие критерии","Малые критерии"]},{"cells":["Кардит","Клинические: артралгия, лихорадка"]},{"cells":["Артрит","Лабораторные: повышенная СОЭ, повышение СРБ"]},{"cells":["Хорея","Инструментальные: удлинение PR на ЭКГ"]},{"cells":["Кольцевидная эритема","Признаки митральной или аортальной регургитации на ЭхоКГ"]},{"cells":["Подкожные ревматические узелки",""]}]}},{"id":"ccc-117","text":{"text":"Подтверждение предшествующей стрептококковой инфекции: повышенные или растущие титры антистрептококковых антител (АСЛ-О > 250); позитивная А-стрептококковая культура из зева или положительный экспресс-тест на А-стрептококковый антиген. **Высокая вероятность ОРЛ** — 2 больших или 1 большой + 2 малых критерия при признаках перенесённой инфекции β-гемолитическим стрептококком А."}},{"id":"ccc-118","text":{"text":"Лабораторно [Е]: лейкоцитоз, повышенная СОЭ; диспротеинемия, С-реактивный белок, повышение фибриногена, серомукоида; нарастание титров АСЛ-О, антистрептогиалуронидазы (АСГ), антистрептокиназы (АСК); выделение стрептококка А из зева."}},{"id":"ccc-119","heading":{"text":"Лечение","level":2}},{"id":"ccc-120","text":{"text":"- **Этапы** [Е, З]: 1) стационар (желательно кардиологическое отделение) — 1,5–2 мес [Е] / 6–8 нед [З]; 2) местный санаторий или домашний режим 1,5–2 мес [Е] / санаторий 8–12 нед [З]; 3) диспансерное наблюдение в поликлинике. Все больные с активной фазой госпитализируются [З].\n- **Режим**: постельный 2–3 нед, затем 2 нед полупостельный, через 6 нед — тренирующий; перевод — по клинике, анализам и нагрузочным пробам; ЛФК со 2–3-й недели [Е]. По [З] — постельный в среднем 2–3 нед, затем щадящий; индивидуальная ЛФК с первых дней.\n- **Питание**: обогащённое витаминами, калием, магнием; без НК — общий стол. На фоне гормонов и диуретиков — продукты с калием (изюм, курага, бананы, чернослив) и липотропные (творог, овсянка). При СН — ограничение соли и жидкости (стол № 7 — так в [Е]) [Е]. По [З] — общий стол, 4 раза в день; на гормонах — картофель, капуста, урюк, изюм, чернослив.\n- **Антибиотики**: 10-дневный курс независимо от посева — полусинтетические пенициллины (амоксициллин, ампициллин, ампиокс, амоксиклав, аугментин), затем бициллин-5 [Е]; по [З] — бициллин-5 1 раз в 30 дней в течение года. При непереносимости — макролиды (эритромицин, сумамед, рокситромицин) и цефалоспорины (цефалексин, цефазолин). Санация очагов, прежде всего хронического тонзиллита [Е].\n- **Базисная противовоспалительная терапия** — НПВП, хинолиновые препараты, глюкокортикоиды, цитостатики; выбор по степени активности [Е]:\n  - I степень — НПВП (диклофенак натрия, вольтарен, ортофен, бруфен; также нимесулид/найз) на 2–3, иногда до 6 мес: полная доза 2 нед, затем − 50%.\n  - II–III степень и риск порока (эндокардит) — преднизолон в среднем 6–8 нед, при тяжёлых кардитах до 10–12 нед. Дозы по [З]: 0,4–0,5 мг/кг/сут, при высокой активности 1–1,5 мг/кг; полная доза 2 нед, отмена постепенная (− 5 мг в неделю); НПВС потом − 50% на 1,5–2 мес.\n  - Подострое, затяжное, рецидивирующее течение — хинолиновые (резохин, делагил, плаквенил) на 3–6 мес [Е]; хлорохин/гидроксихлорохин 5–10 мг/кг/сут, позволяют снизить дозы гормонов и НПВС [З].\n  - Рецидивирующее с высокой активностью — цитостатики (азатиоприн) 6–7 нед [Е].\n- **Индометацин** детям не рекомендуется (до 7 лет [Е]): стимулирует склероз в очаге, минуя фазу грануляции, ускоряя формирование порока и анкилозов [Е, З].\n- **Фоновая и симптоматическая** [Е]: витамины C, A, E 1 мес; антигистаминные (тавегил, диазолин, фенкарол) 5–7 дней; кардиотропная терапия 2–3 нед (аспаркам, панангин, рибоксин, актовегин, неотон, антиоксикапс, аевит); при СН — сердечные гликозиды и диуретики (по [З] — только при признаках НК). При хорее дополнительно: пирацетам до 2 мес, алпразолам (ксанакс) или тиоридазин (сонапакс, меллерил) 10–14 дней.\n- **После выписки** [З]: домашние занятия ≥ 1 мес, дополнительный выходной, освобождение от экзаменов; ЛФК, затем год — подготовительная группа; через 2 года ремиссии — основная группа.\n- **Прогноз** [З]: при первичном ревматизме благоприятный, при возвратном — хуже (СН из-за клапанных пороков); хирургическая коррекция паллиативна."}},{"id":"ccc-121","heading":{"text":"Профилактика [Е]","level":2}},{"id":"ccc-122","text":{"text":"- **Первичная**: общие меры (физическое развитие, закаливание с первых месяцев, свежий воздух, активность, полноценное питание) и борьба со стрептококком. При ангине, скарлатине, обострении тонзиллита — полусинтетические пенициллины (ампициллин, амоксициллин, ампиокс, карбенициллин) 10–14 дней или 5 дней + бициллин-5 750 000–1 500 000 ЕД дважды с интервалом 5 дней. Альтернатива — макролиды (джозамицин, мидекамицин, рокситромицин); цефалоспорины активно элиминируют возбудителя.\n- **Вторичная** (против рецидивов): круглогодично бициллин-5 в течение 5 лет после атаки: до 10 лет — 750 000 ЕД, старше 10 лет — 1 500 000 ЕД раз в 3–4 нед. Весной и осенью (март–апрель, октябрь–ноябрь) + НПВП на 1 мес. Группа риска порока (эндокардит при первой атаке, рецидивы) — до 18–20 лет. Можно ретарпен или экстенциллин 1 раз в месяц: до 10 лет — 1 200 000 ЕД, старше — 2 400 000 ЕД. При ангине/ОРИ на фоне профилактики — 7–10 дней антибиотики + НПВП."}},{"id":"ccc-123","heading":{"text":"Поражение сердца при других ревматических болезнях [З]","level":2}},{"id":"ccc-124","text":{"text":"- СКВ: нередко поражаются все 3 оболочки сердца; характерен выпотной или фибринозный перикардит (критерий диагноза — плеврит и/или перикардит).\n- Ювенильный ревматоидный артрит с системными проявлениями (10–13%): ревматоидный кардит, кардиодистрофия, перикардит, васкулиты."}}]},{"id":"ccc-s07","title":"6. Неревматический кардит, кардиомиопатии, вегетососудистая дистония","blocks":[{"id":"ccc-125","text":{"text":"Эти темы есть только в учебнике [З] (гл. 16); дифтерийный миокардит — из главы о дифтерии того же учебника."}},{"id":"ccc-126","heading":{"text":"Неревматический кардит [З]","level":2}},{"id":"ccc-127","text":{"text":"Группа воспалительных заболеваний сердца инфекционно-аллергической природы с преимущественным поражением миокарда; по данным аутопсии — 3–8%."}},{"id":"ccc-128","text":{"text":"- **Этиология:** чаще вирусы — Коксаки (A и B) и ECHO (кардиотропны, а иммунитет детей несовершенен). Врождённый кардит — цитомегаловирус, токсоплазмоз. Грибковый — при хронических болезнях и на фоне антибиотиков.\n- **Патогенез:** иммунопатологический феномен. При остром кардите пусковой механизм — инфекция: медиаторы воспаления (брадикинин, гистамин, серотонин), гиперчувствительность немедленного типа (иммунные комплексы), рост проницаемости сосудов, клеточная инфильтрация. При хроническом течении возбудитель не решает: аутоиммунные нарушения, антимиокардиальные антитела, комплексы с комплементом повреждают сосуды; нарушен клеточный иммунитет (меньше Т-супрессоров, снижена активация Т-хелперов, гиперстимуляция В-лимфоцитов) → пролиферативные изменения. Особенности хронического кардита у детей: системность, злокачественное и рецидивирующее течение.\n- **Классификация:** врождённый (ранний — фиброэластоз, эластофиброз; поздний) и приобретённый; по течению — острый, подострый, хронический."}},{"id":"ccc-129","table":{"caption":"","header":true,"rows":[{"cells":["Форма","Когда","Клиника"]},{"cells":["Врождённый ранний","Первые 6 мес (реже 2–3-й год)","Отставание в развитии, вялость, бледность, утомляемость при кормлении; кардиомегалия, ранний «сердечный горб», глухие тоны; шума нет или систолический (недостаточность митрального клапана); левожелудочковая недостаточность, рефрактерная к терапии"]},{"cells":["Врождённый поздний","С 3–5 мес","Преобладают внесердечные симптомы: утомляемость при кормлении, потливость, плохая прибавка массы, приступы беспокойства с одышкой, цианозом, судорогами, иногда потерей сознания; приподнимающийся верхушечный толчок, умеренное расширение границ, громкие тоны, шума нет, тахи- или брадиаритмия, СН менее выражена"]},{"cells":["Острый","Обычно 2–3 года","Интоксикация (утомляемость, слабость, лихорадка, тошнота, рвота); у старших — упорные боли в сердце и за грудиной. Слабый частый, часто аритмичный пульс, ослабленный верхушечный толчок, расширение границ, снижение АД, ритм галопа, экстрасистолия, реже пароксизмальная тахикардия, приглушение тонов, мышечный систолический шум; иногда перикардит. Быстро — лево-, затем правожелудочковая недостаточность (одышка, цианоз, застойные хрипы, пастозность, увеличение печени). На противовоспалительной терапии быстро улучшается"]},{"cells":["Подострый","Пре- и пубертат","Поражение проводящей системы: нарушения ритма, блокады"]},{"cells":["Хронический","Старшие дети (исход острого или первично-хронический)","Бессимптомно до СН; отставание в развитии, «сердечный горб», утомляемость, одышка, сердцебиение, боли, навязчивый кашель; кардиомегалия, аритмия, систолический шум на верхушке и в V точке, хрипы, увеличение и уплотнение печени. Несоответствие кардиомегалии и хорошего самочувствия; СН сначала левожелудочковая, потом тотальная"]}]}},{"id":"ccc-130","text":{"text":"- **Лечение:** этиологическое и патогенетическое, воздействие на иммунную реактивность, ликвидация СН; коррекция двигательного, пищевого и питьевого режима. При остром и подостром кардите на 2–4 нед ограничивают двигательную активность; меньше соли, больше калия; выпитая жидкость на 200–300 мл меньше суточного диуреза. Антибиотики — только детям раннего возраста для профилактики осложнений. Глюкокортикоиды — чтобы предотвратить хронизацию (при хроническом кардите не показаны). При подостром и хроническом — аминохинолины (хлорохин/делагил, гидроксихлорохин/плаквенил) + диклофенак 3 мг/кг, курсы 2–3 раза в год; пирикарбат (пармидин), апротинин (контрикал) 0,25–0,75 г/сут 1,5–2 мес. По показаниям — сердечные гликозиды вместе с мочегонными. Метаболические — кокарбоксилаза, инозин.\n- **Прогноз:** острый — благоприятный, изменения исчезают бесследно; подострый — возможна хронизация; хронический — неблагоприятный, тотальная СН."}},{"id":"ccc-131","heading":{"text":"Дифтерийный миокардит [З]","level":2}},{"id":"ccc-132","text":{"text":"- Возникает в конце 1-й — начале 2-й недели болезни: приглушение тонов, расширение границ, систолический шум, иногда экстрасистолия, частый пульс, слабость.\n- Тяжёлый: бурное развитие, бледность, цианоз губ, адинамия; **триада Молчанова** — рвота, боли в животе, стойкий ритм галопа; падение АД, нарушение периферической гемодинамики. Летальность при тяжёлом миокардите — более чем у половины.\n- Лечение: строгий постельный и охранительный режим; при тяжёлом — глюкокортикоиды; НПВС; для метаболизма миокарда — 10% глюкоза, аскорбиновая кислота, пиридоксин, кокарбоксилаза, инозин (рибоксин); совместно с кардиологом под контролем ЭКГ."}},{"id":"ccc-133","heading":{"text":"Кардиомиопатии (КМП) [З]","level":2}},{"id":"ccc-134","text":{"text":"- В основе — неравномерная гипертрофия миокарда (чаще левого желудочка) с нарушением внутрисердечной гемодинамики; описано более 70 вариантов локализации асимметричной гипертрофии.\n- 4 анатомических типа по двухмерной ЭхоКГ: 1) гипертрофия базальных отделов МЖП; 2) тотальная гипертрофия МЖП; 3) тотальная гипертрофия перегородки и свободной стенки ЛЖ (в т.ч. симметричная); 4) гипертрофия верхушки с возможным распространением на стенку и перегородку.\n- Этиология и патогенез: патологическая реакция адренорецепторов миокарда на катехоламины (возможно, уже внутриутробно); снижение аденозина (антагониста катехоламинов); генетика (HLA B27, DR4), изменение конфигурации МЖП; патология интрамуральных венечных артерий → ишемия, фиброз, компенсаторная гипертрофия; аномалия коллагена; субэндокардиальная ишемия → истощение энергии для секвестрации кальция в диастолу, снижение диастолической податливости.\n- Клиника: у детей чаще **гипертрофическая КМП**; проявляется в первые дни жизни, реже на 2-м году. Одышка, сердцебиение, потеря сознания; границы сердца расширены влево, I тон приглушен, бради- и тахиаритмии. Самый частый признак — грубый скребущий систолический шум, меняющийся при смене положения тела (нефиксированное сужение выходного тракта ЛЖ, пролабирование митрального клапана, турбулентность); максимум в III–IV межреберье слева или на верхушке, на сосуды не проводится.\n- ЭКГ зависит от локализации: при гипертрофии перегородки с переходом на стенку ЛЖ — блокада левой ножки пучка Гиса; при верхушечной — «гигантские» отрицательные T в грудных отведениях.\n- Лечение симптоматическое: β-адреноблокаторы (предпочтителен пропранолол, доза индивидуально, до улучшения и вновь при нарастании жалоб); при мерцательной и других аритмиях — верапамил, нифедипин; периферические вазодилататоры (нитроглицерин, изосорбида динитрат) усиливают чувствительность к β-блокаторам. Сердечные гликозиды — только при мерцательной тахиаритмии, не купируемой другими средствами, или при застойной СН (с диуретиками). Прогноз неблагоприятный."}},{"id":"ccc-135","heading":{"text":"Вегетососудистая дистония (синдром вегетативной дистонии, СВД) [З]","level":2}},{"id":"ccc-136","text":{"text":"- Нарушение вегетативной регуляции сердца, сосудов, внутренних органов, желёз внутренней секреции из-за первичных или вторичных отклонений ЦНС и периферической НС. Это не самостоятельная болезнь, а клинический синдром. Синонимы: вегетативная дисфункция, дизрегуляция, гиперкинетический синдром, **нейроциркуляторная дистония (НЦД)** — когда нарушения только в кардиоваскулярной системе.\n- Этиология (схема 3): эндогенные — наследственно-конституциональный тип реагирования НС, нарушение чувствительности рецепторов гипоталамуса и лимбико-ретикулярного комплекса, неблагоприятное течение беременности и родов; экзогенные — приобретённые поражения ЦНС (ЧМТ, опухоли, интоксикации), психоэмоциональное напряжение дома и в школе, личностные особенности.\n- Патогенез (схема 4): предрасположенность + экзогенные факторы → нарушение надсегментарных центров (внутричерепная гипертензия в области III желудочка, дисфункция гипоталамуса и лимбико-ретикулярного комплекса) → нарушение интегративной функции ВНС (обмен, свёртывание, иннервация органов, медиаторная и гормональная регуляция, чувствительность рецепторов) → кардиальные и экстракардиальные симптомы → психосоматические болезни (гипертоническая, гипотоническая болезнь).\n- Типы: симпатикотонический, парасимпатикотонический (ваготонический), смешанный. Нарушения чаще генерализованные/системные; бывают первичные и вторичные.\n- Три клинических синдрома:\n  - **Психовегетативный** — пароксизмальные нарушения психики и органов. Особое значение — обмороки (синкопе), чаще у девочек в пре- и пубертате: внезапное нарушение сознания до утраты на 1–3 мин, падение АД, брадикардия, сменяющаяся тахикардией, холодный пот, мышечная гипотония. Также кардиалгии, одышка, ЖКТ-дискомфорт, мигрени.\n  - **Прогрессирующей вегетативной недостаточности** (реже) — симпаталгии, сосудистые и трофические нарушения; при очагах в височной доле — височная эпилепсия с висцеральной аурой (боль в сердце, животе); похудание, недержание мочи, запор, дизартрия, заложенность носа.\n  - **Вегетативно-сосудисто-трофический** (ангиотрофоневротический) — поражение нервов и корешков рук и ног.\n- Лечение: совместно педиатр, кардиоревматолог, психоневролог, физиотерапевт. Принципы: 1) учитывать этиологию и патогенез у ребёнка; 2) комплексность и длительность; 3) с момента диагноза; 4) с учётом типа (ваго- или симпатотонический); 5) психотерапия всей семьи. Также санаторно-курортное лечение, ЛФК, водные процедуры, массаж, иглорефлексотерапия. Прогноз при своевременном лечении благоприятный."}}]},{"id":"ccc-s08","title":"7. Недостаточность кровообращения и неотложная помощь","blocks":[{"id":"ccc-x-003","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Методика","text":"Медсестра не назначает препараты и дозы: её задача — распознать состояние, вызвать врача, придать положение, дать кислород и подготовить всё для введения лекарств. Дозы приведены для понимания назначений врача."}},{"id":"ccc-137","text":{"text":"Недостаточность кровообращения (НК) — состояние, при котором ССС не может достаточно снабдить кровью органы и ткани [З]; две формы — сердечная и сосудистая, возможно их сочетание [Е, З]."}},{"id":"ccc-138","heading":{"text":"Острая сердечная недостаточность (ОСН)","level":2}},{"id":"ccc-139","text":{"text":"- Сердце не обеспечивает потребность в кровоснабжении. Два вида [Е]: **синдром малого выброса (кардиогенный шок)** и **застойная СН**.\n- Причины малого выброса: нарушения ритма, токсическое поражение сердца при инфекциях и отравлениях кардиотоксическими ядами, острая ишемия миокарда. Развивается молниеносно: бледность, резкое беспокойство, частый нитевидный пульс, падение АД, олигурия [Е].\n- Застойная СН — сердце не справляется с венозным возвратом; чаще при врождённых и приобретённых пороках, инфекционных и инфекционно-аллергических миокардитах [Е].\n- Причины ОСН у детей [З]: бактериальное и токсическое поражение миокарда при гриппе, пневмонии, кишечных инфекциях, отравлениях; ревматический миокардит и пороки; дифтерийный и брюшнотифозный миокардит; острый нефрит; анемия. Снижение сократимости → меньше выброс и минутный объём, выше венозное давление, больше ОЦК.\n- Симптомы [З]: тахикардия, одышка, цианоз, пастозность и отёки, расширение границ сердца, увеличение печени, диспепсия (большинство — компенсаторные). У детей раннего возраста первые признаки — затруднения при кормлении, отказ от еды, беспокойство, нарушение сна, рвота; отёки — одутловатость лица, припухлость век, выбухание большого родничка, пастозность мошонки и крестца."}},{"id":"ccc-141","table":{"caption":"Стадии застойной СН [Е]","header":true,"rows":[{"cells":["Стадия","Признаки"]},{"cells":["I","Застой в одном (у малышей — в обоих) кругах; тахикардия и одышка в покое; соотношение ЧСС/ЧД растёт (≥ 3,5 на 1-м году, > 4,5 у старших). Большой круг: увеличение печени, периорбитальные отёки, набухание шейных вен, одутловатость лица. Малый круг: цианоз, затруднённое дыхание, крепитация и мелкопузырчатые хрипы внизу, акцент II тона на лёгочной артерии. Тоны приглушены"]},{"cells":["II","+ олигурия (анурия), периферические отёки (ноги, крестец, поясница), часто отёк лёгких"]},{"cells":["III","Тотальный застой, падение систолического, затем диастолического АД, сердце значительно расширено, тоны глухие"]}]}},{"id":"ccc-142","text":{"text":"**Неотложная помощь при ОСН.** Госпитализация (реанимация/ПИТ); лечебно-охранительный режим, приподнятое изголовье, аэрация, кислород [Е, З]. Медикаменты:"}},{"id":"ccc-143","text":{"text":"- [Е]: 1) инотропные — допамин, добутрекс, адреналин; после уменьшения гипоксии — сердечные гликозиды (строфантин, коргликон); 2) кардиотрофики — панангин, аспаркам, глюкоза, кокарбоксилаза, рибоксин, АТФ, витамины B1, B6, B12, C; 3) борьба с гиперволемией — ограничение соли, жидкости и инфузий, диуретики (лазикс, этакриновая кислота); 4) сосудорасширяющие (никошпан, компламин) и дезагреганты (трентал, курантил).\n- [З] — 4 направления: **преднагрузка** (фуросемид в/в 1–2 мг/кг 2–3 раза в сутки; жидкость до ⅔ возрастной потребности; дыхание с положительным давлением в конце выдоха); **инотропная поддержка** — адреномиметики в/в микроструйно (лучше в центральную вену) + коррекция ацидоза натрия гидрокарбонатом 200–250 мг/кг за 30–40 мин; **снижение постнагрузки** — нитроглицерин или каптоприл внутрь каждые 12–24 ч (0,5–0,6 мг/кг до 3 лет, 12,5 мг старше), можно с гипотиазидом; **кардиотрофика** — поляризующая смесь (20% глюкоза 5 мл + 7,5% KCl 0,3 мл + инсулин 1 ЕД). По показаниям: преднизолон 5–7 мг/кг/сут, панангин 0,25 мл/кг, курантил 0,1–0,2 мл/год жизни, рибоксин 5–15 мл, цитохром C, солкосерил, эуфиллин."}},{"id":"ccc-145","table":{"caption":"Табл. 29 [З]. Адреномиметики","header":true,"rows":[{"cells":["Препарат","Доза, мкг/(кг·мин)","Действие"]},{"cells":["Допамин","2–4","Диуретическое и сосудорасширяющее (почки, мышцы, ЖКТ)"]},{"cells":["Допамин","5–8","Усиление сердечных сокращений"]},{"cells":["Допамин","10","Сосудосуживающее, поддерживает АД"]},{"cells":["Добутамин (добутрекс)","5–15","Увеличение частоты и силы сокращений"]},{"cells":["Эпинефрин (адреналин)","0,2–1,0","То же"]},{"cells":["Нитроглицерин","0,1–25","Преимущественно венозное, лёгочное и коронарное расширение"]}]}},{"id":"ccc-146","text":{"text":"- **Дигитализация** [З]: в экстренных ситуациях — только при наджелудочковой тахикардии с застойной СН. Дигоксин в/в: доза насыщения 0,03–0,05 мг/кг — ½, через 8–12 ч ¼, ещё через 8–12 ч ¼; поддерживающая = ⅕ дозы насыщения в 2 приёма через 12 ч. Гликозиды — не препараты первого выбора: только после ликвидации гипоксии, ацидоза и гиперкапнии, иначе возможна фибрилляция желудочков.\n- **Острая левожелудочковая недостаточность / отёк лёгких** [Е]: снизить давление в лёгочных сосудах и гипоксию: кислород через 30–40% спирт или аэрозоль 10% антифомсилана (2–3 мл на ингаляцию); диуретики; периферические вазодилататоры (нитроглицерин под язык, натрия нитропруссид в/в титрованием) и ганглиоблокаторы (арфонад) под контролем АД; глюкокортикоиды; при бронхоспазме — 2,4% эуфиллин 1 мл на год жизни. Алгоритм для взрослых (ортопноэ, жгуты и т.д.) [О] — в разделе 3."}},{"id":"ccc-147","heading":{"text":"Одышечно-цианотический приступ (при «синих» пороках) [З]","level":2}},{"id":"ccc-148","text":{"text":"- Первая помощь: усадить, максимальный приток воздуха или кислород.\n- Основа терапии: оксигенотерапия (желательно с положительным давлением на выдохе), коррекция ацидоза (4% натрия гидрокарбонат 5 мл/кг за 5 мин, затем та же доза: половина за 30 мин, половина за 4 ч), снятие спазма лёгочной артерии: морфин 0,1–0,2 мг/кг п/к или в/в (промедол менее эффективен); без эффекта — пропранолол 0,1–0,2 мг/кг в/в медленно (1 мл/мин) в 10 мл 20% глюкозы. Схема [Е] — в разделе 4."}},{"id":"ccc-149","heading":{"text":"Сосудистая недостаточность: коллапс","level":2}},{"id":"ccc-150","text":{"text":"- **Определение.** Недостаточность периферического кровообращения с низким АД и нарушением кровоснабжения органов; острая — коллапс и обморок [Е]. Коллапс (лат. *collapsus*) — острая сосудистая недостаточность с падением сосудистого тонуса, снижением сократимости сердца, ОЦК и АД [О]; несоответствие ОЦК и ёмкости сосудистого русла [Е, З].\n- **Механизмы** [Е]: 1) снижение тонуса артериол и вен (на пике инфекции, острая гипоксия, отравления, травма, острый панкреатит, внезапная отмена глюкокортикоидов, ортостатический); 2) уменьшение ОЦК (массивная кровопотеря, плазмопотеря при ожоге, обезвоживание). Также: тяжёлые инфекции, надпочечниковая недостаточность, ортостатическая ишемия мозга [З]; инфаркт миокарда, обезвоживание при рвоте и диарее, передозировка антигипертензивных [О].\n- **Клиника** [Е]: ребёнок лежит, вставание ухудшает состояние; бледность, мраморность, холодный пот, цианоз губ, холодные конечности, тахикардия, ЦВД падает до нуля. [З]: затемнённое сознание, снижение температуры, олигурия, глухие тоны, поверхностное дыхание, липкий холодный пот. [О]: как при обмороке, но сознание не всегда теряется — больной заторможен, безучастен, зрачки расширены. Примечание: в [Е] написано, что пульсовое давление «высокое».\n- **Типы коллапса** [З]: симпатикотонический (бледность, повышение систолического АД, тахикардия), ваготонический (брадикардия, низкое диастолическое АД), паралитический (тахикардия, нитевидный пульс, снижение обоих давлений).\n- **Помощь:** уложить горизонтально, приподняв ножной конец (голова ниже [О]); расстегнуть одежду, свежий воздух, кислород, согреть; устранить причину (напр. кровотечение) [Е, О, З]. Лекарства [Е]: в/в инфузия для восстановления ОЦК под контролем состояния, цвета кожи, ЧСС, АД, часового диуреза; глюкокортикоиды (преднизолон, триамцинолон, метипред); вазопрессоры (норадреналин, допамин, добутрекс). [О]: препараты крови или кровезаменители, средства, повышающие тонус (никетамид, сульфокамфорная кислота + прокаин, фенилэфрин). [З] по типам: симпатикотонический — 2,5% аминазин и 2,5% пипольфен по 0,1 мл/год (не более 1 мл) в/м; ваготонический и паралитический — 10% кофеин 0,1 мл/год п/к, кордиамин 0,1 мл/год п/к или в/м, 1% мезатон 0,1 мл/год (≤ 1 мл) в/м. Перед транспортировкой без сознания — преднизолон 1–2 мг/кг в/в, реополиглюкин 10–15 мл/кг капельно; далее лечение основного заболевания."}},{"id":"ccc-151","heading":{"text":"Обморок","level":2}},{"id":"ccc-152","text":{"text":"- **Определение.** Обморок (синкопе) — кратковременная потеря сознания из-за острой недостаточности кровоснабжения мозга [О]; лёгкая форма сосудистой недостаточности: рефлекторный парез сосудистого тонуса и временная анемия мозга [Е].\n- **Причины:** эмоции (страх, боль, взятие крови, вид крови, небольшая травма), душное помещение, переутомление [Е, О]; ортостатические — у ослабленных детей после длительного постельного режима, после быстродействующих диуретиков, ганглиоблокаторов; брадикардия, пароксизмальная тахикардия; малый выброс (аортальный, митральный стенозы); физнагрузка, гипервентиляция, гипогликемия, приступообразный кашель [Е].\n- **Клиника:** предвестники — слабость, головокружение, звон/шум в ушах, мушки/потемнение в глазах, тошнота, позывы на рвоту, «ватные» ноги. Бледность кожи и слизистых, холодный липкий пот, холодные конечности, резкое падение АД, малый нитевидный пульс, ослабленные тоны [Е, О]. Длится обычно 20–30 с [О] (секунды — минуты [Е]); возникает в вертикальном положении, лёжа сознание быстро возвращается. В отличие от эпилепсии непроизвольное мочеиспускание редко, нет остановки дыхания и прикуса языка [О]. У детей раннего возраста возможны судороги [Е].\n- **Помощь:** уложить с приподнятыми ногами (старшего ребёнка можно усадить, опустив голову на колени [Е]); расстегнуть одежду, свежий воздух; обрызгать лицо и грудь холодной водой, растереть виски, тело; осторожно дать вдохнуть нашатырный спирт (или уксус [Е]) — активирует дыхательный центр [О]; согреть; массаж живота, при ознобе — тёплое питьё [З]. При необходимости [Е]: 10% кофеин 0,1 мл/год п/к, кордиамин (1 капля/год внутрь или 0,1–0,5 мл п/к); при выраженной гипотонии — 1% мезатон 0,1 мл/год в/в струйно; лечение основного заболевания. В [З] при отсутствии эффекта — переход к ИВЛ."}},{"id":"ccc-153","heading":{"text":"Пароксизмальная тахикардия и риск внезапной смерти [З]","level":2}},{"id":"ccc-154","text":{"text":"Особый контроль — за состояниями, ведущими к внезапной смерти: пароксизмальная тахикардия, синдром Вольфа — Паркинсона — Уайта, СН. Для снятия пароксизма — раздражение блуждающего нерва: надавливание на глазные яблоки, массаж синокаротидной зоны, искусственная рвота; подготовить всё для в/в введения. При остановке сердца — закрытый массаж, ИВЛ, подготовка к внутрисердечному введению и электростимуляции."}}]},{"id":"ccc-s09","title":"8. Сердечно-лёгочная реанимация (СЛР)","blocks":[{"id":"ccc-x-004","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Методика","text":"СЛР отрабатывают только на фантоме. Цифры учебников разных лет расходятся с действующими рекомендациями (у взрослых сейчас 30 компрессий : 2 вдоха, глубина 5–6 см, темп 100–120 в минуту) — отвечайте по стандарту кафедры."}},{"id":"ccc-155","text":{"text":"Остановка сердца и дыхания — начало клинической смерти; спасение зависит от быстроты и качества первичных мероприятий [Е, О]. Цифры в учебниках разных лет отличаются — ниже даны как в источниках."}},{"id":"ccc-156","heading":{"text":"Терминальные состояния [О]","level":2}},{"id":"ccc-157","text":{"text":"1. Предагональное — угнетение сознания, расстройство дыхания и кровообращения; заканчивается терминальной паузой (5–10 с — 3–4 мин).\n2. Агония — секунды–минуты: сначала АД и ЧД растут, затем резкое падение АД, урежение ЧСС, агональное дыхание, утрата сознания и рефлексов, расширение зрачков.\n3. Клиническая смерть — обратимый этап в среднем 5–6 мин; обмен в тканях ещё идёт."}},{"id":"ccc-158","text":{"text":"**Признаки клинической смерти:** отсутствие сознания (через 10–15 с после остановки кровообращения) и реакции на раздражители; расширение зрачков без реакции на свет (начинается через 40–60 с, максимум через 90–100 с); остановка дыхания или ЧДД 5–8; нет пульса на лучевых, сонных, бедренных артериях; цианоз губ, пальцев, мочек; бледность с синюшной мраморностью [О]. [Е]: исчезновение сердцебиения, нет пульса на сонной и бедренной, потеря сознания, апноэ, широкие зрачки, серая с цианотичным оттенком кожа."}},{"id":"ccc-159","text":{"text":"**Биологическая смерть** (констатирует врач) [О]: нет спонтанных движений, дыхания и сердцебиения, максимально расширенные зрачки без реакции + поздние признаки: снижение температуры тела, трупные пятна, мышечное окоченение. После остановки сердца в ЦНС развиваются необратимые изменения (гибель коры) [Е]."}},{"id":"ccc-160","heading":{"text":"Задачи и порядок","level":2}},{"id":"ccc-161","text":{"text":"- Задачи сердечно-лёгочно-мозговой реанимации [Е]: 1) восстановить и поддержать дыхание; 2) поддержать кровообращение; 3) устранить метаболические расстройства; 4) предотвратить необратимые изменения ЦНС.\n- Начинать немедленно на месте, отметить время остановки сердца, уложить на жёсткую поверхность (пол) [Е, О].\n- **Проходимость дыхательных путей**: запрокинуть голову (нельзя при травме шейного отдела), выдвинуть нижнюю челюсть, устранить западение языка, очистить рот и глотку (слизь, рвота, протезы, инородные тела) [Е, О]. При инородном теле у ребёнка — двойной удар: 3–5 ударов между лопатками с одновременным надавливанием на живот к грудине; при обтурации нижних путей — ларингоскопия, аспирация, интубация [Е]; у взрослых при инородном теле или отёке гортани — трахеотомия [О]."}},{"id":"ccc-162","heading":{"text":"Искусственное дыхание и массаж сердца","level":2}},{"id":"ccc-163","table":{"caption":"","header":true,"rows":[{"cells":["Параметр","Дети [Е]","Взрослые [О]"]},{"cells":["Способ ИВЛ","«рот в рот» / «рот в нос», новорождённому — в рот и нос; через влажную салфетку; лучше воздуховод, маска, мешок Амбу, аппарат","«изо рта в рот» / «в нос» через марлю; желательно мешок Амбу"]},{"cells":["Частота вдохов","грудные 20–24, ранний и младший возраст 16–20, старшие 12–16 в мин","16–20 в мин"]},{"cells":["Объём вдувания","новорождённый 30–40 мл, недоношенный ≤ 25 мл","—"]},{"cells":["Точка массажа","на 2 поперечных пальца выше мечевидного отростка","нижняя треть грудины, на 2 пальца выше мечевидного отростка; основания кистей крестом, руки прямые"]},{"cells":["Глубина и темп","новорождённые и грудные — 1–2 пальца, 1–2 см, 120–140/мин; до 10–12 лет — одна рука, 2,5–3 см, 100–120/мин; старше 12 лет — две ладони, 3–5 см, 60–80/мин","4–5 см (руки + масса тела), 80–100/мин (рекомендации США и Европы — 100)"]},{"cells":["Соотношение","2 спасателя: 5 : 1; один — 2 вдоха на 10–15 толчков","2 человека: 1 вдох : 5 сжатий; один: 2 : 15"]}]}},{"id":"ccc-164","text":{"text":"- У взрослых перед массажем — 1–2 прекардиальных удара кулаком с 25–30 см (при асистолии может восстановить ритм) [О]. По мнению американских кардиологов (1997), в начале реанимации массаж важнее дыхания [О].\n- Критерии эффективности: ИВЛ — экскурсия грудной клетки (вздутие эпигастрия = воздух в желудке, риск рвоты и аспирации); массаж — пульс на сонной/бедренной при каждом толчке, сужение зрачков, порозовение кожи [Е, О].\n- Осложнения массажа: переломы рёбер и грудины (самое частое), пневмоторакс; давление на мечевидный отросток — разрыв печени; аспирация желудочного содержимого [Е, О]."}},{"id":"ccc-165","heading":{"text":"Специализированная реанимация у детей [Е]","level":2}},{"id":"ccc-166","text":{"text":"- 100% кислород через маску/интубационную трубку, при стабилизации — 40–60%.\n- При остановке сердца в/в: 0,1% адреналин 0,01 мг/кг (0,1 мл/кг); 0,1% атропин 0,02 мг/кг (0,1–1,0 мг); по показаниям алупент; 4% натрия бикарбонат под контролем КОС.\n- Фибрилляция желудочков (утопление в пресной воде, электротравма, передозировка гликозидов) — дефибрилляция электрическая или лидокаином, на фоне ИВЛ 100% O₂ и антиацидотической терапии.\n- В/в препараты — только при эффективном массаже; иначе интратрахеально (прокол щитовидно-перстневидной мембраны) адреналин, атропин, лидокаин в удвоенных дозах.\n- Постреанимационный период: выяснить причину, нейрореанимация; ОЦК и АД — коллоиды и кристаллоиды + допамин микроструйно + глюкокортикоиды; отёк мозга — ИВЛ не менее 12–24 ч, ГОМК или гексенал, диуретики, кортикостероиды, ноотропы, гипотермия головы."}},{"id":"ccc-167","heading":{"text":"Реанимация новорождённого [З]","level":2}},{"id":"ccc-168","text":{"text":"- Показания: бледность или разлитой цианоз, брадикардия или отсутствие первого вдоха после начальных мер. Начинать до конца 1-й минуты (до оценки по Апгар). Отсасывание желудка — не ранее 5 мин (риск рефлекторных апноэ и брадикардии).\n- ИВЛ — при апноэ или неадекватном (судорожном, нерегулярном, поверхностном) дыхании; **непрямой массаж — при ЧСС < 80** через 15–30 с после начала ИВЛ; надавливают на нижнюю треть грудины (не на мечевидный отросток) 80–120 раз/мин; эффективность — по окраске кожи и пульсу на бедренной артерии.\n- Лекарства в родзале: адреналин 1 : 10 000 (через эндотрахеальную трубку или катетер в пупочной вене); восполнение ОЦК (5% альбумин, физраствор, Рингер-лактат); 4% натрия гидрокарбонат. Если за 1 мин массаж не помог — 0,01% адреналин 0,1 мл/кг в пупочную вену (развести физраствором 1 : 1), можно повторить через 5 мин до 3 раз.\n- Прекращение в родзале: адекватное дыхание, нормальная ЧСС и розовая кожа в первые 20 мин; иначе перевод в ОРИТ после стабилизации сердечной деятельности."}}]},{"id":"ccc-s10","title":"9. Уход, режим, питание, обследования","blocks":[{"id":"ccc-169","heading":{"text":"Уход за детьми с болезнями ССС [З]","level":2}},{"id":"ccc-170","text":{"text":"- Основа — физический покой, общий и питьевой режим, правильное питание, рациональное применение лекарств.\n- **Режимы:** строгий постельный (Iа) — вставать нельзя, функциональное положение полусидя, гигиена, кормление и отправления с приспособлениями; постельный (Iб) — всё это сидя рядом с кроватью; полупостельный (II) — можно дойти до туалета и столовой.\n- Палату хорошо проветривают, температура не выше 18–20 °C, централизованная подача кислорода.\n- Питание: диета № 10 (немного меньше соли и жиров), дробно 4–5 раз, последний приём не позднее чем за 3 ч до сна; продукты с калием (изюм, курага, чернослив, картофель, капуста).\n- Пульс и АД — в покое, лучше во сне, запись в температурный лист."}},{"id":"ccc-171","heading":{"text":"Работа медсестры кардиологического отделения [Е]","level":2}},{"id":"ccc-172","checklist":{"title":"Обязанности медсестры кардиологического отделения [Е]","ordered":true,"steps":["Контролирует постельный и двигательный режим, питание (стол № 10).","Обеспечивает санитарный режим палаты, проветривание, температуру.","Знает применение и побочные эффекты кардиологических препаратов (сердечные гликозиды, периферические вазодилататоры, мочегонные, антиаритмические, сосудосуживающие).","Ежедневно измеряет АД, считает пульс, оценивает цвет кожи и отёки.","Транспортирует тяжёлых детей на процедуры.","Знает признаки острой сердечной и сосудистой недостаточности и оказывает доврачебную помощь."]}},{"id":"ccc-173","heading":{"text":"Транспортировка [О]","level":2}},{"id":"ccc-174","text":{"text":"- Сердечно-сосудистая недостаточность — полусидя, хорошо укрыть, грелки к ногам и рукам.\n- Острая сосудистая недостаточность — голова ниже уровня ног."}},{"id":"ccc-175","heading":{"text":"Лечебные диеты при болезнях ССС [О]","level":2}},{"id":"ccc-176","table":{"caption":"","header":true,"rows":[{"cells":["Диета","Показания","Состав и калорийность","Соль / свободная жидкость","Режим"]},{"cells":["№ 10","Болезни ССС без признаков СН","Б 90 г (55–60% животных), Ж 70 г (25–30% растительных), У 350–400 г; 2500–2600 ккал","6–7 г (3–5 г на руки) / 1,2 л","5 раз"]},{"cells":["№ 10а","Выраженная СН","Б 60 г (70% животных), Ж 50 г, У 300 г; 1900 ккал","соль исключена / 0,6–0,7 л","6 раз, не более 4 нед"]},{"cells":["№ 10с","Атеросклероз сосудов сердца, мозга; инфаркт в стадии рубцевания; гипертоническая болезнь","I вар.: Б 90–100, Ж 80 (40% раст.), У 350–400 (сахар 50 г); 2600–2700 ккал. II вар. (ожирение): Б 90, Ж 70, У 300; 2200 ккал","8–10 г / 1,2 л","5 раз, на ночь кефир"]},{"cells":["№ 10и","Инфаркт миокарда","I рацион (1-я нед, протёртое): Б 50, Ж 30–40, У 150–200; 1100–1300 ккал. II (2–3-я нед, измельчённое): Б 60–70, Ж 50–60, У 230–250; 1600–1800 ккал. III (4-я нед, рубцевание): Б 85–90, Ж 70, У 300–350; 2200–2400 ккал","I: без соли / 0,7–0,8 л; II: 3 г / 0,9–1 л; III: 5–6 г / 1–1,1 л","I–II — 6 раз, III — 5 раз"]}]}},{"id":"ccc-177","text":{"text":"- **№ 10:** цель — улучшить кровообращение, щадить ССС и ЖКТ. Немного меньше жиров и углеводов, значительно меньше соли и жидкости; больше калия, магния, липотропных и ощелачивающих продуктов (молочные, овощи, фрукты); мясо и рыбу отваривают, пищу готовят без соли. Исключают: свежий хлеб, сдобу, блины; бульоны и супы из бобовых; жирное мясо, гуся, утку, печень, почки, мозги, копчёности, колбасы, консервы; жирную, солёную, копчёную рыбу, икру; солёные сыры; яйца вкрутую и жареные; бобовые; солёные, маринованные, квашеные овощи; шпинат, щавель, редьку, редис, чеснок, лук, грибы; шоколад, пирожные; горчицу, перец, хрен; натуральный кофе, какао; мясные и кулинарные жиры.\n- **№ 10а:** хлеб бессолевой; резко ограничены экстрактивные вещества, клетчатка, жирное, холестерин, чай и кофе. Блюда отварные и протёртые, кислого или сладкого вкуса; жареное, горячее и холодное запрещены. Исключают также пшено, ячневую, перловую, макароны, виноград, сыр, газировку, квас; из жиров — только свежее сливочное и 5–10 г рафинированного растительного.\n- **№ 10с:** меньше животного жира и легкоусвояемых углеводов, холестерина, экстрактивов; больше витаминов C и группы B, линолевой кислоты, пищевых волокон, калия, магния (растительные масла, овощи, морепродукты, творог); пищу подсаливают за столом.\n- **№ 10и:** три последовательных рациона; без соли, в отварном виде; исключены блюда холоднее 15 °C, продукты, вызывающие брожение и метеоризм (цельное молоко, белокочанная капуста, бобовые, огурцы), желтки, субпродукты; добавлены продукты, мягко стимулирующие кишечник (борьба с запорами).\n- В педиатрии: при ревматизме без НК — общий стол, а при СН — ограничение соли и жидкости [Е]; уход в кардиологии — стол № 10 [Е, З]."}},{"id":"ccc-178","text":{"text":"**Разгрузочные диеты при ХСН** [О]: белковые, углеводные, комбинированные или их чередование."}},{"id":"ccc-179","text":{"text":"- **Молочная (диета Карелля, 1865)** — снятое молоко 0,8–3 л/сут при постельном режиме; в 1-ю неделю по 200 мл 4 раза, затем яйца, сухари, переход на обычную пищу. Вариант: молоко/кефир/простокваша по 200–250 мл через 2–2,5 ч, 6 раз (1,2–1,5 л).\n- **Творожная** (выраженная СН): 500 г творога, 150 г сахара, 1–2 стакана отвара шиповника, 5 приёмов через 2–2,5 ч.\n- **Молочно-картофельная** (в т.ч. при СН): 1 кг картофеля + 0,5 л молока, без соли, 2–6 дней, 1200–1300 ккал. Яблочная и компотная — при гипертонической болезни (яблоки 250–300 г × 5 раз, 500–600 ккал; компот из 200 г сухофруктов по 1 стакану × 6, 750 ккал).\n- Табл. 4-2 (стартовые и разгрузочные диеты при ХСН): апельсиновая, картофельная, кефирная, молочная, огуречная, творожная, яблочная; Карелля-1 (900, 1100, 1200 мл снятого молока) и Карелля-2 (800, 1000, 1200 мл) — в среднем ~600 ккал, натрий 500 мг, калий 1460 мг; Певзнера–Карелля 1–3 (постепенно добавляют бессолевой хлеб, яйцо, рисовую кашу, сахар, картофельное пюре)."}},{"id":"ccc-180","heading":{"text":"Инструментальные методы и подготовка","level":2}},{"id":"ccc-181","text":{"text":"- **У детей** [З]: осмотр, перкуссия, аускультация; ЭКГ и её мониторирование, ФКГ, ЭхоКГ, функциональные пробы (велоэргометрия, «степ-тест», проба по Шалкову), клиноортостатическая проба, кардиоинтервалография; лекарственные пробы при аритмии (калиевая, пропранололовая, атропиновая); по показаниям — зондирование и ангиография сердца, электрофизиологическое исследование. Оценка — с позиций возрастной кардиологии. При НК в педиатрии широко применяют ЭКГ, ФКГ, сфигмографию и УЗИ.\n- **Рентгеноскопия/графия** [О]: размеры сердца и камер, крупных сосудов, смещение сердца, жидкость в перикарде; взвесь бария контрастирует пищевод — по его смещению судят об увеличении левого предсердия. Подготовка не нужна.\n- **Ангиокардиография** [О]: контраст через зонды в сосуды и полости сердца — фактически операция (кардиохирургия). Накануне — пробы на переносимость йода и анестетиков, натощак. После — особое внимание: при боли в сердце, одышке, нарушении ритма, падении АД, резкой слабости — сразу сообщить врачу.\n- **УЗИ:** эхокардиография (сердце) и допплерография (сосуды); для ЭхоКГ подготовка не нужна [О]. ЭКГ может сниматься уже в смотровом кабинете приёмного отделения [О]."}},{"id":"ccc-182","heading":{"text":"Пожилые и старые больные с болезнями ССС [О]","level":2}},{"id":"ccc-183","text":{"text":"- Основа особенностей — инволюция и прежде всего склероз сосудов и сердца: снижается эластичность аорты, венечных, мозговых и почечных артерий, растёт периферическое сопротивление; извитость и аневризмы капилляров и артериол, фиброз, гиалиноз, облитерация капилляров; неадекватное кровоснабжение органов.\n- Коронарная недостаточность → дистрофия, атрофия и замещение волокон соединительной тканью → атеросклеротический кардиосклероз → СН и аритмии; снижается сократимость, полости дилатируются. «Старческое сердце» — один из главных факторов СН.\n- Активируется свёртывание, слабеет противосвёртывающая система, ухудшается реология. Повышается главным образом систолическое АД (изолированная систолическая АГ > 140), снижаются венозное давление, сердечный выброс, мозговой, почечный, мышечный кровоток. Возрастных нормативов АД нет; часть специалистов считает повышение АД компенсаторным.\n- Сосудистая недостаточность у пожилых (например, при критическом падении температуры при пневмонии) проявляется не классическим коллапсом, а обострением ИБС, инсультом, усилением почечной недостаточности.\n- Ухудшение ИБС провоцируют бронхолёгочные болезни, физнагрузка, переедание, стресс, инфекции, воспаление мочевых путей, операции.\n- Медсестра объясняет вред курения: после сигареты учащаются и усиливаются сокращения, сужаются сосуды, растёт АД; у курильщиков чаще злокачественная АГ, хуже эффект лечения, смертность от болезней ССС почти вдвое выше.\n- Нужны дневной отдых и спокойный ночной сон, упражнения на расслабление, умеренно калорийный и богатый витаминами рацион без животных жиров, сладостей и перекусов (лишний вес мешает сердцу); регулярная физкультура и дыхательная гимнастика."}}]},{"id":"ccc-s99","title":"Самоконтроль по теме","blocks":[{"id":"ccc-q-001","text":{"text":"Ответы проверяются сразу на странице, результат никуда не сохраняется."}},{"id":"ccc-q-002","quiz":{"title":"АФО, пульс и АД у детей","questions":[{"text":"Систолическое АД ребёнка 6 лет по формуле для детей старше года:","options":["96 мм рт. ст.","106 мм рт. ст.","112 мм рт. ст.","88 мм рт. ст."],"correct":[1],"explanation":"100 + n, где n — возраст в годах: 100 + 6 = 106 (допускаются колебания ±15)."},{"text":"Нормальная частота пульса у новорождённого:","options":["60–80 в минуту","90–100 в минуту","120–140 в минуту","160–180 в минуту"],"correct":[2],"explanation":"У новорождённого пульс 120–140 в минуту [Е, З]."},{"text":"Ширина манжеты, которая занижает показатели АД:","options":["Узкая","Широкая","Ширина не влияет"],"correct":[1],"explanation":"Узкая манжетка завышает, широкая — занижает показатели [Е]."},{"text":"Анатомическое закрытие овального окна происходит к:","options":["2–3 мес","5–6 мес","1 году","3 годам"],"correct":[1],"explanation":"Овальное окно закрывается анатомически к 5–6 мес [З]."}]}},{"id":"ccc-q-003","quiz":{"title":"Методика исследования пульса и АД","questions":[{"text":"При ритмичном пульсе пульс считают:","options":["10 с и умножают на 6","15 с и умножают на 4","Всегда ровно 1 мин","30 с и умножают на 2"],"correct":[1],"explanation":"При ритмичном пульсе — 15 с × 4; при аритмии — полную минуту [О]."},{"text":"Скорость выпуска воздуха из манжеты при измерении АД:","options":["2 мм рт. ст. в секунду","10 мм рт. ст. в секунду","Как можно быстрее","1 мм рт. ст. в 5 секунд"],"correct":[0],"explanation":"2 мм рт. ст./с; медленнее — занижение АД [О]."},{"text":"Почему пульс на сонной артерии исследуют только с одной стороны?","options":["Пульс там слабый","Это рефлексогенная зона: опасно резкое урежение ЧСС","Так быстрее","Мешает щитовидная железа"],"correct":[1],"explanation":"Сдавление каротидного синуса может резко урежать ЧСС вплоть до потери сознания [О]."},{"text":"Как отмечают пульс и АД в температурном листе?","options":["Пульс — красными точками, АД — красными столбиками","Пульс — синими точками, АД — синей линией","Только цифрами в истории болезни"],"correct":[0],"explanation":"Пульс — красными точками по шкале пульса, АД — красными столбиками [О]."}]}},{"id":"ccc-q-004","quiz":{"title":"Неотложные состояния","questions":[{"text":"Положение пациента при сердечной астме:","options":["Лёжа с приподнятым ножным концом","Сидя с опущенными ногами (ортопноэ)","На левом боку","Лёжа на животе"],"correct":[1],"explanation":"Сидя с опущенными ногами кровь депонируется в сосудах ног и живота, малый круг разгружается [О]."},{"text":"Положение при обмороке и коллапсе:","options":["Горизонтально с приподнятыми ногами","Полусидя","Сидя с опущенными ногами"],"correct":[0],"explanation":"Приподнятый ножной конец улучшает приток крови к мозгу [О, Е]."},{"text":"Что противопоказано при гипоксемическом (одышечно-цианотическом) приступе?","options":["Кислород","Сердечные гликозиды и мочегонные","Седативные средства","Коррекция ацидоза"],"correct":[1],"explanation":"При приступе сердечные гликозиды и мочегонные противопоказаны [Е]."},{"text":"Нитроглицерин при отёке лёгких дают, если систолическое АД:","options":["не ниже 100 мм рт. ст.","ниже 90 мм рт. ст.","при любом АД"],"correct":[0],"explanation":"Нитроглицерин — при систолическом АД не менее 100 мм рт. ст. [О]."}]}},{"id":"ccc-q-005","quiz":{"title":"Болезни и диеты","questions":[{"text":"Возбудитель, с которым связан ревматизм:","options":["Золотистый стафилококк","β-гемолитический стрептококк группы А","Вирус Коксаки","Пневмококк"],"correct":[1],"explanation":"ОРЛ связана с β-гемолитическим стрептококком группы А [Е, З]."},{"text":"Отличительная черта ревматического артрита:","options":["Деформация суставов","Проходит без деформаций","Поражает мелкие суставы кистей","Не отвечает на лечение"],"correct":[1],"explanation":"Летучий, симметричный, проходит за несколько дней без деформаций [Е, З]."},{"text":"Диета при инфаркте миокарда:","options":["№ 10","№ 10а","№ 10с","№ 10и"],"correct":[3],"explanation":"№ 10и — три последовательных рациона [О]."},{"text":"Самый частый «синий» порок:","options":["ДМПП","ОАП","Тетрада Фалло","Коарктация аорты"],"correct":[2],"explanation":"Тетрада Фалло — самый частый порок с цианозом."}]}}]},{"id":"sources","title":"Источники","blocks":[{"id":"ccc-001","text":{"text":"В тексте источник отмечен буквой в квадратных скобках."}},{"id":"ccc-002","table":{"caption":"","header":true,"rows":[{"cells":["Метка","Учебник","Что взято по ССС"]},{"cells":["[Е]","Ежова Н.В., Русакова Е.М., Кащеева Г.И. «Педиатрия», 8-е изд., Минск, 2014","Гл. 11 «АФО ССС. Болезни органов кровообращения» (с. 308–331): АФО, ВПС, ревматизм, работа медсестры; гл. 16 «Неотложная помощь»: лёгочно-сердечная реанимация, недостаточность кровообращения (с. 424–437); кардиореспираторная адаптация новорождённого (с. 23); ВПС в структуре пороков развития (с. 198)"]},{"cells":["[З]","Запруднов А.М., Григорьев К.И. «Педиатрия с детскими инфекциями», ГЭОТАР-Медиа, 2011","АФО ССС (с. 53–56); адаптация новорождённого (с. 106); гл. 16 «Болезни ССС» (с. 271–291): неревматический кардит, кардиомиопатии, ВПС, ВСД, уход; гл. 17.2 «Ревматическая лихорадка» (с. 294–297); поражение сердца при СКВ (с. 303); гл. 42 «Острые нарушения кровообращения» (с. 504–509)"]},{"cells":["[О]","«Общий уход за больными в терапевтической клинике» (учебное пособие; авторы в файле не указаны)","Гл. 13 «Наблюдение и уход за больными с заболеваниями органов кровообращения» (с. 153–161); диеты №10, 10а, 10с, 10и и разгрузочные диеты при ХСН (гл. 4); рентгенологическое исследование ССС, ЭхоКГ (гл. 10); транспортировка (гл. 2); пожилые с заболеваниями ССС (гл. 16); реанимация (гл. 17)"]}]}},{"id":"ccc-003","text":{"text":"Учебник [З] — скан, текст распознан автоматически; цифры сверены по смыслу, но при сомнении проверяйте по странице оригинала."}}]}]}$json$::jsonb AS j) v
