UPDATE "library_manuals" SET "title" = 'Методика зондовых процедур, клизм и ухода при заболеваниях органов пищеварения', "annotation" = 'Методика: введение желудочного зонда, промывание желудка, фракционное и дуоденальное зондирование, кормление, клизмы, газоотводная трубка, помощь при рвоте и кровотечении, подготовка к исследованиям и сбор кала — с оснащением, алгоритмами, типичными ошибками, ситуационными задачами и самоконтролем.',
  "published" = v.j, "draft" = CASE WHEN "draft_changed" THEN "draft" ELSE v.j END, "updated_at" = now()
FROM (SELECT $json${"sections":[{"id":"nursing_gi_t2-s01","title":"Методические указания","blocks":[{"id":"nursing_gi_t2-001","text":{"text":"Акцент — на **методике**: что и в каком порядке делает медсестра, зачем нужен каждый шаг и как оценить результат."}},{"id":"nursing_gi_t2-002","heading":{"text":"Цель занятия","level":2}},{"id":"nursing_gi_t2-003","text":{"text":"Освоить методику зондовых процедур, клизм и сестринского ухода при заболеваниях органов пищеварения у взрослых и детей."}},{"id":"nursing_gi_t2-004","heading":{"text":"Студент должен","level":2}},{"id":"nursing_gi_t2-005","text":{"text":"**Знать:** виды зондов и их назначение; формулы длины введения зонда; показания и противопоказания к промыванию желудка, зондированию, клизмам; порции желчи; правила подготовки к исследованиям ЖКТ и сбора кала; первую помощь при рвоте и желудочно-кишечном кровотечении."}},{"id":"nursing_gi_t2-006","text":{"text":"**Уметь:**\n- рассчитать длину и ввести желудочный зонд взрослому и ребёнку;\n- промыть желудок, в том числе при отравлениях у детей;\n- провести фракционное желудочное и дуоденальное зондирование, оформить пробирки;\n- ввести газоотводную трубку, поставить очистительную, сифонную, послабляющую и лекарственную клизмы;\n- оказать помощь при рвоте и желудочно-кишечном кровотечении;\n- подготовить пациента к рентгенологическим и эндоскопическим исследованиям, к УЗИ; собрать кал."}},{"id":"nursing_gi_t2-007","heading":{"text":"Схема ответа по манипуляции","level":2}},{"id":"nursing_gi_t2-008","checklist":{"title":"Каждая манипуляция разобрана по этой схеме","ordered":true,"steps":["Цель — зачем выполняют.","Показания и противопоказания.","Оснащение.","Подготовка пациента: объяснить ход, получить согласие, придать положение, снять зубные протезы.","Алгоритм — по шагам, с обоснованием.","Оценка результата: что получено, куда отправить, как записать.","Типичные ошибки и безопасность."]}},{"id":"nursing_gi_t2-009","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Дезинфекция — по действующим нормам","text":"Пособие даёт режимы прошлых лет: зонд и воронку — в 3% хлорамин Б на 1 ч, у детей — кипятить 15–20 мин. Сейчас зонды, наконечники и системы применяют одноразовые, а многоразовые изделия обрабатывают по СанПиН 3.3686-21 и инструкциям к дезсредствам. Отвечайте по стандарту кафедры."}},{"id":"nursing_gi_t2-010","glossary":{"terms":[{"term":"Зондирование","definition":"инструментальное исследование полых и трубчатых органов, каналов, свищевых ходов и ран с помощью зондов (франц. sonder — исследовать)."},{"term":"Зонд","definition":"эластичная трубка или комбинация трубок для извлечения содержимого органов ЖКТ и введения в них жидкостей."},{"term":"Холекинетики","definition":"раздражители, вызывающие сокращение желчного пузыря при дуоденальном зондировании (магния сульфат, глюкоза 40%, растительное масло)."},{"term":"Мелена","definition":"чёрный дёгтеобразный стул при кровотечении из верхних отделов ЖКТ."},{"term":"Гематемезис","definition":"кровавая рвота."},{"term":"Тенезмы","definition":"ложные болезненные позывы на дефекацию."},{"term":"Микроклизма","definition":"клизма объёмом 50–200 мл; макроклизма — 1,5–12 л."},{"term":"Сипинг","definition":"приём питательной смеси в виде напитка через трубочку мелкими глотками."}]}}]},{"id":"nursing_gi_t2-s02","title":"Введение желудочного зонда","blocks":[{"id":"nursing_gi_t2-011","text":{"text":"Зондирование желудка нужно для трёх процедур: **промывание желудка, исследование желудочного сока, искусственное питание**."}},{"id":"nursing_gi_t2-012","table":{"caption":"","header":true,"rows":[{"cells":["Этап","Содержание"]},{"cells":["Выбор зонда","Толстый (взрослый — диаметр 10–15 мм, метки 45, 55, 65 см) — промывание, одномоментное извлечение содержимого. Тонкий (5–9 мм; детский № 10–15, 3–5 мм) — фракционное исследование, кормление; можно вводить через нос"]},{"cells":["Оснащение","Зонд, жидкое вазелиновое масло, роторасширитель, языкодержатель, металлический напальчник, перчатки, клеёнчатые фартуки, пелёнка"]},{"cells":["Положение","Взрослый — сидя на стуле, спина плотно к спинке, голова слегка наклонена вперёд"]}]}},{"id":"nursing_gi_t2-014","table":{"caption":"Длина введения зонда","header":true,"rows":[{"cells":["Кому","Формула"]},{"cells":["Взрослый","l = рост (см) − 100; рост 170 см → 70 см"]},{"cells":["Ребёнок, ориентировочно","расстояние от переносицы до пупка"]},{"cells":["Ребёнок, точнее","20 + n см, n — возраст в годах; 5 лет → 25 см"]}]}},{"id":"nursing_gi_t2-015","checklist":{"title":"Алгоритм введения желудочного зонда (взрослый)","ordered":true,"steps":["Объяснить пациенту ход процедуры; снять съёмные зубные протезы.","Усадить на стул: спина плотно к спинке, голова слегка наклонена вперёд.","Рассчитать длину введения: рост − 100 см.","Надеть перчатки и фартук; шею и грудь пациента укрыть пелёнкой или фартуком.","Достать стерильный зонд из пакета, смочить слепой конец водой или смазать вазелином.","Встать сзади или сбоку, попросить открыть рот; при необходимости — роторасширитель или палец в напальчнике между коренными зубами.","Положить слепой конец на корень языка, попросить делать глотательные движения и глубоко дышать носом.","По мере глотания медленно продвигать зонд до нужной метки."]}},{"id":"nursing_gi_t2-016","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Почему именно так","text":"- **Наклон головы вперёд** — зонд идёт в пищевод, а не в трахею.\n- **Глубокое дыхание носом** подавляет рвотный рефлекс.\n- **Продвигать только во время глотания** — пищевод открывается при глотательном движении.\n- **Протезы снимают обязательно** — их можно аспирировать или проглотить."}},{"id":"nursing_gi_t2-017","heading":{"text":"Особенности у детей","level":2}},{"id":"nursing_gi_t2-018","text":{"text":"- **Грудной возраст** — уложить на бок, лицом слегка вниз.\n- **Дошкольник** — помощник берёт на руки, оборачивает пелёнкой, зажимает ноги ребёнка между своими, прижимает голову к плечу; вторая медсестра быстрым движением вводит зонд за корень языка и **без насилия** продвигает во время глотания.\n- **Старшие дети** — сидя на стуле, грудь закрыта фартуком или пелёнкой.\n- **Зонд в желудке**, если прекратились рвотные движения и идёт прозрачный или слегка мутный сок."}},{"id":"nursing_gi_t2-019","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Безопасность","text":"Силу не применять: слизистая пищевода у детей нежная, легко ранима. При рвотных позывах — глубоко дышать носом. При появлении крови процедуру прекратить."}}]},{"id":"nursing_gi_t2-s03","title":"Промывание желудка","blocks":[{"id":"nursing_gi_t2-020","table":{"caption":"","header":true,"rows":[{"cells":["Этап","Содержание"]},{"cells":["Цели","Диагностическая, лечебная, профилактическая: удаление недоброкачественной пищи, ядов, лекарств, токсинов"]},{"cells":["Показания","Острые пищевые (пища, грибы, алкоголь) и лекарственные отравления; повторная рвота при кишечных инфекциях; аллерген, поступивший в ЖКТ при анафилактическом шоке (после выведения из коллапса)"]},{"cells":["Противопоказания","Кровотечение из ЖКТ, ожоги пищевода и желудка, бронхиальная астма, инфаркт миокарда, нарушения мозгового кровообращения. У детей — также поздние сроки (позже 2 ч) после отравления щелочами и коррозивными ядами, судорожный синдром"]},{"cells":["Оснащение","Толстый желудочный зонд, воронка 1 л, ведро чистой воды комнатной температуры, кружка 1 л, таз, вазелиновое масло, роторасширитель, языкодержатель, перчатки, фартуки; ёмкость для промывных вод в лабораторию"]}]}},{"id":"nursing_gi_t2-021","checklist":{"title":"Алгоритм промывания желудка (взрослый)","ordered":true,"steps":["Ввести толстый зонд до нужной метки.","Подсоединить воронку и опустить её с наклоном до уровня колен — выльется содержимое желудка.","Налить в воронку 1 л воды и медленно поднимать, пока вода не дойдёт до устья воронки, но не ниже.","Опустить воронку ниже колен и слить содержимое в таз.","Повторять, пока промывные воды не станут чистыми.","Отсоединить воронку, осторожно извлечь зонд.","Дать прополоскать рот, обеспечить покой.","При необходимости отправить первую порцию промывных вод в лабораторию (бактериологическую, токсикологическую).","Обработать зонд и воронку."]}},{"id":"nursing_gi_t2-022","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Почему именно так","text":"- Промывание работает по **закону сообщающихся сосудов**: поднятая воронка — жидкость в желудок, опущенная ниже желудка — обратно в таз.\n- Вода **не должна уйти из воронки полностью**: в зонд попадёт воздух, и сифон прервётся.\n- **Первую порцию** берут на анализ: в ней больше всего яда или возбудителя."}},{"id":"nursing_gi_t2-023","heading":{"text":"Особенности у детей и при отравлениях","level":2}},{"id":"nursing_gi_t2-024","text":{"text":"- Воронка около 500 мл; детям раннего возраста жидкость удобнее вводить 20-граммовым шприцем. Растворы: вода, 2% натрия гидрокарбонат, светло-розовый раствор перманганата калия.\n- **Детям до 3 лет — изотонический раствор NaCl**: вода быстро всасывается, возможно водное отравление.\n- Промывают не позже чем через 2 ч после попадания яда; **через 2–3 ч промывание повторяют** — в складках слизистой остаются таблетки, а некоторые яды снова выделяются из крови в желудок.\n- **Кислоты и щёлочи**: сначала обезболивание по назначению врача; зонд на всю длину смазывают растительным маслом.\n- **Бензин, керосин**: перед промыванием — вазелиновое масло; **молоко и касторовое масло запрещены** — усиливают всасывание.\n- При отравлениях промывание часто сочетают с сифонной клизмой."}},{"id":"nursing_gi_t2-025","table":{"caption":"","header":true,"rows":[{"cells":["Ошибка","Чем опасна"]},{"cells":["Промывание при кровотечении из ЖКТ, ожоге пищевода","Усиление кровотечения, перфорация"]},{"cells":["Ребёнку до 3 лет — простая вода","Водное отравление"]},{"cells":["Воздух в системе (воронку опустошили)","Сифон прерывается, промывные воды не выходят"]},{"cells":["Промывание ребёнку с судорожным синдромом","Аспирация промывных вод"]},{"cells":["Молоко при отравлении бензином","Усиливается всасывание яда"]}]}}]},{"id":"nursing_gi_t2-s04","title":"Фракционное исследование желудочной секреции","blocks":[{"id":"nursing_gi_t2-026","text":{"text":"**Цель:** оценить кислотообразующую функцию желудка натощак и после стимуляции."}},{"id":"nursing_gi_t2-027","text":{"text":"**Противопоказания:** артериальная гипертензия, выраженная хроническая сердечная недостаточность, аневризма аорты, острые отравления, ожоги пищевода и желудка, кровотечение из ЖКТ."}},{"id":"nursing_gi_t2-028","text":{"text":"**Оснащение:** тонкий зонд, шприц 20 мл, раздражитель, штатив с пронумерованными пробирками, спирт, ватные шарики, часы-таймер; при парентеральном раздражителе — антигистаминные препараты и противошоковый набор."}},{"id":"nursing_gi_t2-029","checklist":{"title":"Схема с энтеральным раздражителем (взрослый)","ordered":true,"steps":["Утром натощак ввести тонкий зонд (рост − 100 см).","Порция 1 — всё содержимое желудка натощак, извлекать шприцем 5 мин.","Ввести через зонд 300 мл подогретого энтерального раздражителя (капустный отвар, мясной бульон).","Порция 2 — через 10 мин извлечь 10 мл.","Порция 3 — через 15 мин извлечь весь остаток пробного завтрака.","Порции 4–7 — каждые 15 мин в течение часа."]}},{"id":"nursing_gi_t2-030","checklist":{"title":"Схема с парентеральным раздражителем","ordered":true,"steps":["Порция 1 — содержимое натощак, 5 мин.","Порции 2–5 — каждые 15 мин в течение часа (базальная секреция).","Ввести гистамин или пентагастрин подкожно по назначению врача.","Порции 6–9 — каждые 15 мин в течение часа (стимулированная секреция)."]}},{"id":"nursing_gi_t2-031","text":{"text":"У детей: 4 базальные порции через каждые 15 мин, затем стимулятор и 4 порции стимулированной секреции через каждые 15 мин."}},{"id":"nursing_gi_t2-032","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Остановить процедуру","text":"При появлении крови в содержимом процедуру немедленно прекращают. Пробирки нумеруют, в направлении указывают вид раздражителя."}},{"id":"nursing_gi_t2-033","text":{"text":"**Внутрижелудочная рН-метрия** — наиболее информативный метод оценки кислотообразования, возрастных ограничений нет. Длина рН-зонда у ребёнка — X = 0,2Y + 1,5 см (Y — рост); стандартное исследование 2–3 ч, при гастроэзофагеальном рефлюксе — суточный мониторинг."}}]},{"id":"nursing_gi_t2-s05","title":"Дуоденальное зондирование","blocks":[{"id":"nursing_gi_t2-034","table":{"caption":"","header":true,"rows":[{"cells":["Этап","Содержание"]},{"cells":["Цели","Диагностическая — исследование желчного пузыря и желчевыводящих путей (порции А, В, С); лечебная — отток желчи, введение лекарств"]},{"cells":["Противопоказания","Острый холецистит, обострение хронического холецистита и ЖКБ, опухоли ЖКТ, кровотечения из ЖКТ"]},{"cells":["Подготовка","За 3 дня — на ночь сладкий чай и грелка на правое подреберье; сладкий чай не дают при сахарном диабете, грелку не кладут при подозрении на лямблиоз. Утром — натощак"]},{"cells":["Оснащение","Стерильный дуоденальный зонд с оливой, раздражитель (25% магния сульфат 40–50 мл, 40% глюкоза 30–40 мл или растительное масло 40 мл), штатив с пронумерованными пробирками, шприц Жане, зажим, валик, полотенце, перчатки, грелка"]}]}},{"id":"nursing_gi_t2-035","checklist":{"title":"Алгоритм дуоденального зондирования (взрослый)","ordered":true,"steps":["Усадить пациента, положить оливу на корень языка; пациент глотает и дышит носом.","Когда зонд дошёл до желудка, наложить зажим на свободный конец.","Уложить на правый бок без подушки, ноги согнуты, под таз — валик, под правое подреберье — тёплая грелка.","Пациент медленно заглатывает зонд 20–60 мин до метки 70 см.","Опустить конец зонда в пробирку, снять зажим — порция А (золотисто-жёлтая), 2–3 пробирки.","Уложить на спину, шприцем Жане ввести раздражитель, наложить зажим.","Через 10–15 мин снова на правый бок, снять зажим — порция В (густая, тёмно-оливковая), до 60 мл за 20–30 мин.","Собрать порцию С (прозрачная, золотисто-жёлтая), 15–20 мл за 20–30 мин.","Извлечь зонд, обработать; пробирки с направлением — в лабораторию."]}},{"id":"nursing_gi_t2-036","table":{"caption":"","header":true,"rows":[{"cells":["Порция","Откуда","Вид у взрослого","Объём и время"]},{"cells":["А","Дуоденальная","Золотисто-жёлтая","2–3 пробирки"]},{"cells":["В","Пузырная","Густая, тёмно-оливковая","До 60 мл за 20–30 мин"]},{"cells":["С","Печёночная","Прозрачная, золотисто-жёлтая","15–20 мл за 20–30 мин"]}]}},{"id":"nursing_gi_t2-037","callout":{"tone":"MANUAL_CALLOUT_TONE_CLINICAL","title":"Если что-то пошло не так","text":"- **Желчь не поступает** — зонд мог свернуться в желудке: немного подтянуть назад или проверить положение рентгенологически.\n- **Порция В не идёт** — вероятен спазм сфинктера Одди; по назначению врача 1 мл 0,1% атропина подкожно."}},{"id":"nursing_gi_t2-038","text":{"text":"**У детей:** стоя измерить расстояние от резцов до пупка и отметить на зонде; при рвотном позыве — зажать зонд губами и глубоко дышать; на правом боку на валике с грелкой желчь появляется через 30–60 мин; раздражитель — 20–50 мл 25% магния сульфата; вся процедура 2–2,5 ч."}},{"id":"nursing_gi_t2-039","text":{"text":"**Беззондовый тюбаж** — утром натощак выпить подогретую до 35–42 °C негазированную минеральную воду (до 7 лет — полстакана, старше — стакан), лечь на правый бок с грелкой под правое подреберье на 40–60 мин."}}]},{"id":"nursing_gi_t2-s06","title":"Искусственное питание","blocks":[{"id":"nursing_gi_t2-040","text":{"text":"**Показания:** поражения языка, глотки, гортани, пищевода; нарушение глотания (после операции, инсульт, ботулизм, ЧМТ); непроходимость желудка; кома; отказ от пищи при психическом заболевании; терминальная кахексия."}},{"id":"nursing_gi_t2-041","text":{"text":"**Противопоказания к энтеральному питанию:** кишечная непроходимость, острый панкреатит, тяжёлая мальабсорбция, продолжающееся кровотечение из ЖКТ, шок, анурия, аллергия на компоненты смеси, неукротимая рвота."}},{"id":"nursing_gi_t2-042","table":{"caption":"","header":true,"rows":[{"cells":["Путь","Способ"]},{"cells":["Сипинг","Смесь в виде напитка через трубочку мелкими глотками"]},{"cells":["Зонд","Назогастральный, назодуоденальный, назоеюнальный, двухканальный"]},{"cells":["Стома","Гастростома, дуоденостома, еюностома"]}]}},{"id":"nursing_gi_t2-043","text":{"text":"Смесь вводят фракционно (например, 8 раз по 50 мл или 4 раза по 300 мл), капельно или через помпу. Модульные смеси не сбалансированы — только дополнение рациона. Ректальное питание не применяют: в толстой кишке не всасываются жиры и аминокислоты."}},{"id":"nursing_gi_t2-044","checklist":{"title":"Алгоритм пассивного кормления тяжелобольного","ordered":true,"steps":["Проветрить палату, вымыть пациенту руки.","Придать положение сидя или полусидя; на строгом постельном режиме — голова под углом 30–35° к туловищу.","Покрыть шею и грудь салфеткой.","Одной рукой приподнять голову вместе с подушкой, другой кормить с ложки малыми порциями.","Поить из поильника или через трубочку.","После еды прополоскать рот (или обработать полость рта) и вымыть пациенту руки."]}},{"id":"nursing_gi_t2-045","text":{"text":"**Новорождённые и недоношенные:** зонд — при отсутствии сосательного и глотательного рефлексов, одышке или цианозе при сосании, ИВЛ, расщелине нёба; кормят порционно 7–8 раз в сутки или длительной инфузией шприцевым насосом."}}]},{"id":"nursing_gi_t2-s07","title":"Клизмы и газоотводная трубка","blocks":[{"id":"nursing_gi_t2-046","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Абсолютные противопоказания ко всем клизмам","text":"Желудочно-кишечное кровотечение, острое воспаление толстой кишки и области ануса, рак прямой кишки, острый аппендицит, перитонит, первые дни после операций на ЖКТ, кровотечение из геморроидальных узлов, выпадение прямой кишки."}},{"id":"nursing_gi_t2-047","heading":{"text":"Очистительная клизма","level":2}},{"id":"nursing_gi_t2-048","text":{"text":"**Показания:** запоры, отравления, подготовка к операции, родам, рентгену, эндоскопии, УЗИ, перед лекарственной клизмой. **Оснащение:** кружка Эсмарха до 2 л, трубка (просвет 1 см, длина 1,5 м), кран, наконечник, вазелин, клеёнка, пелёнка, таз, перчатки, фартук, маска."}},{"id":"nursing_gi_t2-049","checklist":{"title":"Алгоритм постановки очистительной клизмы (взрослый)","ordered":true,"steps":["Вымыть руки, надеть маску, фартук, перчатки.","Налить в кружку 1–1,5 л воды нужной температуры, подвесить на 1 м над пациентом.","Заполнить систему, выпустить воздух, закрыть кран.","Таз на пол; на кушетку — клеёнку (свисает в таз) и пелёнку.","Уложить пациента на левый бок, колени подтянуть к животу; если двигаться нельзя — на спине на судне.","Наконечник смазать вазелином, ввести вращательно 3–4 см по направлению к пупку, затем параллельно позвоночнику — всего на 7–8 см.","Открыть кран; при боли — остановить. Если вода не идёт — поднять кружку, сдвинуть наконечник на 1–2 см или заменить.","Закрыть кран, извлечь наконечник; пациент сжимает ягодицы и удерживает воду 5–10 мин.","Проверить эффект; если вышла почти одна вода — после осмотра врачом повторить.","Обработать систему."]}},{"id":"nursing_gi_t2-050","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Почему именно так","text":"- **Левый бок** — сигмовидная и нисходящая кишка расположены слева, вода проходит по ходу кишки.\n- **Сначала к пупку, потом вдоль позвоночника** — так наконечник повторяет изгиб анального канала и прямой кишки.\n- **Воздух из системы выпускают** — он растягивает кишку и вызывает боль.\n- **Температура**: обычно 37–39 °C; при атоническом запоре — холодная (до 12 °C), при спастическом — 37–42 °C."}},{"id":"nursing_gi_t2-051","heading":{"text":"Сифонная клизма","level":2}},{"id":"nursing_gi_t2-052","text":{"text":"Показания: неэффективность очистительной клизмы, отравления, подготовка к операции на кишке, подозрение на толстокишечную непроходимость. Пациент на левом боку; толстый желудочный зонд вводят на 30–40 см; воронку с 1 л воды поднимают на 0,5 м, у устья опускают ниже тела и сливают в таз; всего 10–12 л воды 37 °C до чистых промывных вод. Вода не должна уходить ниже устья воронки. **Выделенной жидкости должно быть больше, чем введённой.** Пациенты переносят процедуру тяжело — постоянное наблюдение. У детей — 5–10 л, трубку на 20–30 см, только под контролем врача."}},{"id":"nursing_gi_t2-053","heading":{"text":"Послабляющие, лекарственная и питательная клизмы","level":2}},{"id":"nursing_gi_t2-054","table":{"caption":"","header":true,"rows":[{"cells":["Клизма","Состав и объём","Температура","Главное"]},{"cells":["Гипертоническая","50–100 мл 10% NaCl или 20–30% магния сульфата","37–38 °C","Удерживать 20–30 мин лёжа"]},{"cells":["Масляная","100–200 мл растительного или вазелинового масла","37–38 °C","На ночь; эффект через 10–12 ч"]},{"cells":["Лекарственная","50–100 мл","39–40 °C","За 30 мин — очистительная клизма; после — лежать 1 ч"]},{"cells":["Питательная","до 200 мл (физраствор, глюкоза)","39–40 °C","1–2 раза в сутки"]}]}},{"id":"nursing_gi_t2-055","text":{"text":"Лекарственную и питательную клизмы делают тёплыми (39–40 °C): более холодный раствор вызывает позыв на дефекацию, и лекарство не всасывается."}},{"id":"nursing_gi_t2-056","heading":{"text":"Клизмы у детей","level":2}},{"id":"nursing_gi_t2-057","table":{"caption":"","header":true,"rows":[{"cells":["Возраст","Объём очистительной клизмы"]},{"cells":["1–5 мес","30–60 мл"]},{"cells":["6–12 мес","120–180 мл"]},{"cells":["1–2 года","до 200 мл"]},{"cells":["3–5 лет","до 300 мл"]},{"cells":["6–11 лет","до 400 мл"]},{"cells":["12–14 лет","500 мл и более"]}]}},{"id":"nursing_gi_t2-058","text":{"text":"Наконечник у младших вводят на 3–5 см, у старших на 6–8 см. Очистительная клизма ребёнку — при отсутствии стула 3 дня и более."}},{"id":"nursing_gi_t2-059","heading":{"text":"Газоотводная трубка","level":2}},{"id":"nursing_gi_t2-060","text":{"text":"Основное средство при метеоризме. Трубка 40 см, внутренний диаметр 5–10 мм."}},{"id":"nursing_gi_t2-061","checklist":{"title":"Алгоритм введения газоотводной трубки (взрослый)","ordered":true,"steps":["Уложить пациента на левый бок, подложить клеёнку; рядом — судно, на треть заполненное водой.","Закруглённый конец смазать вазелином на 20–30 см.","Перегнуть трубку посередине, зажать свободный конец.","Ввести вращательными движениями на 20–30 см; свободный конец опустить в судно с водой.","Через 1 ч извлечь трубку, обработать; провести туалет заднего прохода."]}},{"id":"nursing_gi_t2-062","text":{"text":"Детям: перед введением — очистительная клизма; трубка 3–5 мм, снаружи остаётся 10–15 см; держать 20–30 мин, при необходимости повторить через 3–4 ч."}}]},{"id":"nursing_gi_t2-s08","title":"Уход при симптомах заболеваний органов пищеварения","blocks":[{"id":"nursing_gi_t2-063","heading":{"text":"Рвота","level":2}},{"id":"nursing_gi_t2-064","checklist":{"title":"Алгоритм помощи при рвоте","ordered":true,"steps":["Пациента без сознания или ослабленного уложить на бок или полусидя, голова наклонена вниз; на спине лежать нельзя.","Поставить таз на пол, к углу рта — лоток или полотенце.","Не оставлять пациента одного, не допускать аспирации.","После рвоты прополоскать рот (тяжёлым — обработать тампоном), уложить, укрыть.","Рвотные массы собрать в отдельную градуированную ёмкость с крышкой и сохранить до прихода врача.","Сообщить врачу."]}},{"id":"nursing_gi_t2-065","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Рвота с кровью","text":"«Кофейная гуща» — кровотечение из желудка или ДПК; рвота тёмной неизменённой кровью со сгустками — из вен пищевода. Уложить, приподнять ножной конец, срочно вызвать врача, пузырь со льдом на эпигастрий, контролировать пульс и АД."}},{"id":"nursing_gi_t2-066","heading":{"text":"Желудочно-кишечное кровотечение","level":2}},{"id":"nursing_gi_t2-067","text":{"text":"Достоверные признаки — **гематемезис** (кровавая рвота) и **мелена**; общие — слабость, головокружение, шум в ушах, обморок, бледность, частый слабый пульс, падение АД."}},{"id":"nursing_gi_t2-068","checklist":{"title":"Первая помощь при желудочно-кишечном кровотечении","ordered":true,"steps":["Вызвать врача.","Уложить; при низком АД — приподнять ножной конец; строгий постельный режим, не разговаривать.","Не давать есть и пить.","Положить пузырь со льдом на живот.","Вызвать лаборанта (гематокрит, гемоглобин), подготовить набор для определения группы крови и резус-фактора; кал и рвотные массы — на кровь.","Контролировать пульс и АД каждые 30 мин.","Кровоостанавливающие средства — по назначению врача."]}},{"id":"nursing_gi_t2-069","text":{"text":"После кровотечения: строгий постельный режим 3–5 суток, голод 24–48 ч, затем жидкая холодная или слегка подогретая пища (диета № 1а); медсестра сама кормит и поит пациента."}},{"id":"nursing_gi_t2-070","heading":{"text":"«Острый живот»","level":2}},{"id":"nursing_gi_t2-071","text":{"text":"Внезапная сильная боль, тошнота или рвота, задержка стула и газов, вздутие, «доскообразный» живот. Срочно вызвать врача, уложить, запретить еду и питьё. **До осмотра врача — никаких обезболивающих, слабительных, клизм и грелок**: они затрудняют диагностику."}},{"id":"nursing_gi_t2-072","heading":{"text":"Диарея и запор","level":2}},{"id":"nursing_gi_t2-073","text":{"text":"- **Диарея**: судно вместо унитаза (врач смотрит кал); подмывание после каждой дефекации; контроль пульса, АД, водного баланса, кратности и вида стула; ежедневное взвешивание; питьё не менее 1,5–2 л в сутки. До выяснения причины — отдельная палата и текущая дезинфекция. Детям — сразу дополнительная жидкость: после каждого жидкого стула до 2–3 лет 50–100 мл, старше 100–200 мл.\n- **Запор**: больше двигаться, 4-разовое питание, продукты, стимулирующие кишечник (кисломолочные, ржаной хлеб, овощи, чернослив, курага, растительное масло); исключить задерживающие (крепкий чай, какао, белый хлеб, рис, манка, кисели).\n- **Кал осматривают после каждого опорожнения; при крови — немедленно сообщить врачу.**"}}]},{"id":"nursing_gi_t2-s09","title":"Подготовка к исследованиям и сбор кала","blocks":[{"id":"nursing_gi_t2-074","table":{"caption":"","header":true,"rows":[{"cells":["Исследование","Подготовка"]},{"cells":["ФЭГДС","Ужин до 20:00; утром не есть, не пить, не курить"]},{"cells":["Рентген желудка и ДПК","3 дня диета без газообразующих продуктов (ржаной хлеб, картофель, бобовые, молоко, овощи, фрукты, соки); ужин до 20:00; очистительная клизма вечером и утром за 2 ч; слабительные нельзя; утром не есть, не пить, не курить"]},{"cells":["Ирригоскопия, колоноскопия","2–3 дня та же диета; накануне перед обедом 30 г касторового масла (нельзя при непроходимости); вечером клизмы с интервалом 1 ч до чистой воды, утром за 2 ч — то же; за 30 мин — газоотводная трубка"]},{"cells":["Пероральный лаваж (фортранс)","2 л после обеда накануне, 1,5–2 л утром; нельзя при НЯК, болезни Крона, непроходимости, неясных болях в животе"]},{"cells":["УЗИ брюшной полости","3 дня диета без газообразующих продуктов, при метеоризме — активированный уголь; ужин до 20:00; натощак, не пить и не курить"]}]}},{"id":"nursing_gi_t2-075","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Почему слабительные перед рентгеном желудка нельзя","text":"Слабительные усиливают газообразование, а газ в кишке мешает рассмотреть желудок и ДПК. Кишку очищают клизмами."}},{"id":"nursing_gi_t2-076","heading":{"text":"Сбор кала","level":2}},{"id":"nursing_gi_t2-077","text":{"text":"- **За 2–3 дня отменить** препараты висмута и железа, бария сульфат, активированный уголь, слабительные, ректальные свечи на жировой основе; масляные клизмы не ставить.\n- **Скрытая кровь**: 3 дня диета без мяса, печени, рыбы, яиц, томатов, зелёных овощей, гречки; зубы щёткой не чистить, полоскать рот 3% раствором соды.\n- **Копрология**: за 5 дней — пробная диета Шмидта или Певзнера."}},{"id":"nursing_gi_t2-078","checklist":{"title":"Алгоритм сбора кала на исследование","ordered":true,"steps":["Пациент опорожняет кишечник в сухое судно без воды и мочи.","Палочкой взять 5–10 г кала из разных мест во флакон, закрыть.","Оформить направление.","Доставить в лабораторию: в стационаре — в течение 1 ч, амбулаторно — в течение 8 ч; хранить при 3–5 °C, исследовать не позже 8–12 ч.","На бактериологическое исследование — стерильная пробирка с консервантом."]}},{"id":"nursing_gi_t2-079","text":{"text":"У детей: на яйца глистов и лямблии — горшок обдать кипятком, доставить за 30 мин; на энтеробиоз — соскоб деревянной лопаточкой с перианальных складок на стекло в каплю 50% глицерина или физраствора."}}]},{"id":"nursing_gi_t2-s10","title":"Ситуационные задачи","blocks":[{"id":"nursing_gi_t2-080","text":{"text":"Решите задачу письменно по схеме: проблемы пациента → что делает медсестра (по шагам) → обоснование. Затем сверьтесь с эталоном."}},{"id":"nursing_gi_t2-081","clinicalCase":{"title":"Задача 1. Отравление таблетками","condition":"Мальчик 2 лет 40 минут назад проглотил неизвестное количество таблеток бабушки. Сознание ясное, судорог нет. Врач назначил промывание желудка.","questions":["Какой раствор выбрать и почему?","Как уложить или удержать ребёнка при введении зонда?","Как рассчитать длину введения зонда?","Нужно ли повторять промывание?"],"answer":"- **Изотонический раствор NaCl**: детям до 3 лет простая вода опасна — быстро всасывается, возможно водное отравление.\n- Помощник берёт ребёнка на руки, оборачивает пелёнкой, зажимает ноги ребёнка между своими, прижимает голову к плечу; вторая медсестра быстро вводит зонд за корень языка и без насилия продвигает во время глотания.\n- Ориентировочно — от переносицы до пупка; точнее 20 + n = 20 + 2 = **22 см** от зубов до входа в желудок.\n- Да, **через 2–3 ч** — в складках слизистой остаются таблетки, часть яда снова выделяется в желудок. Первую порцию промывных вод — в лабораторию."}},{"id":"nursing_gi_t2-082","clinicalCase":{"title":"Задача 2. Дуоденальное зондирование","condition":"Пациентке 45 лет назначено дуоденальное зондирование. Она страдает сахарным диабетом. Через 70 мин после начала зондирования желчь в пробирку не поступает.","questions":["Какие ошибки можно допустить при подготовке этой пациентки?","Как уложить пациентку после того, как зонд дошёл до желудка?","Что делать, если желчь не поступает?"],"answer":"- При сахарном диабете **сладкий чай не дают**; грелка на правое подреберье — можно (нельзя при подозрении на лямблиоз).\n- На **правый бок без подушки**, ноги согнуты, под таз — валик, под правое подреберье — тёплая грелка; пациентка медленно заглатывает зонд до метки 70 см.\n- Зонд мог свернуться в желудке: немного подтянуть назад; при неудаче — проверить положение рентгенологически (по назначению врача)."}},{"id":"nursing_gi_t2-083","clinicalCase":{"title":"Задача 3. Ошибки при клизме","condition":"Студент ставит очистительную клизму: пациент лежит на правом боку, систему не заполнил, наконечник вводит сразу параллельно позвоночнику. Пациент жалуется на боль и вздутие.","questions":["Какие ошибки допущены?","Почему возникли боль и вздутие?","Опишите правильную методику."],"answer":"**Ошибки:** положение на правом боку (нужно на левом); воздух не выпущен из системы; наконечник введён без начального направления к пупку.\n\nВоздух растягивает кишку — отсюда боль и вздутие; неправильное направление травмирует слизистую.\n\n**Правильно:** левый бок, колени к животу; заполнить систему и выпустить воздух; наконечник, смазанный вазелином, ввести вращательно 3–4 см к пупку, затем параллельно позвоночнику — всего 7–8 см; кружка на 1 м над пациентом; при боли — остановить поступление воды; удерживать воду 5–10 мин."}},{"id":"nursing_gi_t2-084","clinicalCase":{"title":"Задача 4. Рвота «кофейной гущей»","condition":"Пациент 52 лет с язвенной болезнью пожаловался на слабость, головокружение, затем была рвота цвета «кофейной гущи». Пульс 108 в минуту, слабый; АД 95/60 мм рт. ст.","questions":["Какое осложнение развилось?","Алгоритм действий медсестры.","Как кормить пациента после остановки кровотечения?"],"answer":"**Желудочное кровотечение.**\n\nВызвать врача; уложить, приподнять ножной конец (АД низкое); строгий постельный режим, не разговаривать, не есть и не пить; пузырь со льдом на эпигастрий; сохранить рвотные массы до прихода врача; лаборант — гемоглобин, гематокрит; набор для группы крови и резус-фактора; пульс и АД каждые 30 мин; кровоостанавливающие — по назначению.\n\nГолод 24–48 ч, затем жидкая холодная или слегка подогретая пища — диета № 1а; медсестра сама кормит и поит пациента; постельный режим 3–5 суток."}},{"id":"nursing_gi_t2-085","clinicalCase":{"title":"Задача 5. Подготовка к рентгену желудка","condition":"Пациенту назначено рентгенологическое исследование желудка на пятницу. В среду он спрашивает, можно ли выпить слабительное в четверг вечером, «чтобы всё было чисто».","questions":["Что ответит медсестра?","Составьте план подготовки."],"answer":"Слабительные **нельзя**: они усиливают газообразование, а газ мешает исследованию. Кишку очищают клизмами.\n\nПлан: со среды 3 дня — диета без газообразующих продуктов (ржаной хлеб, картофель, бобовые, молоко, овощи, фрукты, соки); в четверг лёгкий ужин до 20:00 и очистительная клизма вечером; в пятницу очистительная клизма за 2 ч до исследования; утром не есть, не пить, не курить, лекарства не принимать."}}]},{"id":"nursing_gi_t2-s11","title":"Самоконтроль","blocks":[{"id":"nursing_gi_t2-086","quiz":{"title":"Методика зондовых процедур","questions":[{"text":"Положение головы взрослого при введении желудочного зонда:","options":["Запрокинута назад","Слегка наклонена вперёд","Повёрнута набок"],"correct":[1],"explanation":"Наклон вперёд направляет зонд в пищевод."},{"text":"Когда продвигают зонд?","options":["Во время глотательных движений","На вдохе, независимо от глотания","Быстро, одним движением до метки"],"correct":[0],"explanation":"Пищевод раскрывается при глотании."},{"text":"Почему вода не должна уходить из воронки полностью при промывании желудка?","options":["Закончится вода","Воздух прервёт сифон","Зонд выскочит"],"correct":[1],"explanation":"Промывание идёт по закону сообщающихся сосудов; воздух нарушает сифон."},{"text":"При какой ситуации промывание желудка противопоказано?","options":["Кровотечение из ЖКТ","Ожог пищевода","Пищевое отравление грибами","Повторная рвота при кишечной инфекции"],"correct":[0,1],"explanation":"Кровотечение и ожоги — противопоказания; отравления и рвота при кишечной инфекции — показания."},{"text":"Сколько длится сбор порций при фракционном исследовании с парентеральным раздражителем?","options":["30 мин","2 ч (час базальной и час стимулированной секреции)","4 ч"],"correct":[1],"explanation":"Порции 2–5 и 6–9 — каждые 15 мин в течение часа."}]}},{"id":"nursing_gi_t2-087","quiz":{"title":"Клизмы, уход, исследования","questions":[{"text":"Положение пациента для очистительной клизмы:","options":["На левом боку, колени подтянуты к животу","На правом боку","Коленно-локтевое"],"correct":[0],"explanation":"Если пациенту нельзя двигаться — на спине на судне."},{"text":"На какую глубину вводят газоотводную трубку взрослому?","options":["5–10 см","20–30 см","40–50 см"],"correct":[1],"explanation":"И оставляют на 1 ч."},{"text":"Температура лекарственной клизмы:","options":["18–20 °C","25–30 °C","39–40 °C"],"correct":[2],"explanation":"Холоднее — позыв на дефекацию, лекарство не всасывается."},{"text":"Как часто контролируют пульс и АД при желудочно-кишечном кровотечении?","options":["Раз в сутки","Каждые 30 мин","Каждые 3 ч"],"correct":[1],"explanation":"Пульс и АД каждые 30 мин — показатель продолжающегося кровотечения."},{"text":"Что исключают за 3 дня до анализа кала на скрытую кровь?","options":["Мясо и рыбу","Чистку зубов щёткой","Кисломолочные продукты","Белый хлеб"],"correct":[0,1],"explanation":"Мясо, рыба, печень, яйца, томаты, зелёные овощи, гречка дают ложноположительный результат; кровоточивость дёсен — тоже."}]}}]},{"id":"sources","title":"Источники","blocks":[{"id":"src-01","text":{"text":"- Общий уход за больными в терапевтической клинике (учебное пособие; авторы в файле не указаны) — с. 48–76 (питание, диеты, искусственное питание), 99–110 (зондирование, промывание желудка, клизмы, газоотводная трубка), 120–121 (исследование кала), 124–127 (подготовка к исследованиям), 162–172 (уход при болезнях органов пищеварения), 182 (пожилые).\n- Запруднов А.М., Григорьев К.И. Педиатрия с детскими инфекциями. — 2011. — с. 57–63 (АФО органов пищеварения), 306–353 (болезни органов пищеварения и уход).\n- Ежова Н.В. и др. Педиатрия. — 2014. — с. 44–47 (АФО органов пищеварения), 75, 175–177, 189 (зонд у новорождённых и недоношенных), 246–253 (гипотрофия, пилороспазм, пилоростеноз), 285–304 (болезни органов пищеварения и желчевыделения), 443–444 (промывание желудка при отравлениях), 519, 558–559 (зонд при дифтерии и кишечных инфекциях)."}}]}]}$json$::jsonb AS j) v
WHERE "discipline" = 'Сестринское дело' AND "title" = 'Методика зондовых процедур, клизм и ухода при заболеваниях органов пищеварения';
-- +goose StatementEnd
