UPDATE "library_manuals" SET "title" = 'Оксигенотерапия', "annotation" = 'Оксигенотерапия: показания и концентрации, способы подачи кислорода, техника кислородной подушки и носового катетера, увлажнение, баллон, новорождённые и дети, техника безопасности. С методическими указаниями, алгоритмами и самоконтролем.',
  "published" = v.j, "draft" = CASE WHEN "draft_changed" THEN "draft" ELSE v.j END, "updated_at" = now()
FROM (SELECT $json${"sections":[{"id":"nursing_resp2-s01","title":"Методические указания","blocks":[{"id":"nursing_resp2-001","text":{"text":"**Оксигенотерапия** (лат. *oxygenium* — кислород, греч. *therapeia* — лечение) — применение кислорода с лечебной целью: устраняет или уменьшает артериальную гипоксемию. Главное правило: **перед подачей кислорода убедиться в проходимости дыхательных путей** (туалет полости рта, воздуховод, интубация, санация трахеобронхиального дерева)."}},{"id":"nursing_resp2-002","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Главное — методика","text":"Выучить дословно: **правило проходимости дыхательных путей**, почему кислород **увлажняют** и почему **не дают чистым**, алгоритм подачи кислорода через носовой катетер (глубина введения, поток, смена положения), технику безопасности при работе с баллоном. Разбор с ошибками и задачами — в методичке «Методика наблюдения и ухода при заболеваниях органов дыхания. Оксигенотерапия»."}},{"id":"nursing_resp2-003","text":{"text":"**Знать:** показания к оксигенотерапии, концентрации кислорода, способы подачи и их возможности, особенности у новорождённых и детей, технику безопасности."}},{"id":"nursing_resp2-004","text":{"text":"**Уметь:** подать увлажнённый кислород через носовой катетер и из кислородной подушки, подготовить аппарат Боброва, соблюдать технику безопасности при работе с баллоном."}}]},{"id":"nursing_resp2-s02","title":"Показания и концентрации","blocks":[{"id":"nursing_resp2-007","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Нормы учебников — проверьте по действующим рекомендациям","text":"- **Карбоген** при отравлении угарным газом и **спиртовые пеногасители** при отёке лёгких — приёмы прошлых лет; в действующих клинических рекомендациях при отравлении угарным газом — кислород в высокой концентрации и гипербарическая оксигенация.\n- Сейчас дозу кислорода подбирают под контролем **пульсоксиметрии (SpO₂)**.\n- **Кислородная подушка** практически вытеснена концентраторами и централизованной подачей.\n\nОтвечайте по стандарту кафедры."}},{"id":"nursing_resp2-008","text":{"text":"- **Показания:** острая или хроническая дыхательная недостаточность с цианозом, тахикардией, снижением парциального давления кислорода в крови; тяжёлая одышка, особенно в покое. У детей — гипоксия любого происхождения (острая дыхательная недостаточность, циркуляторные расстройства), **кроме гистотоксической**.\n- **Концентрация:** взрослым — смесь 40–80% кислорода; длительная непрерывная оксигенотерапия — постоянная концентрация 24–44%, от нескольких часов до нескольких суток. Всегда стремятся к **минимальной эффективной концентрации обязательно увлажнённого** кислорода.\n- **Особые смеси:** отравление угарным газом — **карбоген** (95% O₂ + 5% CO₂); отёк лёгких — кислород пропускают через **пеногасители** (50–96% этиловый спирт или 10% спиртовой раствор антифомсилана).\n- **Чистый кислород нельзя:** угнетает дыхательный центр, обжигает дыхательные пути, токсичен (сухость во рту, боль в груди, судороги, потеря сознания). Исключение — реанимация: дефибрилляцию проводят на фоне ИВЛ 100% кислородом; при тяжёлой гипоксии у детей нужна концентрация 80–100% через лицевую маску или эндотрахеальную трубку.\n- **Проба с кислородом у детей:** реакция на 45% O₂ — вентиляционная дыхательная недостаточность; только на 100% — нарушение диффузии; нет эффекта даже от 100% — внутрилёгочное шунтирование."}}]},{"id":"nursing_resp2-s03","title":"Способы подачи кислорода","blocks":[{"id":"nursing_resp2-009","table":{"caption":"","header":true,"rows":[{"cells":["Способ","Концентрация O₂","Особенности"]},{"cells":["Кислородная подушка","Малоэффективна — стойкой концентрации не даёт","Прорезиненный мешок 10–75 л с трубкой, краном и мундштуком; 10–25 л хватает на 5–7 мин. Дома и когда нет баллона"]},{"cells":["Носовые катетеры / канюли","Носоглоточный катетер: до 40–60%","Централизованная подача; увлажнение аппаратом Боброва; у детей лучше двойные изогнутые канюли из мягкого пластика"]},{"cells":["Лицевая маска","20–60%; при тяжёлой гипоксии до 80–100%","Закрывает рот и нос; вдыхательный и выдыхательный каналы, дыхательный мешок; увлажнение через аппарат Боброва"]},{"cells":["Кислородная палатка, тент, колпак","До 65%","Для контролируемой оксигенации палатки малопригодны; колпаки и тенты с дозатором и увлажнителем; при крупе — паракислородная палатка с аэрозолями"]},{"cells":["ИВЛ через интубационную (эндотрахеальную) трубку","До 100%","При отсутствии или неэффективности самостоятельного дыхания"]},{"cells":["Постоянное положительное давление (CPAP)","2–3 л/мин дают 25–40%","Новорождённые с дефицитом сурфактанта, отёк лёгких, астматический статус; при одышечно-цианотических приступах при пороках сердца — 6–8 см вод. ст. на выдохе"]},{"cells":["Гипербарическая оксигенация (оксигенобаротерапия)","Кислород под повышенным давлением","Барокамера; в пульмонологии — гнойно-обструктивные болезни лёгких; при гемолитической болезни новорождённого — 0,5–0,8 атм, 2–8 сеансов по 1 в день"]}]}}]},{"id":"nursing_resp2-s04","title":"Техника: кислородная подушка","blocks":[{"id":"nursing_resp2-010","text":{"text":"Оснащение: кислородная подушка, баллон с кислородом, стерильные марлевые салфетки, вода."}},{"id":"nursing_resp2-012","checklist":{"title":"Алгоритм подачи кислорода из кислородной подушки","ordered":true,"steps":["Снять мундштук, открыть кран подушки, соединить трубку с редуктором баллона, медленно открыть вентиль и наполнить подушку. Стоять сбоку от баллона — струя может повредить глаза.","Закрыть кран редуктора и вентиль подушки.","Обработать мундштук салфеткой с 70% спиртом.","Объяснить: вдох через рот, выдох через нос.","Обернуть мундштук 2–3 слоями стерильной марли, смоченной водой (увлажнение).","Вставить мундштук в рот, медленно открыть кран.","Скорость подачи регулировать нажатием на подушку; по мере опорожнения сворачивать её с угла, противоположного мундштуку."]}}]},{"id":"nursing_resp2-s05","title":"Техника: носовой катетер","blocks":[{"id":"nursing_resp2-013","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Методика","text":"Глубина введения — **от крыла носа до мочки (козелка) уха**; конец катетера на 1 см ниже язычка мягкого нёба и виден в зеве. Поток **2–3 л/мин**, кислород **всегда увлажнён**. Каждые 30–60 мин менять положение катетера."}},{"id":"nursing_resp2-014","text":{"text":"Оснащение: кислородный баллон (или централизованная подача), стерильные носовые катетеры, стерильный вазелин (детям — глицерин), трубка, пластырь, аппарат Боброва со стерильной водой."}},{"id":"nursing_resp2-016","checklist":{"title":"Алгоритм подачи кислорода через носовой катетер","ordered":true,"steps":["Смазать стерильный катетер вазелином (у детей — глицерином, чтобы меньше раздражать слизистую).","Ввести по нижнему носовому ходу до задней стенки глотки на глубину от крыла носа до мочки (козелка) уха. Конец должен быть на 1 см ниже язычка мягкого нёба: выше — меньше кислорода во вдыхаемом воздухе, ниже — аэрофагия и растяжение желудка.","Если больной в сознании — попросить открыть рот: при правильном введении конец катетера виден в зеве.","Наружный конец соединить с трубкой системы подачи кислорода, закрепить пластырем к щеке (виску, лбу).","Открыть вентиль дозиметра, подавать кислород 2–3 л/мин, увлажняя через аппарат Боброва.","Каждые 30–60 мин менять положение катетера — профилактика пролежней и пересыхания слизистой."]}}]},{"id":"nursing_resp2-s06","title":"Увлажнение и баллон","blocks":[{"id":"nursing_resp2-017","text":{"text":"- Кислород **всегда увлажняют**: аппарат Боброва (пропускают через стерильную воду) или влажная марля на мундштуке подушки.\n- Баллон: 40 л, 150 атм, **синий** с надписью «Кислород медицинский». Больному кислород подают под давлением 2–3 атм через редуктор с двумя манометрами (давление в баллоне и на выходе)."}}]},{"id":"nursing_resp2-s07","title":"Новорождённые и дети","blocks":[{"id":"nursing_resp2-018","text":{"text":"- **В кувезе:** концентрация увлажнённого кислорода около 30%; подбирают минимальную, при которой исчезают признаки гипоксемии (цианоз, вялость, редкое дыхание с апноэ, брадикардия).\n- **После реанимации:** лицевая маска, головной колпак, носовые и назофарингеальные канюли, интубационная трубка; смесь **увлажнена до 60–80% и подогрета до 32–34 °C**. При риске вторичной асфиксии — оксигенотерапия до и после кормления.\n- **Родзал:** источник сжатого кислорода, регулятор концентрации и потока, обогреватель и увлажнитель, лицевые маски.\n- **Обструктивный бронхит:** успокоить, кислород под тентом или через носовой катетер, тёплое питьё.\n- **Круп (стеноз гортани):** после санации — тент или кислородная палатка с высокой влажностью и аэрозолями (ультразвуковой «холодный туман»).\n- **Астматический статус:** увлажнённый кислород сеансами по 30 мин с перерывом 30 мин; при приступе астмы любой тяжести — по возможности, при тяжёлом — любым доступным методом.\n- **Острая дыхательная недостаточность:** на догоспитальном этапе — кислород под обычным давлением; нет самостоятельного дыхания — ИВЛ маской с мешком («Амбу»): первые 3–5 вдохов 30–35 см вод. ст., далее 20 см вод. ст., 30–50 в минуту."}}]},{"id":"nursing_resp2-s08","title":"Техника безопасности","blocks":[{"id":"nursing_resp2-019","text":{"text":"- Баллоны хранят только в отдельных помещениях; **курить запрещено**; не ставить у источников тепла и света.\n- Сжатый кислород при контакте с жирами и нефтепродуктами **воспламеняется и взрывается**: рядом нельзя промасленную ветошь, одежду, свежую краску; **не смазывать руки кремом** перед работой с баллоном.\n- Соблюдать асептику: катетеры и канюли — стерильные, вода в увлажнителе — стерильная."}}]},{"id":"nursing_resp2-s09","title":"Самоконтроль по теме","blocks":[{"id":"nursing_resp2-020","quiz":{"title":"Оксигенотерапия","questions":[{"text":"Что сделать перед подачей кислорода в первую очередь?","options":["Убедиться в проходимости дыхательных путей","Измерить температуру","Дать пациенту воды"],"correct":[0],"explanation":"Туалет полости рта, воздуховод, санация — иначе кислород не дойдёт до альвеол."},{"text":"Глубина введения носового катетера:","options":["От крыла носа до мочки (козелка) уха","От кончика носа до подбородка","2–3 см"],"correct":[0],"explanation":"Конец катетера должен быть на 1 см ниже язычка мягкого нёба."},{"text":"Скорость подачи кислорода через носовой катетер:","options":["0,5 л/мин","2–3 л/мин","10–15 л/мин"],"correct":[1],"explanation":"С увлажнением через аппарат Боброва."},{"text":"Почему чистый кислород длительно давать нельзя?","options":["Угнетает дыхательный центр","Обжигает дыхательные пути","Он слишком дорогой"],"correct":[0,1],"explanation":"Чистый кислород токсичен; исключение — реанимация и тяжёлая гипоксия у детей."},{"text":"Как часто меняют положение носового катетера?","options":["Раз в сутки","Каждые 30–60 мин","Не меняют"],"correct":[1],"explanation":"Профилактика пролежней и пересыхания слизистой."},{"text":"Цвет баллона с медицинским кислородом:","options":["Синий","Чёрный","Красный"],"correct":[0],"explanation":"Синий с надписью «Кислород медицинский»."},{"text":"Почему нельзя смазывать руки кремом перед работой с баллоном?","options":["Сжатый кислород с жирами воспламеняется и взрывается","Крем пачкает баллон","Крем раздражает кожу"],"correct":[0],"explanation":"Рядом с кислородом — никаких жиров и нефтепродуктов."}]}}]},{"id":"sources","title":"Источники","blocks":[{"id":"nursing_resp2-006","text":{"text":"- Общий уход за больными в терапевтической клинике (учебное пособие; авторы в файле не указаны) — с. 145–148.\n- Запруднов А.М., Григорьев К.И. Педиатрия с детскими инфекциями. — 2011. — с. 164, 174, 219, 223, 231, 243, 256, 501–503.\n- Ежова Н.В. и др. Педиатрия. — 2014. — с. 174, 185, 190–191, 269, 321, 418, 427."}}]}]}$json$::jsonb AS j) v
WHERE "discipline" = 'Сестринское дело' AND "title" = 'Оксигенотерапия: конспект по трём учебникам';
