UPDATE "library_manuals" SET "title" = 'Водный баланс', "annotation" = 'Водный баланс: цели и техника учёта, оценка, нарушения диуреза, отёки, водный баланс и диурез у детей, проба Зимницкого. С методическими указаниями, алгоритмом, ситуационными задачами и самоконтролем.',
  "published" = v.j, "draft" = CASE WHEN "draft_changed" THEN "draft" ELSE v.j END, "updated_at" = now()
FROM (SELECT $json${"sections":[{"id":"nursing_wate1-s01","title":"Методические указания","blocks":[{"id":"nursing_wate1-001","text":{"text":"**Водный баланс** — сопоставление всей поступившей за сутки жидкости (выпитой и введённой парентерально) с суточным диурезом. В норме с мочой выделяется **70–80%** поступившей жидкости; суточный диурез взрослого **1,5–2 л**."}},{"id":"nursing_wate1-002","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Главное — методика","text":"Учёт водного баланса — сестринская манипуляция, от точности которой зависит оценка лечения. Нужно знать дословно **алгоритм учёта**, **формулу ожидаемого диуреза** и уметь **оценить баланс** — отрицательный или положительный. Для детей — формулу суточного диуреза и правила сбора мочи."}},{"id":"nursing_wate1-003","text":{"text":"**Знать:** цели учёта водного баланса и кому он нужен; формулу ожидаемого диуреза; нарушения диуреза; отличия сердечных и почечных отёков; диурез у детей по возрасту."}},{"id":"nursing_wate1-004","text":{"text":"**Уметь:** провести учёт водного баланса и оценить его; рассчитать суточный диурез ребёнка; собрать суточную мочу и мочу по Зимницкому; выявить скрытые отёки."}},{"id":"nursing_wate1-005","checklist":{"title":"Порядок подготовки к занятию","ordered":true,"steps":["Выучить алгоритм учёта водного баланса и формулу ожидаемого диуреза.","Решить пример: поступило 2400 мл — сколько должно выделиться?","Выучить нарушения диуреза (полиурия, олигурия, анурия, ишурия, никтурия) с цифрами.","Выучить формулу суточного диуреза у детей и порядок пробы Зимницкого.","Решить ситуационные задачи и пройти самоконтроль."]}}]},{"id":"nursing_wate1-s02","title":"Зачем и кому","blocks":[{"id":"nursing_wate1-008","text":{"text":"- **Цели:** выявить **скрытые отёки**, определить суточный диурез, оценить эффект лечения, прежде всего мочегонного.\n- **Кому:** сердечная недостаточность (отёки на ранних стадиях скрытые — быстрый прирост массы и снижение диуреза), болезни почек, диарея и обезвоживание, инфузионная терапия, новорождённые в интенсивной терапии, гипотрофия."}}]},{"id":"nursing_wate1-s03","title":"Техника определения","blocks":[{"id":"nursing_wate1-009","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Методика","text":"Запомнить три вещи: **порцию в 6 ч утра не учитывают**, собирают всё до 6 ч следующего утра включительно; **первые блюда считают как 75% жидкости**; пациентов с отёками **ежедневно взвешивают**. Пациенту всё объясняют накануне — без его участия учёт выпитого не получится."}},{"id":"nursing_wate1-010","text":{"text":"**Оснащение:** медицинские весы, чистая сухая банка 2–3 л, два градуированных сосуда (цилиндра), лист учёта водного баланса, температурный лист. Лежачим и получающим мочегонные — судно, мочеприёмник."}},{"id":"nursing_wate1-012","checklist":{"title":"Алгоритм учёта водного баланса","ordered":true,"steps":["Накануне предупредить больного, объяснить правила сбора мочи и записи в листе учёта.","В 6 ч утра разбудить — помочиться в унитаз (или выпустить мочу катетером); эту порцию не учитывают.","Все последующие порции до 6 ч утра следующего дня включительно — в банку.","В течение суток больной или медсестра записывают всю жидкость в мл: выпитую (первые блюда считают как 75% жидкости) и введённую парентерально.","Градуированным сосудом измерить суточную мочу.","Занести данные в температурный лист; больных с отёками ежедневно взвешивать."]}}]},{"id":"nursing_wate1-s04","title":"Оценка","blocks":[{"id":"nursing_wate1-013","callout":{"tone":"MANUAL_CALLOUT_TONE_CLINICAL","title":"Пример расчёта","text":"Пациент выпил 1300 мл (с учётом супа), внутривенно получил 500 мл — всего 1800 мл. Ожидаемый диурез: 1800 × 0,8 = 1440 мл. Выделено 1000 мл — **баланс отрицательный**: жидкость задерживается, сообщить врачу, проверить отёки и массу тела."}},{"id":"nursing_wate1-014","text":{"text":"**Ожидаемый диурез = вся поступившая жидкость × 0,8**"}},{"id":"nursing_wate1-015","text":{"text":"Пример: поступило 2000 мл → должно выделиться ~1600 мл."}},{"id":"nursing_wate1-016","table":{"caption":"","header":true,"rows":[{"cells":["Результат","Критерий","Что означает"]},{"cells":["Отрицательный диурез (баланс)","Выделено меньше 70–80% поступившего","Жидкость задерживается: нарастание отёков, мочегонная терапия неэффективна"]},{"cells":["Положительный диурез (баланс)","Выделено больше ожидаемого (больше выпитого)","Схождение отёков, эффект мочегонных"]}]}},{"id":"nursing_wate1-017","text":{"text":"- **Взвешивание:** быстрое увеличение массы — задержка жидкости. При положительном диурезе масса должна снижаться; если нет — проверить, сколько больной на самом деле пьёт.\n- Дневной диурез в норме преобладает над ночным примерно **4 : 1**."}}]},{"id":"nursing_wate1-s05","title":"Нарушения диуреза","blocks":[{"id":"nursing_wate1-018","table":{"caption":"","header":true,"rows":[{"cells":["Термин","Критерий","Причины"]},{"cells":["Полиурия","> 2000 мл/сут","Обильное питьё, беременность, стресс; схождение отёков; хронический нефрит, пиелонефрит, СД, ХПН"]},{"cells":["Олигурия","≤ 500 мл/сут","Ограничение питья, потливость, нагрузка; нефриты, сердечная недостаточность, шок, ожоги, сдавление мочеточников"]},{"cells":["Анурия","≤ 200 мл/сут до полного отсутствия","Почечная недостаточность, падение АД, препятствие оттоку мочи"]},{"cells":["Ишурия","Не может опорожнить переполненный пузырь","Сужение уретры, атония пузыря; помощь — шум воды, орошение тёплой водой, грелка на надлобковую область, затем катетеризация"]},{"cells":["Никтурия","Ночной диурез преобладает над дневным","Болезни почек, аденома простаты, несахарный диабет; ранний признак почечной патологии"]}]}}]},{"id":"nursing_wate1-s06","title":"Отёки","blocks":[{"id":"nursing_wate1-019","table":{"caption":"","header":true,"rows":[{"cells":["Признак","Сердечные","Почечные"]},{"cells":["Где","Ноги (если ходит); крестец, поясница, лопатки (если лежит)","Утром на лице (параорбитальные), при выраженных — и ноги"]},{"cells":["Кожа","Гладкая, блестящая, натянутая; ямка при надавливании долго не расправляется","—"]},{"cells":["Тяжёлые формы","Асцит, гидроторакс, гидроперикард, анасарка","Анасарка (лицо, руки, ноги, промежность)"]}]}}]},{"id":"nursing_wate1-s07","title":"Водный баланс у детей","blocks":[{"id":"nursing_wate1-020","text":{"text":"- **Новорождённые:** в первые дни 10–20 мл мочи, 4–6 мочеиспусканий; затем диурез резко растёт: 20–25 мочеиспусканий у новорождённых, не менее 15 — у грудных. Суточная моча — **60–65% выпитой жидкости**.\n- **Почасовой диурез новорождённого в интенсивной терапии:** в 1-е сутки 0,3–0,5 мл/кг·ч, на 2–3-и — 1,5–2 мл/кг·ч; диуреза добиваются к 5–6-му часу жизни; частота дыхания, пульс и АД — для профилактики перегрузки жидкостью."}},{"id":"nursing_wate1-021","text":{"text":"**Суточный диурез ребёнка до 10 лет (мл) = 600 + 100 × (n − 1)**"}},{"id":"nursing_wate1-022","text":{"text":"где n — возраст в годах, 600 мл — среднесуточный диурез годовалого. Пример: 5 лет → 1000 мл."}},{"id":"nursing_wate1-023","text":{"text":"- **Измерение у детей:** суточную мочу собирают в стеклянную посуду, измеряют градуированным цилиндром, одновременно учитывают выпитую жидкость; данные — в специальную тетрадь; детей с отёками взвешивают ежедневно.\n- **Суточная моча на анализ (соли, глюкоза):** порцию в 6 ч не учитывают, собирают до 6 ч следующего утра в одну ёмкость, измеряют объём и отправляют 80–100 мл с указанием суточного диуреза.\n- **Проба Зимницкого:** 8 пронумерованных банок; в 6 ч моча — на общий анализ, с 9 ч каждые 3 ч — в отдельную банку (ночью будят), последняя — в 6 ч следующего утра. Определяют объём и плотность каждой порции, дневной и ночной диурез. Условие — **обычный водный режим**, выпитую за день жидкость записывают.\n- **Гломерулонефрит с отёками:** жидкость дозируют по диурезу — **диурез за прошедшие сутки + 300–500 мл, но не менее 15 мл/кг**; в олигурию избегают продуктов, богатых калием.\n- **Обязанности медсестры в нефрологии:** контроль диеты, водного и солевого режима и передач; учёт суточного диуреза и выпитой жидкости; взвешивание (скрытые отёки, масса при гормонотерапии); АД и пульс; выявление расстройств мочеиспускания.\n- **Диарея и обезвоживание:** контроль выпитой и выделенной жидкости, ежедневное взвешивание с записью в температурном листе; восстановление диуреза — признак эффективной регидратации. Расчёт оральной регидратации на 1-м этапе (6 ч): V (мл/ч) = 10 × масса (кг) × % потери массы / 6; поддерживающая — 80–100 мл/кг.\n- **Болезни органов дыхания:** суточный объём жидкости ~100 мл/кг; растворы для оральной регидратации — не более 1/3 этого объёма; достаточное питьё ещё и разжижает мокроту."}}]},{"id":"nursing_wate1-s08","title":"Ситуационные задачи","blocks":[{"id":"nursing_wate1-024","clinicalCase":{"title":"Задача 1. Мочегонная терапия","condition":"Пациент с хронической сердечной недостаточностью получает фуросемид. За сутки выпил 900 мл, съел 400 мл супа, внутривенно получил 200 мл. Выделил 1500 мл мочи. За сутки масса тела снизилась на 0,6 кг.","questions":["Сколько жидкости поступило?","Рассчитайте ожидаемый диурез и оцените баланс.","Эффективна ли мочегонная терапия?"],"answer":"Поступило: 900 + 400 × 0,75 + 200 = **1400 мл** (первые блюда — 75% жидкости).\n\nОжидаемый диурез: 1400 × 0,8 = **1120 мл**. Выделено 1500 мл — больше ожидаемого: **баланс положительный**.\n\nДа: отёки сходят, масса снижается — мочегонная терапия эффективна."}},{"id":"nursing_wate1-025","clinicalCase":{"title":"Задача 2. Ошибка при сборе мочи","condition":"Пациентке назначен учёт водного баланса. Утром в 6 ч она помочилась в банку, а в течение дня записывала только выпитый чай; суп и капельницу не учитывала. Вечером одна порция мочи ушла в унитаз.","questions":["Какие ошибки допущены?","Как они исказят результат?","Как правильно организовать учёт?"],"answer":"**Ошибки:** порцию в 6 ч собрали в банку (её не учитывают); не записаны первые блюда и парентеральная жидкость; одна порция мочи потеряна.\n\nПоступившее занижено, выделенное искажено — оценка баланса неверна.\n\n**Правильно:** накануне объяснить правила; в 6 ч — помочиться в унитаз; все порции до 6 ч следующего утра включительно — в банку; записывать всю выпитую жидкость (первые блюда — 75%) и введённую парентерально; измерить мочу градуированным сосудом; записать в температурный лист; при отёках — ежедневно взвешивать."}},{"id":"nursing_wate1-026","clinicalCase":{"title":"Задача 3. Ребёнок с гломерулонефритом","condition":"Мальчику 6 лет с гломерулонефритом и отёками нужно назначить питьевой режим. За прошедшие сутки диурез — 400 мл; масса тела 20 кг.","questions":["Каким должен быть суточный диурез здорового ребёнка этого возраста?","Сколько жидкости можно дать на следующие сутки?","Какие обязанности у медсестры?"],"answer":"600 + 100 × (6 − 1) = **1100 мл**.\n\nДиурез за прошедшие сутки + 300–500 мл: 400 + 300–500 = **700–900 мл**; не менее 15 мл/кг = 300 мл — условие выполнено. В олигурию избегать продуктов, богатых калием.\n\nКонтроль диеты, водного и солевого режима и передач; учёт суточного диуреза и выпитой жидкости; ежедневное взвешивание; АД и пульс; выявление расстройств мочеиспускания."}}]},{"id":"nursing_wate1-s09","title":"Самоконтроль по теме","blocks":[{"id":"nursing_wate1-027","quiz":{"title":"Водный баланс","questions":[{"text":"Какую порцию мочи не учитывают при определении водного баланса?","options":["Первую, в 6 ч утра","Последнюю, в 6 ч следующего утра","Ночные порции"],"correct":[0],"explanation":"Её выливают; всё последующее до 6 ч следующего утра включительно собирают."},{"text":"Сколько жидкости засчитывают за 400 мл супа?","options":["400 мл","300 мл","200 мл"],"correct":[1],"explanation":"Первые блюда считают как 75% жидкости."},{"text":"Поступило 2000 мл. Ожидаемый диурез:","options":["1000 мл","1600 мл","2000 мл"],"correct":[1],"explanation":"2000 × 0,8 = 1600 мл."},{"text":"Выделено меньше 70–80% поступившего — это:","options":["Отрицательный баланс: жидкость задерживается","Положительный баланс: отёки сходят"],"correct":[0],"explanation":"Отёки нарастают, мочегонные неэффективны."},{"text":"Олигурия — это суточный диурез:","options":["более 2000 мл","не более 500 мл","не более 200 мл"],"correct":[1],"explanation":"Не более 200 мл и до полного отсутствия — анурия."},{"text":"Суточный диурез ребёнка 5 лет:","options":["600 мл","1000 мл","1500 мл"],"correct":[1],"explanation":"600 + 100 × (5 − 1) = 1000 мл."},{"text":"Где появляются почечные отёки?","options":["Утром на лице","Вечером на ногах у ходячих больных","Только на крестце"],"correct":[0],"explanation":"Параорбитальные отёки по утрам; сердечные — на ногах или крестце."}]}}]},{"id":"sources","title":"Источники","blocks":[{"id":"nursing_wate1-007","text":{"text":"- Общий уход за больными в терапевтической клинике: учебное пособие. — с. 159, 174–175.\n- Запруднов А.М., Григорьев К.И. Педиатрия с детскими инфекциями. — М.: ГЭОТАР-Медиа, 2011. — с. 239, 373–375.\n- Ежова Н.В., Русакова Е.М., Кащеева Г.И. Педиатрия. — 2014. — с. 191, 358, 366–369."}}]}]}$json$::jsonb AS j) v
WHERE "discipline" = 'Сестринское дело' AND "title" = 'Водный баланс: конспект по трём учебникам';
-- +goose StatementEnd
-- +goose StatementBegin
UPDATE "library_manuals" SET "title" = 'Физиопроцедуры: методика', "annotation" = 'Простейшие физиопроцедуры: холодный компресс, пузырь со льдом, согревающие компрессы, припарки, грелка, банки, горчичники, горчичные ванны и обёртывания, водолечение, кровопускание, гирудотерапия, особенности у детей. С алгоритмами, выносками об устаревших процедурах, ситуационными задачами и самоконтролем.',
  "published" = v.j, "draft" = CASE WHEN "draft_changed" THEN "draft" ELSE v.j END, "updated_at" = now()
FROM (SELECT $json${"sections":[{"id":"nursing_wate2-s01","title":"Методические указания","blocks":[{"id":"nursing_wate2-001","text":{"text":"**Физиотерапия** — область медицины, изучающая лечебное действие естественных и искусственных физических факторов. Простейшие процедуры (холод, тепло, механическое раздражение кожи) действуют как **сегментарно-рефлекторная отвлекающая терапия**: меняют тонус сосудов и гладкой мускулатуры, стимулируют обмен, улучшают сон и самочувствие."}},{"id":"nursing_wate2-002","table":{"caption":"","header":true,"rows":[{"cells":["Группа","Процедуры","Действие"]},{"cells":["Холод","Холодный компресс, пузырь со льдом","Сужение сосудов, обезболивание, остановка кровотечения"]},{"cells":["Тепло","Согревающие компрессы, припарки, грелка","Расширение сосудов, рассасывание воспаления, снятие спазма"]},{"cells":["Тепло + раздражение кожи","Банки, горчичники, горчичные ванны и обёртывания","Отвлекающее, противовоспалительное"]},{"cells":["Водолечение","Душ, ванны, обтирания, обёртывания","Зависит от температуры воды"]},{"cells":["Кровоизвлечение","Кровопускание, гирудотерапия","Снижение ОЦК и АД; пиявки — ещё и антикоагулянтное (гирудин)"]}]}},{"id":"nursing_wate2-003","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Главное — методика","text":"Медсестру оценивают по тому, **как она выполняет процедуру и знает ли противопоказания**. Алгоритмы — холодный компресс, пузырь со льдом, согревающий компресс, грелка, банки, горчичники, кровопускание, гирудотерапия — вынесены в карточки с шагами. Особое внимание — **безопасности**: ожоги (грелка, спирт, банки), противопоказания тепла при острой боли в животе и кровотечении, наблюдение за ребёнком во время любой процедуры."}},{"id":"nursing_wate2-004","text":{"text":"**Знать:** механизм действия холода, тепла и отвлекающих процедур; показания и противопоказания к каждой процедуре; места постановки банок, горчичников, пиявок; особенности у детей."}},{"id":"nursing_wate2-005","text":{"text":"**Уметь:** поставить холодный и согревающий компресс, пузырь со льдом, грелку, горчичники, банки; подготовить оснащение и ассистировать при кровопускании и гирудотерапии; наблюдать за пациентом во время водных процедур."}},{"id":"nursing_wate2-006","checklist":{"title":"Порядок подготовки к занятию","ordered":true,"steps":["Выучить, чем действие холода отличается от действия тепла, и три стадии реакции на холод.","Выучить противопоказания: к холоду, к грелке, к банкам, к горчичникам.","Выучить алгоритмы по карточкам и отработать на фантоме или друг на друге (компресс, пузырь, грелка, горчичники).","Выучить слои согревающего компресса и их размеры.","Решить ситуационные задачи и пройти самоконтроль."]}}]},{"id":"nursing_wate2-s02","title":"1. Применение холода","blocks":[{"id":"nursing_wate2-009","callout":{"tone":"MANUAL_CALLOUT_TONE_IMPORTANT","title":"Методика","text":"Для каждой процедуры отвечать по схеме: **цель → показания → противопоказания → оснащение → алгоритм → оценка**. Холод и тепло: запомнить, что пузырь со льдом заполняют на 2/3 и делают перерыв 10 мин каждые 30 мин, а грелку заполняют на 2/3 водой около 50 °C и всегда оборачивают полотенцем."}},{"id":"nursing_wate2-010","text":{"text":"Местное охлаждение сужает сосуды кожи и близлежащих органов. **Три стадии реакции:** (1) сужение сосудов — бледность, холодная кожа; (2) рефлекторное расширение — кожа розовая и тёплая; (3) капилляры и венулы расширены, артериолы сужены, кровоток замедлен — кожа багрово-красная, холодная."}},{"id":"nursing_wate2-011","text":{"text":"**Цели:** ограничить воспаление и травматический отёк, остановить (замедлить) кровотечение, обезболить."}},{"id":"nursing_wate2-012","heading":{"text":"Холодный компресс","level":2}},{"id":"nursing_wate2-013","text":{"text":"- **Показания:** первые часы после ушибов и травм, носовое и геморроидальное кровотечение, II период лихорадки.\n- **Противопоказания:** спастические боли в животе, коллапс, шок.\n- **Оснащение:** холодная вода со льдом, марля в несколько слоёв."}},{"id":"nursing_wate2-015","checklist":{"title":"Алгоритм постановки холодного компресса","ordered":true,"steps":["Смочить марлю в холодной воде, слегка отжать.","Наложить на нужный участок.","Менять каждые 2–3 мин по мере согревания."]}},{"id":"nursing_wate2-016","heading":{"text":"Пузырь со льдом","level":2}},{"id":"nursing_wate2-017","text":{"text":"Для более длительного охлаждения; плоский резиновый мешок с широким горлом и крышкой."}},{"id":"nursing_wate2-018","text":{"text":"- **Показания:** первые часы после травмы, ушибы, внутреннее кровотечение, II период лихорадки, начальная стадия некоторых острых заболеваний брюшной полости.\n- **Противопоказания:** спастические боли в животе, коллапс, шок.\n- **Оснащение:** лёд, пузырь, полотенце (стерильная клеёнка)."}},{"id":"nursing_wate2-020","checklist":{"title":"Алгоритм применения пузыря со льдом","ordered":true,"steps":["Заполнить пузырь на 2/3 кусочками льда, вытеснить воздух, плотно закрыть.","Подвесить над участком тела на расстоянии 5–7 см или приложить, обернув полотенцем.","При длительной процедуре — каждые 30 мин перерыв 10 мин; растаявшую воду сливать и добавлять лёд."]}},{"id":"nursing_wate2-021","text":{"text":"У новорождённых при черепно-мозговой гипотермии пузырь со льдом подвешивают над головкой, к ногам кладут грелку (или аппарат «Холод-2»)."}}]},{"id":"nursing_wate2-s03","title":"2. Применение тепла","blocks":[{"id":"nursing_wate2-022","text":{"text":"Местное согревание даёт длительное расширение сосудов и усиление кровообращения. **Цели:** рассасывание воспаления, уменьшение боли (снятие спазма гладкой мускулатуры)."}},{"id":"nursing_wate2-023","heading":{"text":"Согревающие компрессы","level":2}},{"id":"nursing_wate2-024","text":{"text":"Виды: **сухой**, **влажный согревающий**, **влажный горячий**."}},{"id":"nursing_wate2-025","table":{"caption":"","header":true,"rows":[{"cells":["Слой","Материал","Размер"]},{"cells":["Внутренний (на кожу)","Влажная салфетка / марля 6–8 слоёв, хорошо отжатая","Самый маленький"]},{"cells":["Средний (изолирующий)","Вощёная бумага, клеёнка, плёнка","На 2 см больше внутреннего"]},{"cells":["Наружный (утепляющий)","Вата 2–3 см, фланель, шерстяной платок","На 2–3 см больше среднего"]}]}},{"id":"nursing_wate2-026","heading":{"text":"Влажный согревающий компресс","level":2}},{"id":"nursing_wate2-027","text":{"text":"- **Показания:** местные воспаления кожи и подкожной клетчатки, постинъекционные инфильтраты, артриты, травмы (не в первые сутки); у детей — острый отит, ларингит (на шею), бронхит.\n- **Противопоказания:** кожные заболевания (дерматит, гнойнички, аллергические высыпания), высокая лихорадка, злокачественные опухоли, повреждение кожи.\n- **Оснащение:** вода комнатной температуры, слабый раствор уксуса или спирт (этиловый, камфорный), салфетка, вощёная бумага, вата, бинт, полотенце."}},{"id":"nursing_wate2-029","checklist":{"title":"Алгоритм постановки влажного согревающего компресса","ordered":true,"steps":["Приготовить раствор: тёплая вода; уксус — 1 ч. л. 9% на 0,5 л воды; водка, одеколон или 96% спирт, разбавленные водой 1 : 2 (неразбавленный спирт вызывает ожог).","Смочить салфетку, отжать, плотно приложить к коже.","Сверху — вощёная бумага, затем вата; зафиксировать бинтом (не сдавливая).","Через 1,5–2 ч проверить: внутренний слой должен быть влажным и тёплым.","Снять через 8–10 ч (у детей на ухо — 4–8 ч, затем перерыв 1–2 ч и можно повторить), протереть кожу водой или спиртом, вытереть насухо, наложить сухую тёплую повязку."]}},{"id":"nursing_wate2-030","text":{"text":"**Сухой компресс** — ватно-марлевая повязка для согревания и защиты от холода (шея, ухо)."}},{"id":"nursing_wate2-031","text":{"text":"**Влажный горячий компресс** — для местного обезболивания: салфетку смачивают в воде **50–60 °C**, отжимают, прикладывают на **5–10 мин**, накрывают клеёнкой и шерстяной тканью."}},{"id":"nursing_wate2-032","heading":{"text":"Припарки","level":2}},{"id":"nursing_wate2-033","text":{"text":"Прогревание нагретым сыпучим или кашицеобразным веществом в полотняном мешочке. **Сухие** — песок, овёс, льняное семя; **влажные** — отруби, овёс, льняное семя, исландский мох, залитые кипятком до кашицы. Мешочек прикладывают, закрывают клеёнкой, фиксируют, накрывают одеялом."}},{"id":"nursing_wate2-034","text":{"text":"- **Показания:** долго не рассасывающиеся инфильтраты, старые гематомы, радикулит.\n- **Противопоказания:** неясные боли в животе, опухоли, первые сутки после травмы, кровотечения, нарушение кожной чувствительности, бессознательное состояние."}},{"id":"nursing_wate2-035","heading":{"text":"Грелка","level":2}},{"id":"nursing_wate2-036","text":{"text":"Сухая тепловая процедура, болеутоляющее и спазмолитическое средство. Виды: резиновая (водяная, 1–3 л), электрическая (термофор), химическая; при отсутствии — бутылка с горячей водой."}},{"id":"nursing_wate2-037","text":{"text":"- **Показания:** воспалительные инфильтраты, невриты, невралгии; согревание больного (озноб, нарушение периферического кровообращения, коллапс — к ногам).\n- **Противопоказания:** острая боль в животе неясного генеза, острые процессы в брюшной полости (аппендицит, панкреатит, холецистит), опухоли, первые сутки после травмы, кровотечения, инфицированная рана, повреждение кожи, бессознательное состояние.\n- **Оснащение:** резиновая грелка, вода **около 50 °C**, полотенце, вазелин."}},{"id":"nursing_wate2-039","checklist":{"title":"Алгоритм применения грелки","ordered":true,"steps":["Смазать кожу вазелином (профилактика ожога и гиперпигментации при частом применении).","Наполнить грелку на 2/3 горячей водой.","Вытеснить воздух, сжав грелку к горловине; плотно закрыть пробкой.","Проверить на герметичность, перевернув.","Обернуть полотенцем, приложить к участку тела."]}},{"id":"nursing_wate2-040","callout":{"tone":"MANUAL_CALLOUT_TONE_INFO","title":"Дети","text":"недоношенного и ослабленного ребёнка даже негорячая грелка может обжечь — согревать их грелками в кроватке опасно; предпочтителен кувез. Если грелки всё же применяют — не вплотную, а между одеялами или на расстоянии от тела, с контролем температуры."}}]},{"id":"nursing_wate2-s04","title":"3. Банки","blocks":[{"id":"nursing_wate2-041","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"Устаревшие процедуры — сверяйтесь со стандартом кафедры","text":"Банки, горчичники при стенокардии и гипертоническом кризе, горчичные обёртывания в действующих клинических рекомендациях не применяются. Процедуры даны по учебникам — для понимания механизма и экзамена; отвечайте по стандарту кафедры."}},{"id":"nursing_wate2-042","text":{"text":"Стеклянные сосуды **30–70 мл** с утолщёнными краями. **Механизм:** пламя создаёт разрежение → банка присасывается → прилив крови и лимфы, рефлекторное улучшение кровообращения и трофики органов. Капилляры разрываются, образуется кровоподтёк; продукты распада крови действуют как биологически активные вещества (аналог аутогемотерапии)."}},{"id":"nursing_wate2-043","text":{"text":"- **Показания:** бронхит, пневмония, неврит, межрёберная невралгия, миозит.\n- **Противопоказания:** высокая температура, злокачественные опухоли, кровохарканье и лёгочное кровотечение (или угроза), активный туберкулёз, заболевания кожи и крови, резкое истощение, судороги, сильное возбуждение, бессознательное состояние, резкая болезненность кожи.\n- **Места:** где выражен мышечный и жировой слой — грудная клетка (межлопаточная, подлопаточная и подмышечная области, симметрично). **Нельзя:** область сердца, молочные железы, позвоночник, родимые пятна.\n- **Оснащение:** лоток с банками (10–16 шт.), вазелин, 96% этиловый спирт, фитиль (металлический зонд с ватой) или зажим Кохера, спички, вата, полотенце, одеяло."}},{"id":"nursing_wate2-045","checklist":{"title":"Алгоритм постановки банок","ordered":true,"steps":["Банки вымыть горячей водой, вытереть насухо, проверить края на сколы.","Уложить больного на живот, голова повёрнута в сторону, руки обхватывают подушку. Волосы при необходимости сбрить.","Нанести на кожу тонкий слой вазелина (герметичность и защита от ожога).","Фитиль смочить спиртом и отжать о край флакона; флакон закрыть и отставить. Эфир применять категорически запрещено!","Поджечь фитиль; в правую руку — фитиль, в левую — 1–2 банки.","Внести пламя в банку на 1–3 с, не касаясь и не накаляя края (нагревать только воздух), быстро и энергично приложить к коже.","Укрыть одеялом; оставить на 10–15 мин (детям — 7–10 мин). При правильной постановке кожа становится ярко-красной, затем багровой.","Снятие: пальцем надавить на кожу у края банки, дно отклонить в противоположную сторону — воздух входит, банка отделяется.","Вытереть вазелин полотенцем (или тампоном со спиртом), укрыть; покой не менее 1 ч (детей тепло одеть и укрыть на 30–40 мин).","Банки промыть горячей водой и вытереть."]}},{"id":"nursing_wate2-046","callout":{"tone":"MANUAL_CALLOUT_TONE_INFO","title":"Дети","text":"банки — **не раньше 7 лет**, с учётом тяжести процесса; младшим школьникам — банки меньшего размера (стандартные — ø 5 см); вместо вазелина можно детский крем; число банок зависит от возраста; медсестра успокаивает ребёнка и не отходит."}}]},{"id":"nursing_wate2-s05","title":"4. Горчичники","blocks":[{"id":"nursing_wate2-047","text":{"text":"Действующее вещество — **эфирное горчичное (аллиловое) масло**, выделяется при **40–45 °C** (при более высокой температуре разрушается). Раздражает рецепторы кожи, вызывает гиперемию и расширение сосудов глубже лежащих органов — болеутоляющий и рассасывающий эффект."}},{"id":"nursing_wate2-048","text":{"text":"- **Стандарт:** листы 8 × 12,5 см (также 12 × 18 и 3 × 4 см) или пакетики из фильтровальной бумаги; срок годности 8–10 мес. **Пригодный** — острый запах горчичного масла, не осыпается.\n- **Показания:** воспаления ВДП (ринит, фарингит, трахеит), бронхит, пневмония, миозит, невралгия, стенокардия, гипертонический криз.\n- **Противопоказания:** заболевания кожи (пиодермия, нейродермит, экзема), лихорадка **выше 38 °C**, лёгочное кровотечение или угроза его, злокачественные опухоли, аллергия на горчицу."}},{"id":"nursing_wate2-049","table":{"caption":"","header":true,"rows":[{"cells":["Место постановки","При чём"]},{"cells":["Затылок","Острый ринит, гипертонический криз"]},{"cells":["Верхняя часть грудины","Острый трахеит"]},{"cells":["Межлопаточная и подлопаточная области","Бронхит, пневмония"]},{"cells":["Область сердца","Стенокардия"]},{"cells":["Икроножные мышцы","Острое воспаление ВДП, отит (рефлекторная терапия)"]}]}},{"id":"nursing_wate2-050","text":{"text":"Только на неповреждённую кожу; **нельзя** на молочные железы, соски, позвоночник, родимые пятна."}},{"id":"nursing_wate2-051","text":{"text":"**Оснащение:** вода 40–45 °C, лоток, горчичники, полотенце, фланелевая пелёнка, одеяло, салфетки."}},{"id":"nursing_wate2-053","checklist":{"title":"Алгоритм постановки горчичников","ordered":true,"steps":["Уложить больного удобно, осмотреть кожу; проверить годность горчичников.","Погрузить горчичник на 5–10 с в воду не выше 45 °C.","Приложить стороной с горчицей к коже, плотно прижать (при чувствительной коже и у детей грудного и раннего возраста — через марлю или пелёнку).","Укрыть полотенцем, затем одеялом.","Держать 10–15 мин (снять через 5–10 мин после появления жжения); больной должен ощущать тепло и лёгкое жжение, кожа — покраснеть. Дольше — риск ожога. У детей кожу осматривают каждые 2–3 мин и снимают при стойком покраснении.","Снять, протереть кожу влажной тёплой салфеткой, вытереть насухо (детям — смазать кремом или растительным маслом), укрыть одеялом."]}}]},{"id":"nursing_wate2-s06","title":"5. Горчичные ванны и обёртывания","blocks":[{"id":"nursing_wate2-054","table":{"caption":"","header":true,"rows":[{"cells":["Процедура","Приготовление","Время","Применение"]},{"cells":["Горчичная ванна (взрослые)","50 г порошка на 10 л воды","20–30 мин","Общая — простуда; ножная — гипертоническая болезнь"]},{"cells":["Горячие ножные / ручные ванны (дети)","Вода с 37 °C постепенно до 40–41 °C; при переносимости 3–5 г горчицы на 1 л","10–15 мин, лучше перед сном","Ринит, ларингит, бронхит (рефлекторная терапия); ранний возраст — тёплые ванны 37,5 °C"]},{"cells":["Горчичное обёртывание (дети)","100 г сухой горчицы + 2 л воды ≥ 80 °C, отстоять 3–4 мин, слить жидкую часть","20–25 мин","Отвлекающее, успокаивающее, потогонное"]}]}},{"id":"nursing_wate2-055","text":{"text":"**Техника обёртывания:** пелёнку или простыню смочить в растворе, отжать, обернуть грудную клетку от ключиц до пупка → сверху фланелевая пелёнка и шерстяное одеяло → 20–25 мин, периодически поить → снять, омыть кожу водой 34–36 °C, вытереть, тепло одеть и уложить. Повторяют через день, **не более 2–3 раз** за болезнь."}},{"id":"nursing_wate2-056","text":{"text":"После горчичной ванны — омыть тёплой водой, вытереть, укутать. Варианты рефлекторной терапии у детей: сухая горчица в носки, парафиновые и озокеритовые «сапожки»."}},{"id":"nursing_wate2-057","text":{"text":"**Противопоказания:** высокая лихорадка, сердечно-сосудистая недостаточность, чувствительность к горчице, заболевания кожи, лёгочное кровотечение, опухоли, активный туберкулёз, бессознательное состояние."}}]},{"id":"nursing_wate2-s07","title":"6. Водолечение (бальнеотерапия)","blocks":[{"id":"nursing_wate2-058","text":{"text":"Душ, ванны, обливания, обтирания, влажные обёртывания."}},{"id":"nursing_wate2-059","table":{"caption":"","header":true,"rows":[{"cells":["Вода","Температура","Эффект"]},{"cells":["Холодная / прохладная","до 20 / 20–30 °C","Спазм сосудов кожи, ↓ ЧСС, ↑ АД, ↑ тонус мышц; закаливание, стимуляция ЦНС и обмена"]},{"cells":["Индифферентная","34–36 °C","Седативный, расслабляющий"]},{"cells":["Тёплая / горячая","37–39 / свыше 40 °C","Расширение сосудов кожи, ↑ ЧСС, ↓ АД, ↓ мышечный тонус, ↑ потоотделение"]}]}},{"id":"nursing_wate2-060","text":{"text":"- **Виды ванн:** гигиенические и лечебные; общие и местные; жемчужные, пенистые, вибрационные и вихревые, ароматические (хвойные, шалфейные), минеральные (сероводородные).\n- **По длительности:** кратковременные (до 5 мин), средние (10–20 мин), длительные (до нескольких часов).\n- **Противопоказания:** тяжёлый атеросклероз, сердечная недостаточность, гипертонический криз, нарушение мозгового и коронарного кровообращения, активный туберкулёз.\n- Во время процедуры — постоянное наблюдение: из-за роста АД, ЧСС и ЧДД состояние может внезапно ухудшиться; больного в ванне не оставляют одного."}}]},{"id":"nursing_wate2-s08","title":"7. Кровопускание","blocks":[{"id":"nursing_wate2-061","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"По действующим рекомендациям","text":"При отёке лёгких и гипертоническом кризе кровопускание в действующих клинических рекомендациях не применяется; лечебное кровопускание (флеботомия) сохраняется при полицитемии. Выполняет врач, медсестра готовит оснащение и ассистирует."}},{"id":"nursing_wate2-062","text":{"text":"Удаление части крови для снижения ОЦК, артериального и венозного давления. Одномоментно — **200–400 мл**, медленно (риск обморока, падения АД)."}},{"id":"nursing_wate2-063","text":{"text":"- **Показания:** острая левожелудочковая недостаточность (отёк лёгких без шока и коллапса), гипертонический криз, лёгочная гипертензия, полицитемия, отравления ядами, долго задерживающимися в крови.\n- **Противопоказания:** гипотония, гиповолемия, анемия, выраженные нарушения свёртывания, желтуха.\n- **Оснащение:** иглы для венепункции, жгут, градуированная ёмкость, стерильные салфетки, спирт, валик с клеёнкой, перчатки."}},{"id":"nursing_wate2-065","checklist":{"title":"Алгоритм кровопускания","ordered":true,"steps":["Под локтевой сгиб — валик с клеёнкой и стерильной салфеткой.","Место обработать спиртом (йод нельзя); руки — мытьё, спирт, перчатки.","Жгут выше локтевого сгиба на 1–3 мин (пульс сохранён, пережаты только вены).","Венепункция по току крови, срезом вверх; жгут не снимать.","После выведения 200–400 мл извлечь иглу, снять жгут, наложить стерильную салфетку и асептическую повязку."]}}]},{"id":"nursing_wate2-s09","title":"8. Гирудотерапия","blocks":[{"id":"nursing_wate2-066","callout":{"tone":"MANUAL_CALLOUT_TONE_WARNING","title":"По действующим рекомендациям","text":"В действующих клинических рекомендациях по артериальной гипертензии и ИБС гирудотерапия не предусмотрена. Раздел дан по учебнику; отвечайте по стандарту кафедры."}},{"id":"nursing_wate2-067","text":{"text":"Применение медицинских пиявок (*Hirudo medicinalis*): местное кровоизвлечение и снижение свёртываемости. Со слюной поступают **гирудин** (антикоагулянт), гистаминоподобные вещества и гиалуронидаза, поэтому процедура по сути медикаментозная."}},{"id":"nursing_wate2-068","text":{"text":"- **Показания:** гипертонический криз и АГ, ИБС (стенокардия, инфаркт), венозный застой в печени, тромбозы и тромбофлебиты, геморрой.\n- **Противопоказания:** анемия, сниженная свёртываемость, приём антикоагулянтов, гипотония, гнойно-септические и аллергические заболевания, повышенная чувствительность кожи, беременность.\n- **Осложнения:** зуд (смазать смесью нашатырного спирта и вазелинового масла 1 : 1); кровотечение при постановке на вену (давящая повязка); пиодермия, фурункулёз; кровоизлияния в клетчатку."}},{"id":"nursing_wate2-069","text":{"text":"**Характеристики:** одна пиявка высасывает **10–15 мл** крови за 20–90 мин; ранка кровоточит 6–24 ч (ещё 10–40 мл); одномоментно ставят **8–10 пиявок**. Хранят в чистой (отстоянной сутки) воде при 10–18 °C в банках под марлей, в темноте, воду меняют ежедневно. **Здоровая пиявка:** гладкое блестящее тело, упруго сокращается при прикосновении, сразу присасывается, активна. **Пиявку используют однократно!**"}},{"id":"nursing_wate2-070","table":{"caption":"","header":true,"rows":[{"cells":["Место постановки","При чём"]},{"cells":["Сосцевидный отросток, 1 см кзади от ушной раковины","АГ, тромбоз мозговых сосудов"]},{"cells":["III–V межреберья, 1 см кнаружи от левого края грудины","Стенокардия, инфаркт"]},{"cells":["Правое подреберье","Венозный застой в печени"]},{"cells":["По ходу вены, 1 см в стороны, через 5 см в шахматном порядке","Тромбофлебит"]},{"cells":["Вокруг копчика","Геморрой"]}]}},{"id":"nursing_wate2-071","text":{"text":"Нельзя ставить там, где видны подкожные вены или близко лежат артерии."}},{"id":"nursing_wate2-072","text":{"text":"**Оснащение:** чистая пробирка (банка), стерильные лоток и пинцет, спирт, 5% йод, перекись водорода, раствор глюкозы, формалин или нашатырный спирт, горячая вода, стерильные салфетки, тампоны, перевязочный материал."}},{"id":"nursing_wate2-074","checklist":{"title":"Алгоритм гирудотерапии с кровоизвлечением (до самостоятельного отпадения)","ordered":true,"steps":["Уложить или усадить больного в зависимости от места аппликации.","Кожу побрить, протереть спиртом (перекисью), затем несколько раз тампоном с горячей водой; участок смочить раствором глюкозы (лучше присасывается).","Отобрать пиявок на 2–3 больше нужного — сачком или ладонью. Пинцетом брать нельзя (паралич пиявки).","Поместить пиявку в пробирку и поднести её под наклоном к коже, направляя тампоном с горячей водой.","Когда пиявка присосётся (волнообразные движения) — убрать пробирку, под заднюю присоску подложить салфетку.","Располагать свободно, не внахлёст; уснувшую протереть ватой с тёплой водой. Отрывать нельзя — насосавшись, отпадают сами.","Наложить сухую асептическую повязку с большим количеством гигроскопической ваты (при промокании — подбинтовать), смена через сутки.","Пиявок уничтожить в формалине (нашатырном спирте)."]}},{"id":"nursing_wate2-075","text":{"text":"**Без кровоизвлечения:** пункты 1–5, затем снять пиявку, смазав место присасывания спиртом, йодом, 10% кальция хлоридом или 10% натрия хлоридом → сухая асептическая повязка → уничтожить пиявок."}},{"id":"nursing_wate2-076","text":{"text":"Ранки заживают за 2–3 дня. Если кровотечение продолжается после снятия повязки — давящая повязка или раствор перманганата калия; без кровотечения — обработать йодом, спиртом или перекисью и наложить сухую повязку."}}]},{"id":"nursing_wate2-s10","title":"9. Прочее у детей","blocks":[{"id":"nursing_wate2-077","text":{"text":"- **Пластырь (перцовый, противокашлевый):** кожу обезжирить спиртом, одеколоном, вытереть насухо, снять защитную плёнку, наложить и прижать; при кашле — на нижнюю часть грудины; держать по чувствительности кожи, **не более 1 суток**.\n- **Аппаратная физиотерапия** (по назначению врача, в физиокабинете): УВЧ, УФО, электрофорез, индуктотермия; в стадии стихания воспаления и в восстановительном периоде.\n- Обязанности медсестры пульмонологического отделения включают постановку банок, горчичников, согревающих компрессов, пластыря и подготовку к физиопроцедурам; во время любой процедуры ребёнка не оставляют без присмотра."}}]},{"id":"nursing_wate2-s11","title":"Ситуационные задачи","blocks":[{"id":"nursing_wate2-078","clinicalCase":{"title":"Задача 1. Боль в животе и грелка","condition":"Пациентка 40 лет пожаловалась на острую боль в правой половине живота, тошноту. Соседка по палате советует положить грелку «чтобы отпустило» и просит медсестру её принести.","questions":["Можно ли положить грелку?","Почему?","Что должна сделать медсестра?"],"answer":"**Нельзя.** Острая боль в животе неясного генеза и острые процессы в брюшной полости (аппендицит, панкреатит, холецистит) — противопоказания к грелке.\n\nТепло усиливает воспаление и может смазать картину болезни, затруднив диагностику.\n\nУложить пациентку, немедленно сообщить врачу; до осмотра — без грелок, обезболивающих, еды и питья."}},{"id":"nursing_wate2-079","clinicalCase":{"title":"Задача 2. Согревающий компресс на ухо","condition":"Ребёнку 4 лет с острым отитом назначен влажный согревающий компресс на ухо. Мама принесла 96% спирт и предлагает смочить им марлю.","questions":["Можно ли использовать неразбавленный спирт?","Опишите слои компресса.","Сколько держать компресс у ребёнка и как проверить правильность постановки?"],"answer":"Нет — неразбавленный спирт вызывает **ожог**; спирт разводят водой 1 : 2.\n\nВнутренний слой — марля 6–8 слоёв, смоченная и хорошо отжатая (самый маленький); средний — вощёная бумага или плёнка, на 2 см больше; наружный — вата 2–3 см, на 2–3 см больше среднего; зафиксировать бинтом, не сдавливая.\n\nНа ухо ребёнку — **4–8 ч**, затем перерыв 1–2 ч. Через 1,5–2 ч проверить: внутренний слой должен быть влажным и тёплым. После снятия — протереть кожу, вытереть насухо, наложить сухую тёплую повязку."}},{"id":"nursing_wate2-080","clinicalCase":{"title":"Задача 3. Пузырь со льдом","condition":"После ушиба коленного сустава пациенту назначен пузырь со льдом. Медсестра заполнила пузырь доверху, положила прямо на кожу и оставила на 2 ч.","questions":["Какие ошибки допущены?","Чем они опасны?","Опишите правильную методику."],"answer":"**Ошибки:** пузырь заполнен доверху (нужно на 2/3), воздух не вытеснен; лёд прямо на коже без полотенца; нет перерывов.\n\nПереохлаждение и обморожение кожи; плохое прилегание пузыря.\n\n**Правильно:** заполнить пузырь на 2/3 кусочками льда, вытеснить воздух, плотно закрыть; приложить, обернув полотенцем (или подвесить на 5–7 см над кожей); каждые 30 мин — перерыв 10 мин; растаявшую воду сливать, добавлять лёд."}},{"id":"nursing_wate2-081","clinicalCase":{"title":"Задача 4. Горчичники","condition":"Пациенту с бронхитом назначены горчичники. Температура тела 38,6 °C. Медсестра достала горчичники, которые осыпаются и почти не пахнут.","questions":["Можно ли ставить горчичники сейчас?","Пригодны ли эти горчичники?","Где ставят горчичники при бронхите и сколько держат?"],"answer":"Нет: лихорадка **выше 38 °C** — противопоказание.\n\nНет: пригодный горчичник имеет острый запах горчичного масла и не осыпается.\n\nНа межлопаточную и подлопаточную области; горчичник погружают на 5–10 с в воду не выше 45 °C (горчичное масло выделяется при 40–45 °C, при более высокой температуре разрушается), держат 10–15 мин — до тепла, лёгкого жжения и покраснения кожи."}}]},{"id":"nursing_wate2-s12","title":"Самоконтроль по теме","blocks":[{"id":"nursing_wate2-082","quiz":{"title":"Холод и тепло","questions":[{"text":"Как часто меняют холодный компресс?","options":["Каждые 2–3 мин","Каждые 30 мин","Раз в час"],"correct":[0],"explanation":"По мере согревания."},{"text":"На сколько заполняют пузырь со льдом?","options":["Доверху","На 2/3","На 1/3"],"correct":[1],"explanation":"И вытесняют воздух."},{"text":"Режим при длительном применении пузыря со льдом:","options":["Каждые 30 мин — перерыв 10 мин","Без перерыва до таяния льда","Каждые 5 мин — перерыв 30 мин"],"correct":[0],"explanation":"Растаявшую воду сливают, добавляют лёд."},{"text":"Температура воды для резиновой грелки:","options":["20–25 °C","около 50 °C","90–100 °C"],"correct":[1],"explanation":"Грелку заполняют на 2/3, вытесняют воздух, оборачивают полотенцем."},{"text":"Через сколько снимают влажный согревающий компресс у взрослого?","options":["Через 30 мин","Через 8–10 ч","Через сутки"],"correct":[1],"explanation":"У детей на ухо — 4–8 ч."}]}},{"id":"nursing_wate2-083","quiz":{"title":"Банки, горчичники, кровоизвлечение","questions":[{"text":"Какое вещество запрещено для фитиля при постановке банок?","options":["Эфир","96% этиловый спирт"],"correct":[0],"explanation":"Эфир категорически запрещён."},{"text":"Как снимают банку?","options":["Надавить пальцем на кожу у края банки, дно отклонить в противоположную сторону","Резко потянуть банку вверх","Повернуть банку вокруг оси"],"correct":[0],"explanation":"Воздух входит под банку, и она отделяется."},{"text":"С какого возраста детям ставят банки?","options":["С 1 года","С 3 лет","Не раньше 7 лет"],"correct":[2],"explanation":"С учётом тяжести процесса."},{"text":"Почему пиявку нельзя брать пинцетом?","options":["Наступает паралич пиявки","Пинцет нестерильный","Пиявка раздавится"],"correct":[0],"explanation":"Пиявку берут сачком или ладонью."},{"text":"Чем обрабатывают кожу перед кровопусканием?","options":["Спиртом","Йодом"],"correct":[0],"explanation":"Йод при кровопускании нельзя."},{"text":"Сколько раз используют медицинскую пиявку?","options":["Однократно","До 3 раз","Пока активна"],"correct":[0],"explanation":"После процедуры пиявок уничтожают."}]}}]},{"id":"sources","title":"Источники","blocks":[{"id":"nursing_wate2-008","text":{"text":"- Общий уход за больными в терапевтической клинике: учебное пособие. — гл. 7, с. 89–98.\n- Запруднов А.М., Григорьев К.И. Педиатрия с детскими инфекциями. — М.: ГЭОТАР-Медиа, 2011. — с. 111, 144, 222–223, 243–246.\n- Ежова Н.В., Русакова Е.М., Кащеева Г.И. Педиатрия. — 2014. — с. 198, 260, 268, 275–276."}}]}]}$json$::jsonb AS j) v
